#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio2_line = NULL;
struct gpiod_line *gpio3_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio2_line, struct gpiod_line **gpio3_line);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio2_line, struct gpiod_line *gpio3_line);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, gpio2_line, gpio3_line);
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio2_line, struct gpiod_line **gpio3_line) {
    int ret;

    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 2
    *gpio2_line = gpiod_chip_get_line(*chip, GPIO_2);
    if (!*gpio2_line) {
        perror("Error getting GPIO 2 line");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 3
    *gpio3_line = gpiod_chip_get_line(*chip, GPIO_3);
    if (!*gpio3_line) {
        perror("Error getting GPIO 3 line");
        gpiod_line_release(*gpio2_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(*gpio2_line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 2 for output");
        gpiod_line_release(*gpio3_line);
        gpiod_line_release(*gpio2_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_output(*gpio3_line, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 3 for output");
        gpiod_line_release(*gpio2_line);
        gpiod_line_release(*gpio3_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Function to get the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio2_line, struct gpiod_line *gpio3_line) {
    if (gpio2_line) {
        gpiod_line_release(gpio2_line);
    }
    if (gpio3_line) {
        gpiod_line_release(gpio3_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int ret;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &gpio2_line, &gpio3_line) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1
        if (set_gpio_value(gpio2_line, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO 2 to 1. Continuing.\n");
        }

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Print the time and GPIO 2 state
        printf("%s - GPIO 2: 1\n", time_string);

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO 2 to 0
        if (set_gpio_value(gpio2_line, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO 2 to 0. Continuing.\n");
        }

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Print the time and GPIO 2 state
        printf("%s - GPIO 2: 0\n", time_string);

        // Wait for 2 seconds
        sleep(2);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2;
struct gpiod_line *line3;

// Function prototypes
int set_gpio_state(int gpio, int state);
int get_gpio_state(int gpio);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    struct gpiod_line *line;

    if (gpio == GPIO_2) {
        line = line2;
    } else if (gpio == GPIO_3) {
        line = line3;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
        return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state: %d\n", gpio, ret);
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio) {
    struct gpiod_line *line;

    if (gpio == GPIO_2) {
        line = line2;
    } else if (gpio == GPIO_3) {
        line = line3;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %d\n", gpio, value);
        return -1;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO %d line\n", GPIO_2);
        gpiod_chip_close(chip);
        return 1;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Error getting GPIO %d line\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line2, "my_program", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_2);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line3, "my_program", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_3);
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1
        if (set_gpio_state(GPIO_2, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 2 state\n");
            break;
        }
        printf("GPIO 2 set to 1\n");

        // Set GPIO 3 to 0
        if (set_gpio_state(GPIO_3, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 3 state\n");
            break;
        }
        printf("GPIO 3 set to 0\n");

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Cleanup (should not reach here unless an error occurred)
    gpiod_line_release(line2);
    gpiod_line_release(line3);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define VALID_STATE_MIN 0
#define VALID_STATE_MAX 1

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to set the GPIO state
int set_gpio_state(int state) {
    int ret;

    if (state < VALID_STATE_MIN || state > VALID_STATE_MAX) {
        fprintf(stderr, "Error: Invalid GPIO state: %d\n", state);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to set GPIO state to %d: %d\n", state, ret);
        return -1;
    }

    return 0;
}

// Function to get the current time in seconds
double get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

int main() {
    int state = 0;
    double start_time, current_time;
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip '%s'\n", GPIO_CHIP);
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for output
    ret = gpiod_line_request_output(line, "example", 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output: %d\n", GPIO_PIN, ret);
        gpiod_chip_close(chip);
        return 1;
    }

    start_time = get_current_time();

    // Main loop
    while (!terminate) {
        current_time = get_current_time();

        if (current_time - start_time >= 5.0) {
            if (set_gpio_state(state) == 0) {
                printf("GPIO %d set to %d\n", GPIO_PIN, state);
            } else {
                fprintf(stderr, "Error: Failed to set GPIO state\n");
            }

            state = !state; // Toggle the state
            start_time = current_time;
        }

        usleep(100000); // Sleep for 100ms to reduce CPU usage
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int fd, uint16_t value) {
    uint8_t buf[3];
    buf[0] = (value >> 8) & 0xFF; // MSB
    buf[1] = value & 0xFF;      // LSB

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int16_t read_ads1115(int fd) {
    uint8_t buf[2];

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 ADC Reader\n");

    while (1) {
        // Configure the ADS1115 for single-shot conversion
        uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

        if (write_ads1115(i2c_fd, config) < 0) {
            fprintf(stderr, "Error writing config register\n");
            break;
        }

        // Wait for the conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        int16_t reading = read_ads1115(i2c_fd);
        if (reading < 0) {
            fprintf(stderr, "Error reading conversion result\n");
            break;
        }

        // Print the reading to standard output
        printf("ADC Reading: %d\n", reading);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Close the I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define TOBJ1_REG 0x07
#define TOBJ2_REG 0x06
#define AMBIENT_REG 0x05

int i2c_fd = -1; // Global file descriptor for I2C

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
        printf("I2C device closed.\n");
    }
    exit(0);
}

// Function to read a single byte from the I2C device
int read_byte(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }

    return (int)data;
}

// Function to read a 16-bit word from the I2C device
int read_word(int fd, uint8_t reg) {
    uint8_t data[2];
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    return (int16_t)((data[1] << 8) | data[0]);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    printf("MLX90614 sensor reader started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read temperature data
        int tobj1 = read_word(i2c_fd, TOBJ1_REG);
        int tobj2 = read_word(i2c_fd, TOBJ2_REG);
        int ambient = read_word(i2c_fd, AMBIENT_REG);

        if (tobj1 == -1 || tobj2 == -1 || ambient == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Convert to Celsius (example formula, adjust as needed)
        float temp1 = (float)tobj1 * 0.02 - 273.15;
        float temp2 = (float)tobj2 * 0.02 - 273.15;
        float temp_amb = (float)ambient * 0.02 - 273.15;

        // Print the temperature readings
        printf("T1: %.2f C, T2: %.2f C, Ambient: %.2f C\n", temp1, temp2, temp_amb);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for output
    ret = gpiod_line_request_output(line, "output", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO pin HIGH
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        perror("Error setting GPIO pin HIGH");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to HIGH\n", GPIO_PIN);

    // Wait for a while (e.g., 5 seconds)
    sleep(5);

    // Set the GPIO pin LOW
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        perror("Error setting GPIO pin LOW");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to LOW\n", GPIO_PIN);

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("GPIO %d released and GPIO chip closed.\n", GPIO_PIN);

    return 0;
}

