#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Generate a sequence of duty cycles
        for (duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle += 100) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Setting duty cycle to %d\n", duty_cycle);
            sleep(0.5);
        }

        // Reverse the sequence
        for (duty_cycle = PWM_RANGE; duty_cycle >= 0; duty_cycle -= 100) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Setting duty cycle to %d\n", duty_cycle);
            sleep(0.5);
        }
    }

    // Clean up and terminate pigpio
    gpioPWM(GPIO_PIN, 0); // Set duty cycle to 0 before exiting
    gpioTerminate();

    printf("PWM control stopped.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for trigger and echo
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define timeout in microseconds
#define TIMEOUT 500000 // 0.5 seconds

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to measure distance using HC-SR04
float measure_distance() {
    long long start_tick, end_tick, diff_tick;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo to start
    int timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_counter < TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout_counter = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_counter < TIMEOUT) {
        gpioDelay(1);
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    // Calculate the pulse duration in microseconds
    diff_tick = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (pulse_duration * speed_of_sound) / 2
    // distance = (pulse_duration * 34300 cm/s) / 2
    // distance = pulse_duration * 17150 cm/s
    float distance = (float)diff_tick / 1000000.0 * 34300.0 / 2.0;

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance >= 0) {
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
        }

        sleep(60); // Wait 60 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x28

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

// Function to write a 16-bit value to an ADS1115 register
int write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an ADS1115 register
int read_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device (read address)");
        return -1;
    }

    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to read the ADC value from the ADS1115
int read_adc(int fd) {
    uint16_t config;

    // Configure the ADS1115 for single-ended AIN0, +/-4.096V range, 128 SPS, single-shot mode
    config = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;

    if (write_register(fd, ADS1115_REG_CONFIG, config) != 0) {
        fprintf(stderr, "Failed to configure ADS1115\n");
        return -1;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion result
    uint16_t adc_value;
    if (read_register(fd, ADS1115_REG_CONVERT, &adc_value) != 0) {
        fprintf(stderr, "Failed to read ADC value\n");
        return -1;
    }

    return adc_value;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    struct timespec sleep_time = {5, 0}; // 5 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 ADC reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!stop_flag) {
        int adc_value = read_adc(i2c_fd);

        if (adc_value >= 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Close the I2C device
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
