    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define NUM_CYCLES 3

struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int i, ret;
    int state = 1; // Start with HIGH
    time_t start_time, current_time;
    double elapsed_time;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for output
    ret = gpiod_line_request_output(line, "example", 0); // Initial state LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d (BCM) is now under program control.\n", GPIO_PIN);

    // Main loop for 3 cycles
    for (i = 0; i < NUM_CYCLES; i++) {
        time(&start_time);

        // First cycle: HIGH for 1 second, LOW for 1 second
        if (i == 0) {
            printf("Cycle %d: Setting HIGH for 1 second...\n", i + 1);
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Error setting GPIO HIGH");
                goto cleanup;
            }
            sleep(1);

            printf("Cycle %d: Setting LOW for 1 second...\n", i + 1);
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Error setting GPIO LOW");
                goto cleanup;
            }
            sleep(1);
        }
        // Second cycle: LOW for 1 second, HIGH for 1 second
        else if (i == 1) {
            printf("Cycle %d: Setting LOW for 1 second...\n", i + 1);
            if (gpiod_line_set_value(line, 0) < 0) {
                perror("Error setting GPIO LOW");
                goto cleanup;
            }
            sleep(1);

            printf("Cycle %d: Setting HIGH for 1 second...\n", i + 1);
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Error setting GPIO HIGH");
                goto cleanup;
            }
            sleep(1);
        }
        // Third cycle: HIGH for 2 seconds
        else {
            printf("Cycle %d: Setting HIGH for 2 seconds...\n", i + 1);
            if (gpiod_line_set_value(line, 1) < 0) {
                perror("Error setting GPIO HIGH");
                goto cleanup;
            }
            sleep(2);
        }

        time(&current_time);
        elapsed_time = difftime(current_time, start_time);
        printf("Cycle %d completed in %.2f seconds\n", i + 1, elapsed_time);
    }

    printf("Program finished.\n");

cleanup:
    // Release the GPIO line and close the chip
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 1; // Indicate an error occurred
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CONFIG_VALUE 0xC283 // Single-shot mode, +/-4.096V, 128 SPS, AIN0

int main() {
    int fd;
    unsigned char buf[2];
    int16_t reading;

    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(fd);
        return 1;
    }

    // Configure ADS1115 for single-shot mode
    buf[0] = CONFIG_REG;
    buf[1] = (CONFIG_VALUE >> 8) & 0xFF; // MSB
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to config register");
        close(fd);
        return 1;
    }

    buf[0] = CONFIG_REG;
    buf[1] = CONFIG_VALUE & 0xFF; // LSB
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to config register");
        close(fd);
        return 1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read the conversion register
    buf[0] = CONVERSION_REG;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to conversion register");
        close(fd);
        return 1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read conversion register");
        close(fd);
        return 1;
    }

    reading = (buf[0] << 8) | buf[1];
    printf("ADS1115 Reading: %d\n", reading);

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio2_line = NULL;
struct gpiod_line *gpio3_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int set_gpio_state(int gpio_pin, int state);
int get_gpio_state(int gpio_pin);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (gpio2_line) {
        gpiod_line_release(gpio2_line);
    }
    if (gpio3_line) {
        gpiod_line_release(gpio3_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_2) {
        line = gpio2_line;
    } else if (gpio_pin == GPIO_3) {
        line = gpio3_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %d\n", gpio_pin, state, ret);
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio_pin) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_2) {
        line = gpio2_line;
    } else if (gpio_pin == GPIO_3) {
        line = gpio3_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %d\n", gpio_pin, value);
        return -1;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio2_line = gpiod_chip_get_line(chip, GPIO_2);
    if (!gpio2_line) {
        perror("Error getting GPIO 2 line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio3_line = gpiod_chip_get_line(chip, GPIO_3);
    if (!gpio3_line) {
        perror("Error getting GPIO 3 line");
        gpiod_line_release(gpio2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(gpio2_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO 2 line for output");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request(gpio3_line, &config, 0);
    if (ret < 0) {
        perror("Error requesting GPIO 3 line for output");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1
        if (set_gpio_state(GPIO_2, 1) != 0) {
            fprintf(stderr, "Error setting GPIO 2 state.\n");
        }
        printf("GPIO 2 set to 1\n");

        // Set GPIO 3 to 0
        if (set_gpio_state(GPIO_3, 0) != 0) {
            fprintf(stderr, "Error setting GPIO 3 state.\n");
        }
        printf("GPIO 3 set to 0\n");

        // Wait for 5 seconds
        sleep(5);

        // Set GPIO 2 to 0
        if (set_gpio_state(GPIO_2, 0) != 0) {
            fprintf(stderr, "Error setting GPIO 2 state.\n");
        }
        printf("GPIO 2 set to 0\n");

        // Set GPIO 3 to 1
        if (set_gpio_state(GPIO_3, 1) != 0) {
            fprintf(stderr, "Error setting GPIO 3 state.\n");
        }
        printf("GPIO 3 set to 1\n");

