#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the duration of the high pulse (in milliseconds)
#define PULSE_DURATION_MS 100

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2;
struct gpiod_line *line3;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line2, line3);
    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3) {
    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 2
    *line2 = gpiod_chip_get_line(*chip, GPIO_2);
    if (!*line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 3
    *line3 = gpiod_chip_get_line(*chip, GPIO_3);
    if (!*line3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(*line2, "my_program", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(*line3);
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line3, "my_program", 0) < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(*line2);
        gpiod_line_release(*line3);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Releases the GPIO lines and closes the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3) {
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line2, &line3) < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 high
        if (set_gpio_value(line2, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        printf("GPIO 2 set to HIGH\n");

        // Wait for PULSE_DURATION_MS milliseconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = PULSE_DURATION_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);

        // Set GPIO 2 low
        if (set_gpio_value(line2, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        printf("GPIO 2 set to LOW\n");

        // Set GPIO 3 high
        if (set_gpio_value(line3, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        printf("GPIO 3 set to HIGH\n");

        // Wait for PULSE_DURATION_MS milliseconds
        ts.tv_sec = 0;
        ts.tv_nsec = PULSE_DURATION_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);

        // Set GPIO 3 low
        if (set_gpio_value(line3, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        printf("GPIO 3 set to LOW\n");

        // Wait for 5 seconds
        ts.tv_sec = 5;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}

