// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line18;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line17, struct gpiod_line **line18);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line18);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line17, line18);
    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line17, struct gpiod_line **line18) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line17 = gpiod_chip_get_line(*chip, GPIO_17);
    if (!*line17) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(*chip);
        return -1;
    }

    *line18 = gpiod_chip_get_line(*chip, GPIO_18);
    if (!*line18) {
        perror("Error getting GPIO 18 line");
        gpiod_line_release(*line17);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line17, "my_program", 0) < 0) {
        perror("Error requesting GPIO 17 as output");
        gpiod_line_release(*line18);
        gpiod_line_release(*line17);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line18, "my_program", 0) < 0) {
        perror("Error requesting GPIO 18 as output");
        gpiod_line_release(*line17);
        gpiod_line_release(*line18);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Releases the GPIO lines and closes the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line18) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line17, &line18) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 to 1
        if (set_gpio_value(line17, 1) < 0) {
            cleanup_gpio(chip, line17, line18);
            return 1;
        }
        printf("GPIO 17 set to 1\n");

        // Set GPIO 18 to 0
        if (set_gpio_value(line18, 0) < 0) {
            cleanup_gpio(chip, line17, line18);
            return 1;
        }
        printf("GPIO 18 set to 0\n");

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define MEASURE_CMD 0xE3
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMID_MIN 0.0
#define HUMID_MAX 100.0

volatile sig_atomic_t keep_running = 1;

void intHandler(int dummy) {
    keep_running = 0;
}

int i2c_setup(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

int read_si7021(int fd, float *temperature, float *humidity) {
    unsigned char buf[2];
    int retries = 3;

    while (retries > 0) {
        if (write(fd, &MEASURE_CMD, 1) != 1) {
            perror("Error writing to I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        usleep(20000); // Wait for measurement (at least 15ms)

        if (read(fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            retries--;
            usleep(10000); // Wait 10ms before retrying
            continue;
        }

        uint16_t raw_value = (buf[0] << 8) | buf[1];

        if (temperature != NULL) {
            *temperature = (175.72 * raw_value / 65536.0) - 46.85;
        }
        if (humidity != NULL) {
            *humidity = (125.0 * raw_value / 65536.0) - 6.0;
        }

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SI7021 after multiple retries.\n");
    return -1; // Failure after retries
}

int validate_reading(float temperature, float humidity) {
    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
        return -1;
    }
    if (humidity < HUMID_MIN || humidity > HUMID_MAX) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", humidity);
        return -1;
    }
    return 0;
}

int main() {
    int fd = i2c_setup(I2C_BUS);
    if (fd < 0) {
        return 1;
    }

    signal(SIGINT, intHandler);

    float temperature, humidity;

    while (keep_running) {
        if (read_si7021(fd, &temperature, &humidity) == 0) {
            if (validate_reading(temperature, humidity) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Invalid reading, skipping.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5);
    }

    close(fd);
    printf("Exiting cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define CONFIG_VALUE 0xC283 // Single-shot mode, +/-4.096V, 128 SPS, AIN0

int main() {
    int fd;
    int i;
    uint8_t buf[2];
    int16_t reading;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return 1;
    }

    // Configure ADS1115
    uint8_t config[3] = {CONFIG_REG, (CONFIG_VALUE >> 8) & 0xFF, CONFIG_VALUE & 0xFF};
    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        close(fd);
        return 1;
    }

    // Wait for conversion (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    buf[0] = CONVERSION_REG;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        close(fd);
        return 1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        close(fd);
        return 1;
    }

    reading = (buf[0] << 8) | buf[1];

    printf("Reading: %d\n", reading);

    // Repeat for two more readings
    for (i = 1; i < 3; i++) {
        usleep(1000000); // 1 second

        // Configure ADS1115 again
        if (write(fd, config, 3) != 3) {
            perror("Error writing to I2C device");
            close(fd);
            return 1;
        }

        // Wait for conversion
        usleep(10000);

        // Read conversion register
        if (write(fd, buf, 1) != 1) {
            perror("Error writing to I2C device");
            close(fd);
            return 1;
        }

        if (read(fd, buf, 2) != 2) {
            perror("Error reading from I2C device");
            close(fd);
            return 1;
        }

        reading = (buf[0] << 8) | buf[1];
        printf("Reading: %d\n", reading);
    }

    close(fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_23 23
#define GPIO_24 24

// Define the number of cycles
#define NUM_CYCLES 256

// Define the delay between cycles (in milliseconds)
#define DELAY_MS 100

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[6];
} gpio_config_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_config_t *config) {
    config->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!config->chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    int lines[] = {GPIO_8, GPIO_9, GPIO_10, GPIO_11, GPIO_23, GPIO_24};
    for (int i = 0; i < 6; i++) {
        config->lines[i] = gpiod_chip_get_line(config->chip, lines[i]);
        if (!config->lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", lines[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_output(config->lines[i], "control") < 0) {
            fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", lines[i], strerror(errno));
            goto cleanup;
        }
    }
    return 0;

cleanup:
    if (config->chip) {
        for (int i = 0; i < 6; i++) {
            if (config->lines[i]) {
                gpiod_line_release(config->lines[i]);
            }
        }
        gpiod_chip_close(config->chip);
    }
    return -1;
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO lines and chip
void cleanup_gpio(gpio_config_t *config) {
    if (config->chip) {
        for (int i = 0; i < 6; i++) {
            if (config->lines[i]) {
                gpiod_line_release(config->lines[i]);
            }
        }
        gpiod_chip_close(config->chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    gpio_config_t gpio_config;

    // Initialize GPIO
    if (initialize_gpio(&gpio_config) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    for (int cycle = 0; cycle < NUM_CYCLES && !terminate; cycle++) {
        // Set GPIO states
        if (set_gpio_state(gpio_config.lines[0], 1) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[1], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[2], 1) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[3], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[4], 1) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[5], 0) < 0) goto cleanup;

        // Print the current state
        printf("Cycle %d: GPIO 8=1, GPIO 9=0, GPIO 10=1, GPIO 11=0, GPIO 23=1, GPIO 24=0\n", cycle + 1);

        // Delay
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&delay, NULL);

        // Reset GPIO states
        if (set_gpio_state(gpio_config.lines[0], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[1], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[2], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[3], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[4], 0) < 0) goto cleanup;
        if (set_gpio_state(gpio_config.lines[5], 0) < 0) goto cleanup;

        // Print the reset state
        printf("Cycle %d: GPIO 8=0, GPIO 9=0, GPIO 10=0, GPIO 11=0, GPIO 23=0, GPIO 24=0\n", cycle + 1);

        // Delay
        delay.tv_sec = 0;
        delay.tv_nsec = DELAY_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&delay, NULL);
    }

cleanup:
    // Cleanup GPIO
    cleanup_gpio(&gpio_config);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

