#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define INPUT_PIN 2
#define OUTPUT_PIN 3

// Define the number of readings to average
#define NUM_READINGS 5

// Define the delay between readings (in milliseconds)
#define READ_DELAY_MS 10

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *input_line;
struct gpiod_line *output_line;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_input_pin();
int average_readings(int num_readings);
void set_output_pin(int state);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read the input pin
int read_input_pin() {
    int value = gpiod_line_get_value(input_line);
    if (value < 0) {
        fprintf(stderr, "Error reading input pin: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to average multiple readings
int average_readings(int num_readings) {
    int sum = 0;
    for (int i = 0; i < num_readings; i++) {
        int reading = read_input_pin();
        if (reading < 0) {
            fprintf(stderr, "Error reading input pin during averaging, returning previous value.\n");
            return -1; // Indicate an error
        }
        sum += reading;
        usleep(READ_DELAY_MS * 1000); // Delay between readings
    }
    return sum / num_readings;
}

// Function to set the output pin
void set_output_pin(int state) {
    int ret = gpiod_line_set_value(output_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting output pin: %d\n", ret);
    }
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the input line
    input_line = gpiod_chip_get_line(chip, INPUT_PIN);
    if (!input_line) {
        perror("Error getting input line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get the output line
    output_line = gpiod_chip_get_line(chip, OUTPUT_PIN);
    if (!output_line) {
        perror("Error getting output line");
        gpiod_chip_close(chip);
        gpiod_line_release(input_line);
        return 1;
    }

    // Request the input line for reading
    struct gpiod_line_request_config input_config;
    memset(&input_config, 0, sizeof(input_config));
    input_config.consumer = "input_consumer";
    input_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    int ret = gpiod_line_request(input_line, &input_config, 0);
    if (ret < 0) {
        perror("Error requesting input line");
        gpiod_chip_close(chip);
        gpiod_line_release(input_line);
        gpiod_line_release(output_line);
        return 1;
    }

    // Request the output line for writing
    struct gpiod_line_request_config output_config;
    memset(&output_config, 0, sizeof(output_config));
    output_config.consumer = "output_consumer";
    output_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    ret = gpiod_line_request(output_line, &output_config, 0);
    if (ret < 0) {
        perror("Error requesting output line");
        gpiod_chip_close(chip);
        gpiod_line_release(input_line);
        gpiod_line_release(output_line);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the input pin and average the readings
        int average_value = average_readings(NUM_READINGS);
        if (average_value < 0) {
            fprintf(stderr, "Error averaging readings, exiting.\n");
            break;
        }

        // Set the output pin based on the average value
        set_output_pin(average_value);

        // Print the state of the output pin
        int output_state = gpiod_line_get_value(output_line);
        if (output_state < 0) {
            fprintf(stderr, "Error reading output pin state: %d\n", output_state);
        } else {
            printf("Output pin state: %d\n", output_state);
        }

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Release the lines and close the chip
    gpiod_line_release(input_line);
    gpiod_line_release(output_line);
    gpiod_chip_close(chip);

    return 0;
}

