// Global variables for GPIO lines and chip
struct gpiod_line *gpio4_line = NULL;
struct gpiod_line *gpio5_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO pin for output
int initialize_gpio(int gpio_pin) {
    int ret;
    struct gpiod_line *line;

    if (gpio_pin == GPIO_4) {
        line = gpio4_line;
    } else if (gpio_pin == GPIO_5) {
        line = gpio5_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "example", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", gpio_pin, ret);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO pin
int set_gpio_value(int gpio_pin, int value) {
    int ret;
    struct gpiod_line *line;

    if (gpio_pin == GPIO_4) {
        line = gpio4_line;
    } else if (gpio_pin == GPIO_5) {
        line = gpio5_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d value to %d: %d\n", gpio_pin, value, ret);
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO pin
int get_gpio_value(int gpio_pin) {
    int ret;
    struct gpiod_line *line;

    if (gpio_pin == GPIO_4) {
        line = gpio4_line;
    } else if (gpio_pin == GPIO_5) {
        line = gpio5_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO %d value: %d\n", gpio_pin, ret);
        return -1;
    }

    return ret;
}

// Cleans up GPIO resources
void cleanup_gpio(void) {
    if (gpio4_line) {
        gpiod_line_release(gpio4_line);
    }
    if (gpio5_line) {
        gpiod_line_release(gpio5_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int ret;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    gpio4_line = gpiod_chip_get_line(chip, GPIO_4);
    gpio5_line = gpiod_chip_get_line(chip, GPIO_5);
    if (!gpio4_line || !gpio5_line) {
        fprintf(stderr, "Error getting GPIO line\n");
        cleanup_gpio();
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(GPIO_4) < 0 || initialize_gpio(GPIO_5) < 0) {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 4 to 1
        if (set_gpio_value(GPIO_4, 1) < 0) {
            cleanup_gpio();
            return 1;
        }

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and GPIO 4 value
        printf("%s - GPIO 4: %d\n", timestamp, get_gpio_value(GPIO_4));

        // Set GPIO 5 to 0
        if (set_gpio_value(GPIO_5, 0) < 0) {
            cleanup_gpio();
            return 1;
        }

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and GPIO 5 value
        printf("%s - GPIO 5: %d\n", timestamp, get_gpio_value(GPIO_5));

        // Wait for 0.5 seconds
        usleep(500000); // 500000 microseconds = 0.5 seconds
    }

    return 0;
}

