#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the duration of the pulse (in milliseconds)
#define PULSE_DURATION_MS 100

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2;
struct gpiod_line *line3;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3);
int set_gpio_value(struct gpiod_line *line, int value);
int report_state(int value2, int value3);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line2, line3);
    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3) {
    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 2
    *line2 = gpiod_chip_get_line(*chip, GPIO_2);
    if (!*line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 3
    *line3 = gpiod_chip_get_line(*chip, GPIO_3);
    if (!*line3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(*line2, "assistant", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(*line3);
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line3, "assistant", 0) < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(*line2);
        gpiod_line_release(*line3);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

// Reports the current state of the GPIO lines
int report_state(int value2, int value3) {
    printf("GPIO 2: %d, GPIO 3: %d\n", value2, value3);
    return 0;
}

// Cleans up the GPIO lines and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3) {
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line2, &line3) < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 high
        if (set_gpio_value(line2, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Report the state
        if (report_state(1, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Wait for the pulse duration
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = PULSE_DURATION_MS * 1000000; // Convert milliseconds to nanoseconds
        nanosleep(&ts, NULL);

        // Set GPIO 2 low
        if (set_gpio_value(line2, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Report the state
        if (report_state(0, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Wait for 5 seconds
        ts.tv_sec = 5;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the number of cycles
#define NUM_CYCLES 3

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    if (sig == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3) {
    int ret;

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_2, strerror(errno));
        return -1;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Error getting GPIO %d line: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(line2);
        return -1;
    }

    ret = gpiod_line_request_output(line2, "cycle", 0); // Initial state LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_2, strerror(errno));
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return -1;
    }

    ret = gpiod_line_request_output(line3, "cycle", 0); // Initial state LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(line2);
        gpiod_line_release(line3);
        return -1;
    }

    return 0;
}

// Function to perform one cycle
void perform_cycle(struct gpiod_line *line2, struct gpiod_line *line3) {
    int ret;

    // Cycle 1: GPIO 2 HIGH, GPIO 3 LOW
    ret = gpiod_line_set_value(line2, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_2, strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(line3, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", GPIO_3, strerror(errno));
        return;
    }
    printf("Cycle 1: GPIO 2 HIGH, GPIO 3 LOW\n");
    usleep(500000); // 500ms

    // Cycle 2: GPIO 2 LOW, GPIO 3 HIGH
    ret = gpiod_line_set_value(line2, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", GPIO_2, strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(line3, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_3, strerror(errno));
        return;
    }
    printf("Cycle 2: GPIO 2 LOW, GPIO 3 HIGH\n");
    usleep(500000); // 500ms

    // Cycle 3: GPIO 2 HIGH, GPIO 3 HIGH
    ret = gpiod_line_set_value(line2, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_2, strerror(errno));
        return;
    }
    ret = gpiod_line_set_value(line3, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", GPIO_3, strerror(errno));
        return;
    }
    printf("Cycle 3: GPIO 2 HIGH, GPIO 3 HIGH\n");
    usleep(500000); // 500ms
}

// Function to release GPIO pins
void cleanup_gpio(struct gpiod_line *line2, struct gpiod_line *line3) {
    gpiod_line_release(line2);
    gpiod_line_release(line3);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int i;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(chip, line2, line3) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Perform cycles
    for (i = 0; i < NUM_CYCLES && program_running; i++) {
        perform_cycle(line2, line3);
    }

    // Cleanup GPIO pins
    cleanup_gpio(line2, line3);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

