    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", line->number, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to release GPIO resources
int release_gpio_resources(struct gpiod_chip *chip) {
    int ret;

    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(-ret));
        return -1;
    }

