        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO %d line: %s\n", lines[i]->number, strerror(errno));
            goto cleanup;
        }

        // Request GPIO line for output
        if (gpiod_line_request_output(lines[i], "control", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", lines[i]->number, strerror(errno));
            goto cleanup;
        }
    }

    // Main loop
    while (program_running) {
        // Toggle GPIO states
        for (i = 0; i < 4; i++) {
            state = (i % 2 == 0) ? 1 : 0; // Alternate between 1 and 0
            if (set_gpio_state(lines[i], state) < 0) {
                fprintf(stderr, "Error setting GPIO %d state\n", lines[i]->number);
                goto cleanup;
            }
