// Function to read DHT11 data
int read_dht11(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[MAX_TIMINGS];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed to 30us

    gpioSetMode(gpio, PI_INPUT);

    int timeout_counter = 0;
    while (gpioRead(gpio) == 1) {
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "DHT11: Timeout waiting for start signal.\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Check every microsecond
    }

    timeout_counter = 0;
    while (gpioRead(gpio) == 0) {
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "DHT11: Timeout waiting for end of start signal.\n");
            return -1; // Timeout
        }
        gpioDelay(1);
    }

    timeout_counter = 0;
    while (gpioRead(gpio) == 1) {
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "DHT11: Timeout waiting for end of data signal.\n");
            return -1; // Timeout
        }
        gpioDelay(1);
    }

    for (i = 0; i < MAX_TIMINGS; i++) {
        timeout_counter = 0;
        while (gpioRead(gpio) == 0) {
            if (timeout_counter++ > TIMEOUT_US) {
                fprintf(stderr, "DHT11: Timeout waiting for rising edge.\n");
                return -1; // Timeout
            }
            gpioDelay(1);
        }

        long t = gpioTick();

        timeout_counter = 0;
        while (gpioRead(gpio) == 1) {
            if (timeout_counter++ > TIMEOUT_US) {
                fprintf(stderr, "DHT11: Timeout waiting for falling edge.\n");
                return -1; // Timeout
            }
            gpioDelay(1);
        }

        pulse_counts[i] = gpioTick() - t;
    }

    for (i = 2; i < 42; i++) {
        int index = i / 8;
        int bit = i % 8;

        if (pulse_counts[2 * i - 1] > 40) {
            data[index] |= (1 << (7 - bit));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT11: Checksum error.\n");
        return -1; // Checksum error
    }

    *humidity = (float)data[0];
    *temperature = (float)data[2];

    return 0; // Success
}

