#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2;
struct gpiod_line *line3;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3);
int set_gpio_output(struct gpiod_line *line, int value);
int report_state(int gpio2_state, int gpio3_state);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line2, line3);
    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    *line2 = gpiod_chip_get_line(*chip, GPIO_2);
    if (!*line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_2, strerror(errno));
        gpiod_chip_close(*chip);
        return -1;
    }

    *line3 = gpiod_chip_get_line(*chip, GPIO_3);
    if (!*line3) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line2, "my_program", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_2, strerror(errno));
        gpiod_line_release(*line3);
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line3, "my_program", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(*line2);
        gpiod_line_release(*line3);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the state of a GPIO line
int set_gpio_output(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Reports the current state of the GPIO lines
int report_state(int gpio2_state, int gpio3_state) {
    printf("GPIO 2: %d, GPIO 3: %d\n", gpio2_state, gpio3_state);
    return 0;
}

// Releases the GPIO lines and closes the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3) {
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line2, &line3) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1
        if (set_gpio_output(line2, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        sleep(1);

        // Report state
        if (report_state(1, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Set GPIO 3 to 1
        if (set_gpio_output(line3, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        sleep(1);

        // Report state
        if (report_state(1, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Set GPIO 2 to 0
        if (set_gpio_output(line2, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        sleep(1);

        // Report state
        if (report_state(0, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }

        // Set GPIO 3 to 0
        if (set_gpio_output(line3, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        sleep(1);

        // Report state
        if (report_state(0, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
    }

    // Cleanup (should not reach here in normal execution due to the signal handler)
    cleanup_gpio(chip, line2, line3);
    return 0;
}

