// Define GPIO pins for PWM outputs
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM duty cycle (0-1000000)
#define PWM_DUTY_CYCLE 500000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

int main() {
    int rc;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM duty cycle for all pins
    gpioPWM(PWM_PIN_1, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_2, PWM_DUTY_CYCLE);
    gpioPWM(PWM_PIN_3, PWM_DUTY_CYCLE);

    // Main loop
    while (!terminate) {
        // Print the current state of the GPIO pins
        printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
               PWM_PIN_1, gpioGetMode(PWM_PIN_1),
               PWM_PIN_2, gpioGetMode(PWM_PIN_2),
               PWM_PIN_3, gpioGetMode(PWM_PIN_3));

        // Wait for 0.15 seconds
        gpioDelay(150000); // 0.15 seconds = 150000 microseconds
    }

    // Clean up and terminate pigpio library
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioTerminate();

    return 0;
}

