#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_7 7
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_17 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[9];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int read_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initializes a GPIO pin for output
int initialize_gpio(int gpio_pin) {
    int line_index;

    switch (gpio_pin) {
        case GPIO_2: line_index = 0; break;
        case GPIO_3: line_index = 1; break;
        case GPIO_4: line_index = 2; break;
        case GPIO_5: line_index = 3; break;
        case GPIO_6: line_index = 4; break;
        case GPIO_7: line_index = 5; break;
        case GPIO_8: line_index = 6; break;
        case GPIO_9: line_index = 7; break;
        case GPIO_17: line_index = 8; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin); return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    lines[line_index] = gpiod_chip_get_line(chip, gpio_pin);
    if (!lines[line_index]) {
        fprintf(stderr, "Error getting line %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    if (gpiod_line_request(lines[line_index], &config, 0) < 0) {
        fprintf(stderr, "Error requesting line %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO pin
int set_gpio_value(int gpio_pin, int value) {
    int line_index;

    switch (gpio_pin) {
        case GPIO_2: line_index = 0; break;
        case GPIO_3: line_index = 1; break;
        case GPIO_4: line_index = 2; break;
        case GPIO_5: line_index = 3; break;
        case GPIO_6: line_index = 4; break;
        case GPIO_7: line_index = 5; break;
        case GPIO_8: line_index = 6; break;
        case GPIO_9: line_index = 7; break;
        case GPIO_17: line_index = 8; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin); return -1;
    }

    if (!lines[line_index]) {
        fprintf(stderr, "GPIO line %d not initialized\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(lines[line_index], value) < 0) {
        fprintf(stderr, "Error setting value for GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Reads the value of a GPIO pin
int read_gpio_value(int gpio_pin) {
    int line_index;

    switch (gpio_pin) {
        case GPIO_2: line_index = 0; break;
        case GPIO_3: line_index = 1; break;
        case GPIO_4: line_index = 2; break;
        case GPIO_5: line_index = 3; break;
        case GPIO_6: line_index = 4; break;
        case GPIO_7: line_index = 5; break;
        case GPIO_8: line_index = 6; break;
        case GPIO_9: line_index = 7; break;
        case GPIO_17: line_index = 8; break;
        default: fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin); return -1;
    }

    if (!lines[line_index]) {
        fprintf(stderr, "GPIO line %d not initialized\n", gpio_pin);
        return -1;
    }

    int value = gpiod_line_get_value(lines[line_index]);
    if (value < 0) {
        fprintf(stderr, "Error reading value for GPIO %d: %s\n", gpio_pin, strerror(errno));
        return -1;
    }

    return value;
}

// Cleans up GPIO resources
void cleanup_gpio(void) {
    for (int i = 0; i < 9; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pins
    int gpio_pins[] = {GPIO_2, GPIO_3, GPIO_4, GPIO_5, GPIO_6, GPIO_7, GPIO_8, GPIO_9, GPIO_17};
    for (size_t i = 0; i < sizeof(gpio_pins) / sizeof(gpio_pins[0]); i++) {
        if (initialize_gpio(gpio_pins[i]) < 0) {
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        // Toggle GPIO 2
        if (set_gpio_value(GPIO_2, 1) < 0) {
            cleanup_gpio();
            return 1;
        }
        usleep(50000); // 50ms

        // Toggle GPIO 3
        if (set_gpio_value(GPIO_3, 0) < 0) {
