#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define OPT3001_ADDR 0x44

int main() {
    int file;
    int ret;
    uint8_t data[2];
    uint16_t raw_reading;
    float voltage;

    // Open I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set slave address
    if (ioctl(file, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file);
        return 1;
    }

    // Read two bytes from the OPT3001
    ret = read(file, data, 2);
    if (ret != 2) {
        perror("Failed to read from I2C device");
        close(file);
        return 1;
    }

    // Combine the bytes into a 16-bit value
    raw_reading = (data[0] << 8) | data[1];

    // Convert the raw reading to voltage (example formula, adjust as needed)
    voltage = (float)raw_reading * 0.0048828125; // Example conversion factor

    // Print the voltage reading
    printf("OPT3001 Voltage: %.6f V\n", voltage);

    // Close the I2C bus
    close(file);

    return 0;
}

#include <stdio.h>
