    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line17, struct gpiod_line **line18) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line17 = gpiod_chip_get_line(*chip, GPIO_17);
    if (!*line17) {
        perror("Error getting GPIO 17 line");
