#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define TIMEOUT_MS 1000

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 0.1 seconds (100ms)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        fprintf(stderr, "Failed to setup UART. Exiting.\n");
        return 1;
    }

    char buffer[256];
    ssize_t bytes_read;
    time_t start_time;

    printf("Starting data exchange...\n");

    while (program_running) {
        start_time = time(NULL);
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read == 0) {
            // Timeout or no data
            if (time(NULL) - start_time >= (TIMEOUT_MS / 1000.0)) {
                fprintf(stderr, "Timeout waiting for data.\n");
            }
        } else {
            perror("Error reading from UART");
            break; // Exit loop on error
        }

        usleep(10000); // Small delay to avoid busy-waiting
    }

    close(uart_fd);
    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17

struct gpiod_chip *chip;
struct gpiod_line *line4, *line17;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 milliseconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for GPIO 4
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("Error getting GPIO line 4");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 17
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line4, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 4 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line17, "my_program", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 4 and GPIO 17 are now output lines.\n");

    while (program_running) {
        // Toggle GPIO 4
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("Error setting GPIO 4 value");
            break;
        }
        printf("GPIO 4 set to 1\n");
        nanosleep(&sleep_time, NULL);

        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("Error setting GPIO 4 value");
            break;
        }
        printf("GPIO 4 set to 0\n");
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO 17
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        printf("GPIO 17 set to 1\n");
        nanosleep(&sleep_time, NULL);

        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 value");
            break;
        }
        printf("GPIO 17 set to 0\n");
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);

    printf("GPIO lines released and chip closed. Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
