// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line4, *line17, *line27;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio_control", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %s\n", gpio_pin, gpiod_line_name(line));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;
    int ret;

    if (gpio_pin == GPIO_4) {
        line = line4;
    } else if (gpio_pin == GPIO_17) {
        line = line17;
    } else if (gpio_pin == GPIO_27) {
        line = line27;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO %d: %s\n", gpio_pin, gpiod_line_name(line));
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == GPIO_4) {
        line = line4;
    } else if (gpio_pin == GPIO_17) {
        line = line17;
    } else if (gpio_pin == GPIO_27) {
        line = line27;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO %d: %s\n", gpio_pin, gpiod_line_name(line));
        return -1;
    }

    return value;
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(void) {
    if (line4) {
        gpiod_line_release(line4);
    }
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i;
    int value;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_4) != 0 ||
        initialize_gpio(GPIO_17) != 0 ||
        initialize_gpio(GPIO_27) != 0) {
        cleanup_gpio();
        return 1;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line27 = gpiod_chip_get_line(chip, GPIO_27);

    // Main loop
    while (1) {
        // Get current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Toggle GPIO 4
        value = get_gpio_value(GPIO_4);
        if (value == 0) {
            if (set_gpio_value(GPIO_4, 1) != 0) {
                cleanup_gpio();
                return 1;
            }
        } else {
            if (set_gpio_value(GPIO_4, 0) != 0) {
                cleanup_gpio();
                return 1;
            }
        }

        // Toggle GPIO 17
        value = get_gpio_value(GPIO_17);
        if (value == 0) {
            if (set_gpio_value(GPIO_17, 1) != 0) {
                cleanup_gpio();
                return 1;
            }
        } else {
            if (set_gpio_value(GPIO_17, 0) != 0) {
                cleanup_gpio();
                return 1;
            }
        }

        // Toggle GPIO 27
        value = get_gpio_value(GPIO_27);
        if (value == 0) {
            if (set_gpio_value(GPIO_27, 1) != 0) {
                cleanup_gpio();
                return 1;
            }
        } else {
            if (set_gpio_value(GPIO_27, 0) != 0) {
                cleanup_gpio();
                return 1;
            }
        }

        // Print current state
        printf("%s - GPIO 4: %d, GPIO 17: %d, GPIO 27: %d\n",
               timestamp, get_gpio_value(GPIO_4), get_gpio_value(GPIO_17), get_gpio_value(GPIO_27));

        // Wait 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 2
#define NUM_CYCLES 3

static volatile int keep_running = 1;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
    keep_running = 0;
}

// Function to set the GPIO pin state
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to read the GPIO pin state
int read_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(-value));
        return -1;
    }
    return value;
}

// Function to perform one cycle of GPIO control
int perform_cycle(struct gpiod_line *line) {
    int ret;

    // Set GPIO high
    ret = set_gpio_state(line, 1);
    if (ret < 0) {
        return -1;
    }
    printf("GPIO set to HIGH\n");

    // Wait for 1 second
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;
    nanosleep(&sleep_time, NULL);

    // Read GPIO state
    int state = read_gpio_state(line);
    if (state < 0) {
        return -1;
    }
    printf("GPIO state: %d\n", state);

    // Set GPIO low
    ret = set_gpio_state(line, 0);
    if (ret < 0) {
        return -1;
    }
    printf("GPIO set to LOW\n");

    // Wait for 1 second
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;
    nanosleep(&sleep_time, NULL);

    return 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    int cycle_count = 0;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "cycle_control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (keep_running && cycle_count < NUM_CYCLES) {
        printf("Starting cycle %d\n", cycle_count + 1);
        if (perform_cycle(line) < 0) {
            fprintf(stderr, "Error performing cycle, exiting.\n");
            break;
        }
        cycle_count++;

        // Wait for 60 seconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 60;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
