// Global variables for GPIO lines and chip
struct gpiod_line *gpio5_line = NULL;
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio24_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    struct gpiod_line_request_config config;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_pin);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", gpio_pin);
        gpiod_line_release(line);
        return -1;
    }

    if (gpio_pin == GPIO_5) {
        gpio5_line = line;
    } else if (gpio_pin == GPIO_17) {
        gpio17_line = line;
    } else if (gpio_pin == GPIO_24) {
        gpio24_line = line;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_5) {
        line = gpio5_line;
    } else if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_24) {
        line = gpio24_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO %d to %d\n", gpio_pin, value);
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == GPIO_5) {
        line = gpio5_line;
    } else if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_24) {
        line = gpio24_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get GPIO %d value\n", gpio_pin);
        return -1;
    }

    return value;
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(void) {
    if (gpio5_line) {
        gpiod_line_release(gpio5_line);
    }
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio24_line) {
        gpiod_line_release(gpio24_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    int i;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", CHIP_NAME);
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_5) < 0 ||
        initialize_gpio(GPIO_17) < 0 ||
        initialize_gpio(GPIO_24) < 0) {
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Toggle GPIO 5
        i = get_gpio_value(GPIO_5);
        if (i < 0) {
            cleanup_gpio();
            return 1;
        }
        set_gpio_value(GPIO_5, !i);
        printf("%s - GPIO 5: %d\n", timestamp, !i);

        // Toggle GPIO 17
        i = get_gpio_value(GPIO_17);
        if (i < 0) {
            cleanup_gpio();
            return 1;
        }
        set_gpio_value(GPIO_17, !i);
        printf("%s - GPIO 17: %d\n", timestamp, !i);

        // Toggle GPIO 24
        i = get_gpio_value(GPIO_24);
        if (i < 0) {
            cleanup_gpio();
            return 1;
        }
        set_gpio_value(GPIO_24, !i);
        printf("%s - GPIO 24: %d\n", timestamp, !i);

        // Wait 0.2 seconds
        usleep(200000); // 200000 microseconds = 0.2 seconds
    }

    return 0;
}

