// Define GPIO pins
#define GPIO11 11
#define GPIO12 12
#define GPIO17 17
#define GPIO18 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", line->number, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(struct gpiod_line *line) {
    int state = gpiod_line_get_value(line);
    if (state < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %s\n", line->number, strerror(-state));
        return -1;
    }
    return state;
}

// Function to print the current state of all GPIO pins
void print_gpio_states(struct gpiod_chip *chip) {
    struct gpiod_line *line;
    int i;

    printf("GPIO States:\n");
    gpiod_chip_for_each_line(chip, i, line) {
        int state = get_gpio_state(line);
        if (state >= 0) {
            printf("GPIO %d: %d\n", line->number, state);
        } else {
            fprintf(stderr, "Error reading GPIO %d state.\n", line->number);
        }
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[4];
    int i, state = 0;
    struct timespec sleep_time;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get lines for the specified GPIO pins
    lines[0] = gpiod_chip_get_line(chip, GPIO11);
    lines[1] = gpiod_chip_get_line(chip, GPIO12);
    lines[2] = gpiod_chip_get_line(chip, GPIO17);
    lines[3] = gpiod_chip_get_line(chip, GPIO18);

    for (i = 0; i < 4; i++) {
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO %d line\n", GPIO11 + i);
            goto cleanup;
        }

        // Request the line for output
        if (gpiod_line_request_output(lines[i], "control", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO11 + i, strerror(errno));
            goto cleanup;
        }
    }

    // Set initial state to 0
    for (i = 0; i < 4; i++) {
        if (set_gpio_state(lines[i], 0) < 0) {
            goto cleanup;
        }
    }

    // Configure sleep time (100 milliseconds)
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds

    // Main loop
    while (!terminate) {
        // Toggle the state
        state = !state;

        // Set the state for all GPIO pins
        for (i = 0; i < 4; i++) {
            if (set_gpio_state(lines[i], state) < 0) {
                terminate = 1; // Exit loop on error
                break;
            }
        }

        // Print the current state of all GPIO pins
        print_gpio_states(chip);

        // Sleep for 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    // Release the GPIO lines
    for (i = 0; i < 4; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

