#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Define the duration of the pulse (in nanoseconds)
#define PULSE_DURATION 100000000 // 100 microseconds

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line2;
    struct gpiod_line *line3;
} gpio_context_t;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_context_t *context) {
    context->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!context->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    context->line2 = gpiod_chip_get_line(context->chip, GPIO_2);
    if (!context->line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(context->chip);
        return -1;
    }

    context->line3 = gpiod_chip_get_line(context->chip, GPIO_3);
    if (!context->line3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(context->line2);
        gpiod_chip_close(context->chip);
        return -1;
    }

    if (gpiod_line_request_output(context->line2, "pulse_generator", 0) < 0) {
        perror("Error requesting GPIO line 2 as output");
        gpiod_line_release(context->line3);
        gpiod_line_release(context->line2);
        gpiod_chip_close(context->chip);
        return -1;
    }

    if (gpiod_line_request_output(context->line3, "pulse_generator", 0) < 0) {
        perror("Error requesting GPIO line 3 as output");
        gpiod_line_release(context->line2);
        gpiod_line_release(context->line3);
        gpiod_chip_close(context->chip);
        return -1;
    }

    return 0;
}

// Function to generate a pulse on GPIO 2 and 3
void generate_pulse(gpio_context_t *context) {
    struct timespec start_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &start_time);

    // Set GPIO 2 high
    if (gpiod_line_set_value(context->line2, 1) < 0) {
        perror("Error setting GPIO 2 high");
        return;
    }

    // Set GPIO 3 high
    if (gpiod_line_set_value(context->line3, 1) < 0) {
        perror("Error setting GPIO 3 high");
        gpiod_line_set_value(context->line2, 0);
        return;
    }

    clock_gettime(CLOCK_MONOTONIC, &current_time);
    long elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - start_time.tv_nsec);

    while (elapsed_ns < PULSE_DURATION) {
        clock_gettime(CLOCK_MONOTONIC, &current_time);
        elapsed_ns = (current_time.tv_sec - start_time.tv_sec) * 1000000000L + (current_time.tv_nsec - start_time.tv_nsec);
        usleep(1); // Small delay to avoid busy-waiting
    }

    // Set GPIO 2 low
    if (gpiod_line_set_value(context->line2, 0) < 0) {
        perror("Error setting GPIO 2 low");
        return;
    }

    // Set GPIO 3 low
    if (gpiod_line_set_value(context->line3, 0) < 0) {
        perror("Error setting GPIO 3 low");
        return;
    }
}

// Function to release GPIO lines and close the chip
void cleanup_gpio(gpio_context_t *context) {
    if (context->line2) {
        gpiod_line_release(context->line2);
    }
    if (context->line3) {
        gpiod_line_release(context->line3);
    }
    if (context->chip) {
        gpiod_chip_close(context->chip);
    }
}

int main() {
    gpio_context_t gpio_context;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_context) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("GPIO initialization complete. Generating pulses...\n");

    // Main loop
    while (program_running) {
        generate_pulse(&gpio_context);
        usleep(100000); // 0.1 seconds
    }

    // Cleanup GPIO
    cleanup_gpio(&gpio_context);

    printf("Program terminated.\n");
    return 0;
}

