    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line17 || !line27) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_17) != 0 || initialize_gpio(GPIO_27) != 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Toggle GPIO 17
        ret = set_gpio_value(GPIO_17, 1);
        if (ret == 0) {
            printf("%s - GPIO %d set to 1\n", timestamp, GPIO_17);
        } else {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_17);
        }

        // Toggle GPIO 27
        ret = set_gpio_value(GPIO_27, 0);
        if (ret == 0) {
            printf("%s - GPIO %d set to 0\n", timestamp, GPIO_27);
        } else {
            fprintf(stderr, "Error setting GPIO %d\n", GPIO_27);
        }

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    cleanup_gpio(GPIO_17);
    cleanup_gpio(GPIO_27);
    gpiod_chip_close(chip);

    return 0;
}

