int main() {
    int i;
    int state;
    struct timespec sleep_time;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for output
    if (gpiod_line_request_output(line, "example", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Configure the number of cycles and sleep time
    int num_cycles = 3;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    // Main loop
    for (i = 0; i < num_cycles; i++) {
        // Set the GPIO pin HIGH
        state = 1;
        if (gpiod_line_set_value(line, state) < 0) {
            perror("Error setting GPIO pin HIGH");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        // Sleep for 0.1 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("Error sleeping");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Set the GPIO pin LOW
        state = 0;
        if (gpiod_line_set_value(line, state) < 0) {
            perror("Error setting GPIO pin LOW");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
