#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
    }
}

// Function to report the current PWM states
void report_pwm_states() {
    int duty_cycle_1 = gpioGetPWMdutycycle(PWM_PIN_1);
    int duty_cycle_2 = gpioGetPWMdutycycle(PWM_PIN_2);
    int duty_cycle_3 = gpioGetPWMdutycycle(PWM_PIN_3);

    printf("PWM States: GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
           PWM_PIN_1, duty_cycle_1, PWM_PIN_2, duty_cycle_2, PWM_PIN_3, duty_cycle_3);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to PWM output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range for all pins
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate a sequence of PWM duty cycles
        for (int duty_cycle = 0; duty_cycle <= PWM_RANGE; duty_cycle += 50) {
            set_pwm_duty_cycle(PWM_PIN_1, duty_cycle);
            set_pwm_duty_cycle(PWM_PIN_2, duty_cycle * 2); // Double the duty cycle
            set_pwm_duty_cycle(PWM_PIN_3, duty_cycle * 3); // Triple the duty cycle
            report_pwm_states();
            sleep(1); // Wait for 1 second
        }

        // Wait for 5 seconds before repeating the sequence
        sleep(5);
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

