#define W1_DEVICES_PATH "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"

static volatile int keep_running = 1;

void int_handler(int dummy) {
    keep_running = 0;
}

int read_ds18b20(float *temperature) {
    char w1_devices_path[256];
    char w1_device_path[512];
    char w1_slave_path[512];
    int fd;
    char buf[256];
    ssize_t num_read;
    char *token;
    char *temp_str;
    float temp_celsius;

    // Find the DS18B20 device
    snprintf(w1_devices_path, sizeof(w1_devices_path), "%s*", W1_DEVICES_PATH);
    struct dirent *entry;
    DIR *dir = opendir(W1_DEVICES_PATH);
    if (!dir) {
        perror("opendir");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strncmp(entry->d_name, "28-", 3) == 0) {
            snprintf(w1_device_path, sizeof(w1_device_path), "%s%s", W1_DEVICES_PATH, entry->d_name);
            break;
        }
    }
    closedir(dir);

    if (entry == NULL) {
        fprintf(stderr, "Error: DS18B20 device not found.\n");
        return -1;
    }

    // Open the w1_slave file
    snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s", w1_device_path, W1_SLAVE_FILE);
    fd = open(w1_slave_path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    // Read the w1_slave file
    num_read = read(fd, buf, sizeof(buf) - 1);
    if (num_read == -1) {
        perror("read");
        close(fd);
        return -1;
    }
    buf[num_read] = '\0';

    close(fd);

    // Parse the temperature
    token = strtok(buf, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Could not find first line in w1_slave file.\n");
        return -1;
    }

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Could not find second line in w1_slave file.\n");
        return -1;
    }

    temp_str = strstr(token, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Could not find temperature in w1_slave file.\n");
        return -1;
    }

    temp_celsius = atof(temp_str + 2) / 1000.0;

    // Validate the temperature
    if (temp_celsius < -20.0 || temp_celsius > 85.0) {
        fprintf(stderr, "Error: Invalid temperature reading: %.2f\n", temp_celsius);
        return -1;
    }

    *temperature = temp_celsius;
    return 0;
}

int main() {
    float temperature;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    // Set up signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    printf("Reading DS18B20 temperature every 5 seconds...\n");

    while (keep_running) {
        if (read_ds18b20(&temperature) == 0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s Temperature: %.2f °C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }

        sleep(5);
    }

    printf("Exiting...\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define HTU21D_ADDR 0x40
#define I2C_DEVICE "/dev/i2c-1"

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

int i2c_write_byte(int fd, uint8_t data) {
    if (write(fd, &data, 1) != 1) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

int read_htu21d(int fd, float *temperature, float *humidity) {
    uint8_t buf[3];
    uint16_t raw_temperature, raw_humidity;

    // Trigger temperature measurement
    if (i2c_write_byte(fd, 0xE3) != 0) {
        fprintf(stderr, "Error triggering temperature measurement\n");
        return -1;
    }
    usleep(50000); // Wait 50ms

    if (i2c_read_bytes(fd, 0, buf, 3) != 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    raw_temperature = (buf[0] << 8) | buf[1];
    raw_temperature &= 0xFFFC; // Clear status bits

    // Trigger humidity measurement
    if (i2c_write_byte(fd, 0xE5) != 0) {
        fprintf(stderr, "Error triggering humidity measurement\n");
        return -1;
    }
    usleep(50000); // Wait 50ms

    if (i2c_read_bytes(fd, 0, buf, 3) != 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    raw_humidity = (buf[0] << 8) | buf[1];
    raw_humidity &= 0xFFFC; // Clear status bits

    // Convert to Celsius and %RH
    *temperature = -46.85 + 175.72 * (raw_temperature / 65536.0);
    *humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    // Validate readings
    if (*temperature < -40.0 || *temperature > 125.0 || *humidity < 0.0 || *humidity > 100.0) {
        fprintf(stderr, "Invalid sensor readings: Temperature=%.2f, Humidity=%.2f\n", *temperature, *humidity);
        return -1;
    }

    return 0;
}

int main() {
    float temperature, humidity;

    signal(SIGINT, signal_handler);

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    while (program_running) {
        if (read_htu21d(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read HTU21D sensor data\n");
        }
        sleep(60);
    }

    close(i2c_fd);
    return 0;
}

#include <stdio.h>
