#include <errno.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    int value = 0;

    /* Register signal handlers */
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request(line, "output", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Main loop */
    while (!terminate) {
        /* Set GPIO value */
        ret = gpiod_line_set_value(line, value);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        /* Print current state */
        printf("GPIO %d: %d\n", GPIO_PIN, value);

        /* Toggle value */
        value = !value;

        /* Wait 50 milliseconds */
        usleep(50000);
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

