int set_gpio_state(int gpio_pin, int state);
int get_gpio_state(int gpio_pin);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (gpio2_line) {
        gpiod_line_release(gpio2_line);
    }
    if (gpio3_line) {
        gpiod_line_release(gpio3_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_2) {
        line = gpio2_line;
    } else if (gpio_pin == GPIO_3) {
        line = gpio3_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %d\n", gpio_pin, state, ret);
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio_pin) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_2) {
        line = gpio2_line;
    } else if (gpio_pin == GPIO_3) {
        line = gpio3_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %d\n", gpio_pin, value);
        return -1;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio2_line = gpiod_chip_get_line(chip, GPIO_2);
    if (!gpio2_line) {
        perror("Error getting GPIO 2 line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio3_line = gpiod_chip_get_line(chip, GPIO_3);
    if (!gpio3_line) {
        perror("Error getting GPIO 3 line");
        gpiod_line_release(gpio2_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio2_line, "my_program", 0) < 0) {
        perror("Error requesting GPIO 2 for output");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio3_line, "my_program", 0) < 0) {
        perror("Error requesting GPIO 3 for output");
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
