#define NUM_CYCLES 50

struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int i;
    int state;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 0.1 seconds

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(line, "example", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d (BCM) set to output mode.\n", GPIO_PIN);

    // Main loop
    for (i = 0; i < NUM_CYCLES; i++) {
        // Toggle the state
        state = (i % 2 == 0) ? 1 : 0;

        // Set the GPIO state
        if (gpiod_line_set_value(line, state) < 0) {
            perror("Error setting GPIO state");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Print the current state
        printf("Cycle %d: GPIO %d set to %d\n", i + 1, GPIO_PIN, state);

        // Sleep for 0.1 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("Error sleeping");
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Release GPIO line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

