int read_dht22(int gpio_pin, float *temperature, float *humidity)
{
    int i, j;
    unsigned int data[5] = {0, 0, 0, 0, 0};
    struct timespec start, end;
    long duration;

    // 1. Send start signal
    if (gpioSetMode(gpio_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to output mode\n", gpio_pin);
        return -1;
    }
    gpioWrite(gpio_pin, 0);
    gpioDelay(DHT22_INIT_LOW);
    gpioWrite(gpio_pin, 1);
    gpioDelay(DHT22_INIT_HIGH);

    // 2. Switch to input mode and read data
    if (gpioSetMode(gpio_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d to input mode\n", gpio_pin);
        return -1;
    }

    // Wait for DHT22 response (low for ~80us, then high for ~80us)
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpioRead(gpio_pin) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration > 100) {
            fprintf(stderr, "DHT22 not responding (initial low timeout)\n");
            return -1;
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpioRead(gpio_pin) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (duration > 100) {
            fprintf(stderr, "DHT22 not responding (initial high timeout)\n");
            return -1;
        }
    }

    // 3. Read 40 bits of data
    for (i = 0; i < 40; i++) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpioRead(gpio_pin) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > DHT22_DATA_HIGH) {
                fprintf(stderr, "DHT22 data high timeout\n");
                return -1;
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &start);
        while (gpioRead(gpio_pin) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            duration = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            if (duration > DHT22_DATA_LOW) {
                break;
            }
        }

        data[i / 8] <<= 1;
        if (gpioRead(gpio_pin) == 1) {
            data[i / 8] |= 1;
        }
    }

    // 4. Verify checksum
    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

