#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pwm_value;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Generate PWM values between 0 and 1000
        pwm_value = rand() % (PWM_RANGE + 1);

        // Set the PWM duty cycle
        gpioPWM(GPIO_PIN, pwm_value);

        // Print the current PWM value
        printf("PWM Value: %d\n", pwm_value);

        // Wait for 20 milliseconds
        usleep(20000);
    }

    // Stop PWM output
    gpioPWM(GPIO_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("PWM control stopped. Program terminated.\n");
    return 0;
}

