// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd) {
    // Enable the sensor (power on and enable RGBC)
    uint8_t enable_value = 0x03; // PON + AEN
    if (write(fd, &enable_value, 1) != 1) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time (ATIME).  A longer integration time increases resolution.
    uint8_t atime_value = 0xD5; // 101ms integration time
    if (write(fd, &atime_value, 1) != 1) {
        perror("Error writing to ATIME register");
        return -1;
    }

    // Set gain (AGAIN).  Higher gain increases sensitivity.
    uint8_t control_value = 0x00; // 1x gain
    if (write(fd, &control_value, 1) != 1) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    return 0;
}

// Function to read RGBC values from the sensor
int tcs34725_read_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buffer[8];

    // Read all RGBC values in one go
    if (read(fd, buffer, 8) != 8) {
        perror("Error reading RGBC data");
        return -1;
    }

    *c = (buffer[1] << 8) | buffer[0];
    *r = (buffer[3] << 8) | buffer[2];
    *g = (buffer[5] << 8) | buffer[4];
    *b = (buffer[7] << 8) | buffer[6];

    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    uint16_t r, g, b, c;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read RGBC values
        if (tcs34725_read_data(i2c_fd, &r, &g, &b, &c) == 0) {
            // Print the RGBC values
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Wait for 0.2 seconds
        usleep(200000); // 200000 microseconds = 0.2 seconds
    }

    // The program should never reach here due to the infinite loop.
    close(i2c_fd);
    return 0;
}

