#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio22_line = NULL;
struct gpiod_line *gpio27_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio22_line, struct gpiod_line **gpio27_line);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio22_line, struct gpiod_line *gpio27_line);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, gpio22_line, gpio27_line);
    exit(0);
}

// Initializes the GPIO chip and lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio22_line, struct gpiod_line **gpio27_line) {
    int ret;

    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 22
    *gpio22_line = gpiod_chip_get_line(*chip, GPIO_22);
    if (!*gpio22_line) {
        perror("Error getting GPIO 22 line");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 27
    *gpio27_line = gpiod_chip_get_line(*chip, GPIO_27);
    if (!*gpio27_line) {
        perror("Error getting GPIO 27 line");
        gpiod_line_release(*gpio22_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(*gpio22_line, "gpio22_control");
    if (ret < 0) {
        perror("Error requesting GPIO 22 for output");
        gpiod_line_release(*gpio27_line);
        gpiod_line_release(*gpio22_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_output(*gpio27_line, "gpio27_control");
    if (ret < 0) {
        perror("Error requesting GPIO 27 for output");
        gpiod_line_release(*gpio22_line);
        gpiod_line_release(*gpio27_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Cleans up the GPIO lines and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio22_line, struct gpiod_line *gpio27_line) {
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int gpio22_value, gpio27_value;
    struct timespec sleep_time;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &gpio22_line, &gpio27_line) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 22 to 1
        if (set_gpio_value(gpio22_line, 1) != 0) {
            cleanup_gpio(chip, gpio22_line, gpio27_line);
            return 1;
        }
        gpio22_value = get_gpio_value(gpio22_line);
        if (gpio22_value < 0) {
            cleanup_gpio(chip, gpio22_line, gpio27_line);
            return 1;
        }
        printf("GPIO 22 set to %d\n", gpio22_value);

        // Set GPIO 27 to 0
        if (set_gpio_value(gpio27_line, 0) != 0) {
            cleanup_gpio(chip, gpio22_line, gpio27_line);
            return 1;
        }
        gpio27_value = get_gpio_value(gpio27_line);
        if (gpio27_value < 0) {
            cleanup_gpio(chip, gpio22_line, gpio27_line);
            return 1;
        }
        printf("GPIO 27 set to %d\n", gpio27_value);

        // Sleep for 10 milliseconds
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10000000; // 10 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

