// Initialize the SSD1306 display
int ssd1306_init() {
    unsigned char init_sequence[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset (0 = no offset)
        0x40,       // Start line
        0x8D, 0x14, // Charge pump enable
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap (A0/A1 = 1/1 = normal)
        0xC8,       // COM output scan direction (C0/C8 = 0/1 = normal)
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Pre-charge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF (A4 = normal)
        0xA6,       // Normal/Inverse display (A6 = normal)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        ssd1306_write_command(init_sequence[i]);
    }

    return 0;
}

// Clear the SSD1306 display
void ssd1306_clear_display() {
    for (int i = 0; i < SCREEN_WIDTH * (SCREEN_HEIGHT / 8); i++) {
        ssd1306_write_data(0x00);
    }
}

// Write a command to the SSD1306
void ssd1306_write_command(unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write command");
    }
}

// Write data to the SSD1306
void ssd1306_write_data(unsigned char data) {
    unsigned char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write data");
    }
}

