#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins (BCM numbering)
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_5 5

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2, *line3, *line5;

// Function prototypes
int initialize_gpio(struct gpiod_chip *chip, int pin);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3, struct gpiod_line *line5);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line2, line3, line5);
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(struct gpiod_chip *chip, int pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", pin);
        return -1;
    }

    ret = gpiod_line_request(line, "gpio_control", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output (%d)\n", pin, ret);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set GPIO value to %d (%d)\n", value, ret);
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get GPIO value (%d)\n", value);
        return -1;
    }
    return value;
}

// Releases GPIO lines and unexports the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3, struct gpiod_line *line5) {
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (line5) gpiod_line_release(line5);
    if (chip) gpiod_chip_close(chip);
}

int main() {
    int ret;
    time_t current_time;
    struct tm *time_info;
    char time_string[20];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(chip, GPIO_2) != 0 ||
        initialize_gpio(chip, GPIO_3) != 0 ||
        initialize_gpio(chip, GPIO_5) != 0) {
        cleanup_gpio(chip, NULL, NULL, NULL);
        return 1;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    line3 = gpiod_chip_get_line(chip, GPIO_3);
    line5 = gpiod_chip_get_line(chip, GPIO_5);

    // Main loop
    while (1) {
        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S", time_info);

        // Set GPIO values
        if (set_gpio_value(line2, 1) != 0 ||
            set_gpio_value(line3, 0) != 0 ||
            set_gpio_value(line5, 1) != 0) {
            cleanup_gpio(chip, line2, line3, line5);
            return 1;
        }

        // Get GPIO values
        int value2 = get_gpio_value(line2);
        int value3 = get_gpio_value(line3);
        int value5 = get_gpio_value(line5);

        if (value2 < 0 || value3 < 0 || value5 < 0) {
            cleanup_gpio(chip, line2, line3, line5);
            return 1;
        }

        // Print the state
        printf("%s - GPIO 2: %d, GPIO 3: %d, GPIO 5: %d\n", time_string, value2, value3, value5);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

