        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    // Set the sensor to forced mode and configure other settings
    uint8_t ctrl_meas = (0b001 << 5) | (0b001 << 2) | 0b001; // Temperature and pressure oversampling x1, forced mode
    uint8_t ctrl_hum = 0b001; // Humidity oversampling x1
    uint8_t config = (0b000 << 5) | (0b000 << 2); // t_sb = 0.5ms, filter off

    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CTRL_HUM, ctrl_hum) < 0) {
        perror("Error writing to CTRL_HUM register");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CONFIG, config) < 0) {
        perror("Error writing to CONFIG register");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    if (i2c_smbus_write_byte_data(i2c_fd, BME280_REG_CTRL_MEAS, ctrl_meas) < 0) {
        perror("Error writing to CTRL_MEAS register");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

