#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register settings
#define CONFIG_OS_SINGLE 0x8000  // Start single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0040  // +/-4.096V range
#define CONFIG_MODE_SINGLE 0x0100 // Single-shot mode
#define CONFIG_DR_128SPS 0x0080   // 128 SPS
#define CONFIG_COMP_MODE_TRAD 0x0000 // Traditional comparator
#define CONFIG_COMP_POL_LOW 0x0000 // Active low comparator
#define CONFIG_COMP_LAT_NON 0x0000 // Non-latching comparator
#define CONFIG_COMP_QUE_DISABLE 0x0003 // Disable comparator

// Global variables
int i2c_fd;
volatile sig_atomic_t stop_flag = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

// Function to write a 16-bit value to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;      // LSB

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from an I2C register
int read_i2c_reg(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write to I2C device (read address)");
        return -1;
    }

    uint8_t read_buf[2];
    if (read(fd, read_buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    struct timespec sleep_time = {0, 200000000}; // 0.2 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    printf("ADS1115 ADC reader started. Press Ctrl+C to exit.\n");

    while (!stop_flag) {
        // Configure the ADS1115 for single-shot conversion
        uint16_t config_value = CONFIG_OS_SINGLE | CONFIG_MUX_SINGLE_0 | CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE | CONFIG_DR_128SPS | CONFIG_COMP_MODE_TRAD | CONFIG_COMP_POL_LOW | CONFIG_COMP_LAT_NON | CONFIG_COMP_QUE_DISABLE;
        if (write_i2c_reg(i2c_fd, ADS1115_REG_CONFIG, config_value) < 0) {
            fprintf(stderr, "Error configuring ADS1115. Exiting.\n");
            break;
        }

        // Wait for the conversion to complete (at least 8ms for 128 SPS)
        usleep(10000); // 10ms

        // Read the conversion result
        uint16_t conversion_result;
        if (read_i2c_reg(i2c_fd, ADS1115_REG_CONVERT, &conversion_result) < 0) {
            fprintf(stderr, "Error reading conversion result. Exiting.\n");
            break;
        }

        // Print the conversion result
        printf("Conversion Result: %d\n", conversion_result);

        // Sleep for 0.2 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Close the I2C device
    close(i2c_fd);

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 60;
    sleep_time.tv_nsec = 0;

    /* Register signal handlers */
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stderr, "GPIO %d requested for output.\n", GPIO_PIN);

    /* Main loop */
    while (!terminate) {
        /* Set GPIO high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO high");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        /* Sleep for 60 seconds */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep interrupted");
            break;
        }

        /* Set GPIO low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO low");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        /* Sleep for 60 seconds */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep interrupted");
            break;
        }
    }

    /* Release GPIO line */
    gpiod_line_release(line);
    fprintf(stderr, "GPIO %d released.\n", GPIO_PIN);

    /* Close GPIO chip */
    gpiod_chip_close(chip);
    fprintf(stderr, "GPIO chip closed.\n");

    return 0;
}

