// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t data = 0x00;
    if (write(i2c_fd, &data, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    // Read accelerometer data (6 bytes: X, Y, Z)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read accelerometer data
        if (read_accelerometer(&x, &y, &z) == 0) {
            // Print accelerometer data
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        // Delay for 10 milliseconds
        usleep(10000); // 10000 microseconds = 10 milliseconds
    }

    // The program should never reach here due to the infinite loop.
    close(i2c_fd);
    return 0;
}

