#include <time.h>

// HD44780 I2C address
#define HD44780_ADDR 0x28

// HD44780 commands
#define HD44780_FUNCTION_SET 0x33
#define HD44780_DISPLAY_CONTROL 0x08
#define HD44780_ENTRY_MODE_SET 0x06
#define HD44780_CLEAR_DISPLAY 0x01
#define HD44780_SET_CURSOR 0x80 // Set cursor to beginning of line 1

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to send a command to the HD44780
int send_command(int fd, unsigned char command) {
    unsigned char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to send command");
        return -1;
    }
    return 0;
}

// Function to initialize the HD44780
int init_hd44780(int fd) {
    if (send_command(fd, HD44780_FUNCTION_SET) != 0) return -1;
    usleep(5000); // Wait 5ms
    if (send_command(fd, HD44780_DISPLAY_CONTROL) != 0) return -1;
    usleep(5000); // Wait 5ms
    if (send_command(fd, HD44780_ENTRY_MODE_SET) != 0) return -1;
    usleep(5000); // Wait 5ms
    if (send_command(fd, HD44780_CLEAR_DISPLAY) != 0) return -1;
    usleep(5000); // Wait 5ms
    if (send_command(fd, HD44780_SET_CURSOR) != 0) return -1;
    usleep(5000); // Wait 5ms
    return 0;
}

// Function to display a string on the HD44780
int display_string(int fd, const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        unsigned char buf[2];
        buf[0] = 0x40; // Control byte: data
        buf[1] = str[i];
        if (write(fd, buf, 2) != 2) {
            perror("Failed to send data");
            return -1;
        }
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the HD44780
    if (ioctl(i2c_fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the HD44780
    if (init_hd44780(i2c_fd) != 0) {
        fprintf(stderr, "HD44780 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Get current time
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format time string
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Display time string
        if (display_string(i2c_fd, time_str) != 0) {
            fprintf(stderr, "Failed to display time.\n");
        }

        // Wait 10 seconds
        sleep(10);
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);
    return 0;
}

