    // Read accelerometer data (6 bytes: X, Y, Z)
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading accelerometer data");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Read and print accelerometer data 100 times
    for (int i = 0; i < 100; i++) {
        int16_t x, y, z;

        if (read_accelerometer(&x, &y, &z) == 0) {
            printf("Accelerometer: X=%d, Y=%d, Z=%d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define OUTPUT_PIN 14
#define INPUT_PIN 15

// Define the duration of the output pulse (in milliseconds)
#define PULSE_DURATION_MS 100

// Define the delay between pulses (in seconds)
#define DELAY_SECONDS 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *output_line;
    struct gpiod_line *input_line;
} gpio_context_t;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to initialize the GPIO lines
int initialize_gpio(gpio_context_t *context) {
    context->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!context->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    context->output_line = gpiod_chip_get_line(context->chip, OUTPUT_PIN);
    if (!context->output_line) {
        perror("Error getting output GPIO line");
        gpiod_chip_close(context->chip);
        return -1;
    }

    context->input_line = gpiod_chip_get_line(context->chip, INPUT_PIN);
    if (!context->input_line) {
        perror("Error getting input GPIO line");
        gpiod_line_release(context->output_line);
        gpiod_chip_close(context->chip);
        return -1;
    }

    // Set output line as output
    if (gpiod_line_request_output(context->output_line, "output", 0) < 0) {
        perror("Error requesting output line");
        gpiod_line_release(context->input_line);
        gpiod_line_release(context->output_line);
        gpiod_chip_close(context->chip);
        return -1;
    }

    // Set input line as input
    if (gpiod_line_request_input(context->input_line, "input") < 0) {
        perror("Error requesting input line");
        gpiod_line_release(context->output_line);
        gpiod_chip_close(context->chip);
        return -1;
    }

    return 0;
}

// Function to read the input GPIO line
int read_input_gpio(gpio_context_t *context) {
    int value = gpiod_line_get_value(context->input_line);
    if (value < 0) {
        perror("Error reading input GPIO value");
        return -1;
    }
    return value;
}

// Function to set the output GPIO line
int set_output_gpio(gpio_context_t *context, int value) {
    if (gpiod_line_set_value(context->output_line, value) < 0) {
        perror("Error setting output GPIO value");
        return -1;
    }
    return 0;
}

// Function to release the GPIO lines and close the chip
void cleanup_gpio(gpio_context_t *context) {
    gpiod_line_release(context->output_line);
    gpiod_line_release(context->input_line);
    gpiod_chip_close(context->chip);
}

int main() {
    gpio_context_t gpio_context;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_context) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read input GPIO
        int input_value = read_input_gpio(&gpio_context);
        if (input_value < 0) {
            fprintf(stderr, "Error reading input GPIO. Continuing.\n");
            sleep(DELAY_SECONDS);
            continue;
        }

        // Check if input is valid (0 or 1)
        if (input_value != 0 && input_value != 1) {
            fprintf(stderr, "Invalid input value: %d. Skipping this cycle.\n", input_value);
            sleep(DELAY_SECONDS);
            continue;
        }

        // Set output GPIO based on input value
        if (set_output_gpio(&gpio_context, input_value) < 0) {
            fprintf(stderr, "Error setting output GPIO. Continuing.\n");
        } else {
            // If output is set to 1, generate a pulse
            if (input_value == 1) {
                struct timespec pulse_duration = {0, PULSE_DURATION_MS * 1000000L}; // 100ms
                nanosleep(&pulse_duration, NULL);
                if (set_output_gpio(&gpio_context, 0) < 0) {
                    fprintf(stderr, "Error setting output GPIO to 0. Continuing.\n");
                }
            }
        }

        // Print the current state
        printf("Input: %d, Output: %d\n", input_value, input_value);

        // Wait for the specified delay
        sleep(DELAY_SECONDS);
    }

    // Cleanup GPIO
    cleanup_gpio(&gpio_context);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable_sensor_data"
#define SENSOR_PIN 4 // GPIO pin connected to the sensor
#define READ_INTERVAL_MS 10 // 10 milliseconds
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define VALID_READING_MIN 0
#define VALID_READING_MAX 1023

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor();
int validate_reading(int reading);
int publish_reading(int reading);
void signal_handler(int signum);
int mqtt_connect_and_subscribe();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Reads the sensor value from the specified GPIO pin
int read_sensor() {
    int reading = gpioRead(SENSOR_PIN);
    return reading;
}

// Validates the sensor reading
int validate_reading(int reading) {
    if (reading >= VALID_READING_MIN && reading <= VALID_READING_MAX) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Publishes the sensor reading to the MQTT broker
int publish_reading(int reading) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%d", reading);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }
    return 0;
}

// Connects to the MQTT broker and subscribes to the topic
int mqtt_connect_and_subscribe() {
    int ret;

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(ret));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Initialize MQTT
    if (mqtt_connect_and_subscribe() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting sensor data publishing...\n");

    while (running) {
        int reading = read_sensor();

        if (validate_reading(reading)) {
            if (publish_reading(reading) != 0) {
                fprintf(stderr, "Failed to publish reading.\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor reading: %d\n", reading);
        }

        gpioDelay(READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

