    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    /* Register signal handlers */
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "GPIO %d requested for output.\n", GPIO_PIN);

    /* Main loop */
    while (!terminate) {
        /* Set GPIO high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Failed to set GPIO high");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        /* Sleep for 1 second */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
            break;
        }

        /* Set GPIO low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Failed to set GPIO low");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        /* Sleep for 1 second */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep failed");
            break;
        }
    }

    /* Release GPIO line */
    if (line) {
        gpiod_line_release(line);
        fprintf(stderr, "GPIO %d released.\n", GPIO_PIN);
    }

    /* Close GPIO chip */
    if (chip) {
        gpiod_chip_close(chip);
        fprintf(stderr, "GPIO chip closed.\n");
    }

    return EXIT_SUCCESS;
