#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio18_line = NULL;
struct gpiod_line *gpio24_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio18_line, struct gpiod_line **gpio24_line);
int set_gpio_output(struct gpiod_line *gpio_line, int value);
int report_state(int gpio18_state, int gpio24_state);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio18_line, struct gpiod_line *gpio24_line);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio(chip, gpio18_line, gpio24_line);
    exit(0);
}

// Initialize GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio18_line, struct gpiod_line **gpio24_line) {
    int ret;

    // Open GPIO chip
    *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get GPIO line for GPIO 18
    *gpio18_line = gpiod_chip_get_line(*chip, GPIO_18);
    if (!*gpio18_line) {
        perror("Error getting GPIO 18 line");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get GPIO line for GPIO 24
    *gpio24_line = gpiod_chip_get_line(*chip, GPIO_24);
    if (!*gpio24_line) {
        perror("Error getting GPIO 24 line");
        gpiod_line_release(*gpio18_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request GPIO 18 as output
    ret = gpiod_line_request_output(*gpio18_line, "gpio18_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 18 as output");
        gpiod_line_release(*gpio24_line);
        gpiod_line_release(*gpio18_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request GPIO 24 as output
    ret = gpiod_line_request_output(*gpio24_line, "gpio24_output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 24 as output");
        gpiod_line_set_value(*gpio18_line, 0);
        gpiod_line_release(*gpio24_line);
        gpiod_line_release(*gpio18_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Set GPIO output value
int set_gpio_output(struct gpiod_line *gpio_line, int value) {
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Report GPIO states
int report_state(int gpio18_state, int gpio24_state) {
    printf("GPIO 18: %d, GPIO 24: %d\n", gpio18_state, gpio24_state);
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio18_line, struct gpiod_line *gpio24_line) {
    if (gpio18_line) {
        gpiod_line_set_value(gpio18_line, 0); // Set to a safe state (LOW)
        gpiod_line_release(gpio18_line);
    }
    if (gpio24_line) {
        gpiod_line_set_value(gpio24_line, 0); // Set to a safe state (LOW)
        gpiod_line_release(gpio24_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &gpio18_line, &gpio24_line) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Set GPIO 18 to HIGH
    if (set_gpio_output(gpio18_line, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO 18 HIGH.\n");
        cleanup_gpio(chip, gpio18_line, gpio24_line);
        return 1;
    }

    // Report state
    if (report_state(1, 0) != 0) {
        fprintf(stderr, "Failed to report state.\n");
        cleanup_gpio(chip, gpio18_line, gpio24_line);
        return 1;
    }

    // Set GPIO 24 to HIGH
    if (set_gpio_output(gpio24_line, 1) != 0) {
        fprintf(stderr, "Failed to set GPIO 24 HIGH.\n");
        cleanup_gpio(chip, gpio18_line, gpio24_line);
        return 1;
    }

    // Report state
    if (report_state(1, 1) != 0) {
        fprintf(stderr, "Failed to report state.\n");
        cleanup_gpio(chip, gpio18_line, gpio24_line);
        return 1;
    }

    // Cleanup GPIO resources
    cleanup_gpio(chip, gpio18_line, gpio24_line);

    return 0;
}

