    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %d\n", ret);
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO line
int get_gpio_state(struct gpiod_line *line) {
    int state = gpiod_line_get_value(line);
    if (state < 0) {
        fprintf(stderr, "Error getting GPIO state\n");
        return -1;
    }
    return state;
}

int main() {
    int ret;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio2_line = gpiod_chip_get_line(chip, GPIO_2);
    gpio3_line = gpiod_chip_get_line(chip, GPIO_3);
    gpio23_line = gpiod_chip_get_line(chip, GPIO_23);

    if (!gpio2_line || !gpio3_line || !gpio23_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio2_line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_2);
        gpiod_chip_close(chip);
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_line_release(gpio23_line);
        return 1;
    }

    ret = gpiod_line_request_output(gpio3_line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_3);
        gpiod_chip_close(chip);
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_line_release(gpio23_line);
        return 1;
    }

    ret = gpiod_line_request_output(gpio23_line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_23);
        gpiod_chip_close(chip);
        gpiod_line_release(gpio2_line);
        gpiod_line_release(gpio3_line);
        gpiod_line_release(gpio23_line);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        if (set_gpio_state(gpio2_line, 1) < 0) goto cleanup;
        if (set_gpio_state(gpio3_line, 0) < 0) goto cleanup;
        if (set_gpio_state(gpio23_line, 1) < 0) goto cleanup;

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and GPIO states
        printf("%s - GPIO 2: %d, GPIO 3: %d, GPIO 23: %d\n", timestamp, get_gpio_state(gpio2_line), get_gpio_state(gpio3_line), get_gpio_state(gpio23_line));

        // Wait for 2 seconds
        sleep(2);

        // Set GPIO states
        if (set_gpio_state(gpio2_line, 0) < 0) goto cleanup;
        if (set_gpio_state(gpio3_line, 1) < 0) goto cleanup;
        if (set_gpio_state(gpio23_line, 0) < 0) goto cleanup;

        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and GPIO states
        printf("%s - GPIO 2: %d, GPIO 3: %d, GPIO 23: %d\n", timestamp, get_gpio_state(gpio2_line), get_gpio_state(gpio3_line), get_gpio_state(gpio23_line));

        // Wait for 2 seconds
        sleep(2);
    }

cleanup:
    // Cleanup and exit
    signal_handler(SIGINT);
    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define UDP_IP "127.0.0.1" // Replace with the IP address of the receiving device
#define UDP_PORT 5000
#define SENSOR_PIN 4 // GPIO pin connected to the sensor
#define READ_INTERVAL_SEC 5

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;

// Structure to hold MQTT client configuration
typedef struct {
    char *host;
    int port;
    char *topic;
} mqtt_config_t;

// Structure to hold UDP client configuration
typedef struct {
    char *ip;
    int port;
} udp_config_t;

// Function prototypes
int read_sensor();
int publish_mqtt(const char *message);
int send_udp(const char *message);
void signal_handler(int sig);

// MQTT client instance
struct mosquitto *mqtt_client = NULL;

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to publish data to MQTT broker
int publish_mqtt(const char *message) {
    int ret;

    ret = mosquitto_publish(mqtt_client, NULL, MQTT_TOPIC, strlen(message), message, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing to MQTT: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Function to send data via UDP
int send_udp(const char *message) {
    int sockfd;
    struct sockaddr_in servaddr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(UDP_PORT);
    if (inet_pton(AF_INET, UDP_IP, &servaddr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sockfd);
        return -1;
    }

    if (sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    int sensor_value;
    char message[50];
    time_t rawtime;
    struct tm *timeinfo;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Initialize MQTT
    mosquitto_lib_init();
    mqtt_client = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client) {
        fprintf(stderr, "Error: Out of memory.\n");
        gpioTerminate();
        return 1;
    }

    int ret = mosquitto_connect(mqtt_client, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mqtt_client);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mqtt_client);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_value = read_sensor();

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        snprintf(message, sizeof(message), "%ld,%d", rawtime, sensor_value);

        if (publish_mqtt(message) != 0) {
            fprintf(stderr, "Failed to publish MQTT message.\n");
        }

        if (send_udp(message) != 0) {
            fprintf(stderr, "Failed to send UDP message.\n");
        }

        sleep(READ_INTERVAL_SEC);
    }

    // Cleanup
    mosquitto_loop_stop(mqtt_client, false);
    mosquitto_disconnect(mqtt_client);
    mosquitto_destroy(mqtt_client);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pwm_value;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Generate a sequence of PWM values
        for (pwm_value = 0; pwm_value <= PWM_RANGE; pwm_value += 100) {
            gpioPWM(GPIO_PIN, pwm_value);
            printf("PWM value: %d\n", pwm_value);
            sleep(1);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and terminate pigpio
    gpioPWM(GPIO_PIN, 0); // Stop PWM
    gpioTerminate();

    printf("PWM control stopped.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout in microseconds (0.2 seconds)

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *trigger_line;
static struct gpiod_line *echo_line;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void trigger_pulse(void);
long pulse_width(void);
float distance(long pulse_width);
void report_distance(float distance);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize GPIO pins
int init_gpio(void) {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        perror("Error getting trigger line");
        gpiod_chip_close(chip);
        return -1;
    }

    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        perror("Error getting echo line");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(trigger_line, "trigger", 0) < 0) {
        perror("Error requesting trigger line as output");
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(echo_line, "echo") < 0) {
        perror("Error requesting echo line as input");
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Send a 10us trigger pulse
void trigger_pulse(void) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        perror("Error setting trigger line high");
        return;
    }
    usleep(10); // 10 microseconds
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        perror("Error setting trigger line low");
    }
}

// Measure the pulse width of the echo signal
long pulse_width(void) {
    struct timespec start, end;
    long width = 0;

    // Wait for the echo line to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    // Measure the pulse width
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
    clock_gettime(CLOCK_MONOTONIC, &end);
    width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;

    return width;
}

// Calculate the distance in centimeters
float distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Report the distance to standard output
void report_distance(float distance) {
    if (distance < 0) {
        printf("Error: No echo received or timeout occurred.\n");
    } else {
        printf("Distance: %.2f cm\n", distance);
    }
}

// Cleanup GPIO resources
void cleanup_gpio(void) {
    if (trigger_line) {
        gpiod_line_release(trigger_line);
    }
    if (echo_line) {
        gpiod_line_release(echo_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (!terminate) {
        trigger_pulse();
        long pulse_width = pulse_width();
        float distance = distance(pulse_width);
        report_distance(distance);
        usleep(200000); // 0.2 seconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

#include <stdio.h>
