        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio_pin);
    }
}

// Function to report the current PWM states
void report_pwm_states() {
    int pwm1_state = gpioGetPWMdutycycle(PWM_PIN_1);
    int pwm2_state = gpioGetPWMdutycycle(PWM_PIN_2);
    int pwm3_state = gpioGetPWMdutycycle(PWM_PIN_3);
    int pwm4_state = gpioGetPWMdutycycle(PWM_PIN_4);

