}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to PWM output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);

    // Set PWM range for all pins
    gpioSetPWMrange(PWM_PIN_1, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_2, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_3, PWM_RANGE);
    gpioSetPWMrange(PWM_PIN_4, PWM_RANGE);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Set PWM duty cycles (example values)
        set_pwm_duty_cycle(PWM_PIN_1, 128);
        set_pwm_duty_cycle(PWM_PIN_2, 64);
        set_pwm_duty_cycle(PWM_PIN_3, 192);
        set_pwm_duty_cycle(PWM_PIN_4, 32);

        // Report PWM states
        report_pwm_states();

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "wearable/sensor_data"
#define SENSOR_PIN 4 // GPIO pin connected to the sensor
#define READ_INTERVAL_MS 1000 // Read sensor every 1 second
#define TIMEOUT_MS 500 // Timeout for sensor read (500ms)
#define VALID_READING_MIN 0
#define VALID_READING_MAX 1023

// Global variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;

// Function prototypes
int read_sensor();
int publish_data(int sensor_value);
void signal_handler(int signum);
int mqtt_connect_and_subscribe();

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signum);
}

// Reads the sensor value from the specified GPIO pin
int read_sensor() {
    int value = gpioRead(SENSOR_PIN);
    return value;
}

// Publishes the sensor data to the MQTT broker
int publish_data(int sensor_value) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"sensor_value\": %d}", sensor_value);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

// Connects to the MQTT broker and subscribes to the topic
int mqtt_connect_and_subscribe() {
    int ret;

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    ret = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error subscribing to topic: %s\n", mosquitto_strerror(ret));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT
    if (mqtt_connect_and_subscribe() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Starting sensor data collection and publishing...\n");

    while (running) {
        int sensor_value = read_sensor();

        // Validate sensor reading
        if (sensor_value >= VALID_READING_MIN && sensor_value <= VALID_READING_MAX) {
            if (publish_data(sensor_value) != 0) {
                fprintf(stderr, "Failed to publish data.\n");
            }
        } else {
            fprintf(stderr, "Invalid sensor reading: %d\n", sensor_value);
        }

        gpioDelay(READ_INTERVAL_MS); // Wait before next reading
    }

    // Cleanup
    printf("Cleaning up...\n");
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_DEFAULT 0x4003 // Single-shot mode, +/-4.096V, 128 SPS, AIN0
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/ads1115"
#define NUM_READINGS 10

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int16_t *reading);
int publish_reading(int16_t reading);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int16_t *reading) {
    char buf[2];
    int result;

    // Write configuration register
    buf[0] = ADS1115_REG_CONFIG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    // Write configuration value
    buf[0] = ADS1115_CONFIG_DEFAULT >> 8; // MSB
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing config MSB: %d\n", result);
        return -1;
    }

    buf[0] = ADS1115_CONFIG_DEFAULT & 0xFF; // LSB
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing config LSB: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion register
    buf[0] = ADS1115_REG_CONVERT;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to convert register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from convert register: %d\n", result);
        return -1;
    }

    *reading = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

// Publish reading to MQTT broker
int publish_reading(int16_t reading) {
    char payload[50];
    int ret;

    snprintf(payload, sizeof(payload), "%d", reading);

    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error publishing message: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

int main() {
    int16_t reading;
    int i;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    for (i = 0; i < NUM_READINGS && !terminate; i++) {
        if (read_ads1115(&reading) == 0) {
            if (publish_reading(reading) != 0) {
                fprintf(stderr, "Error publishing reading %d\n", i + 1);
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio18_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio17_line, struct gpiod_line **gpio18_line);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio17_line, struct gpiod_line *gpio18_line);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, gpio17_line, gpio18_line);
    exit(0);
}

// Initializes the GPIO chip and lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio17_line, struct gpiod_line **gpio18_line) {
    int ret;

    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 17
    *gpio17_line = gpiod_chip_get_line(*chip, GPIO_17);
    if (!*gpio17_line) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 18
    *gpio18_line = gpiod_chip_get_line(*chip, GPIO_18);
    if (!*gpio18_line) {
        perror("Error getting GPIO 18 line");
        gpiod_line_release(*gpio17_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(*gpio17_line, "gpio17", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(*gpio18_line);
        gpiod_line_release(*gpio17_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_output(*gpio18_line, "gpio18", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(*gpio17_line);
        gpiod_line_release(*gpio18_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Cleans up the GPIO lines and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio17_line, struct gpiod_line *gpio18_line) {
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 50000000; // 0.05 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &gpio17_line, &gpio18_line) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 to 1
        if (set_gpio_value(gpio17_line, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO 17 to 1. Continuing.\n");
        } else {
            printf("GPIO 17 set to 1\n");
        }

        // Set GPIO 18 to 0
        if (set_gpio_value(gpio18_line, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO 18 to 0. Continuing.\n");
        } else {
            printf("GPIO 18 set to 0\n");
        }

        // Sleep for 0.05 seconds
        ret = nanosleep(&sleep_time, NULL);
        if (ret != 0) {
            perror("nanosleep failed");
        }
    }

    return 0;
}

