#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    ssize_t bytes_read;

    printf("Reading from UART %s...\n", UART_DEVICE);

    while (program_running) {
        bytes_read = read(uart_fd, buffer, sizeof(buffer) - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break;
        }
        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    close(uart_fd);
    printf("UART port closed.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read register data");
        return -1;
    }

    return data;
}

// Function to write a single byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = read_i2c_reg(fd, ACCEL_XOUT_H);
    x_l = read_i2c_reg(fd, ACCEL_XOUT_L);
    y_h = read_i2c_reg(fd, ACCEL_YOUT_H);
    y_l = read_i2c_reg(fd, ACCEL_YOUT_L);
    z_h = read_i2c_reg(fd, ACCEL_ZOUT_H);
    z_l = read_i2c_reg(fd, ACCEL_ZOUT_L);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0; // Indicate success
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int16_t accel_x, accel_y, accel_z;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (write_i2c_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            // Print accelerometer data
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
