#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize the BMP280 sensor
int bmp280_init(int fd) {
    // Set the sensor to forced mode
    if (i2c_smbus_write_byte_data(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) { // Oversampling x1, forced mode
        fprintf(stderr, "Error writing to CTRL_MEAS register: %s\n", strerror(errno));
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_smbus_read_i2c_block_data(fd, BMP280_REG_CALIB_00, (char *)calib_data, 26) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        return -1;
    }

    calib.dig_T1 = (uint16_t)calib_data[0] | ((uint16_t)calib_data[1] << 8);
    calib.dig_T2 = (int16_t)calib_data[2] | ((int16_t)calib_data[3] << 8);
    calib.dig_T3 = (int16_t)calib_data[4] | ((int16_t)calib_data[5] << 8);
    calib.dig_P1 = (uint16_t)calib_data[6] | ((uint16_t)calib_data[7] << 8);
    calib.dig_P2 = (int16_t)calib_data[8] | ((int16_t)calib_data[9] << 8);
    calib.dig_P3 = (int16_t)calib_data[10] | ((int16_t)calib_data[11] << 8);
    calib.dig_P4 = (int16_t)calib_data[12] | ((int16_t)calib_data[13] << 8);
    calib.dig_P5 = (int16_t)calib_data[14] | ((int16_t)calib_data[15] << 8);
    calib.dig_P6 = (int16_t)calib_data[16] | ((int16_t)calib_data[17] << 8);
    calib.dig_P7 = (int16_t)calib_data[18] | ((int16_t)calib_data[19] << 8);
    calib.dig_P8 = (int16_t)calib_data[20] | ((int16_t)calib_data[21] << 8);
    calib.dig_P9 = (int16_t)calib_data[22] | ((int16_t)calib_data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];

    // Read 6 bytes of data starting from pressure MSB register
    if (i2c_smbus_read_i2c_block_data(fd, BMP280_REG_PRESS_MSB, (char *)data, 6) < 0) {
        fprintf(stderr, "Error reading raw data: %s\n", strerror(errno));
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
double bmp280_compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Function to compensate pressure
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int retry_count = 0;
    const int max_retries = 3;
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed. Retrying...\n");
        close(i2c_fd);
        return 1;
    }

    printf("BMP280 sensor initialized successfully.\n");

    // Main loop
    while (program_running) {
        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) == 0) {
            // Compensate temperature and pressure
            temperature = bmp280_compensate_temperature(raw_temperature);
            pressure = bmp280_compensate_pressure(raw_pressure, temperature);

            // Print the compensated values
            printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", temperature, pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 4 // BCM numbering
#define PWM_FREQUENCY 1000 // Hz
#define PWM_DUTY_CYCLE 128 // 50% duty cycle (0-255)

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    // Set PWM duty cycle
    gpioPWM(PWM_GPIO, PWM_DUTY_CYCLE);

    printf("PWM output started on GPIO %d with frequency %d Hz and duty cycle %d (50%%)\n", PWM_GPIO, PWM_FREQUENCY, PWM_DUTY_CYCLE);

    // Keep the program running until a signal is received
    while (program_running) {
        gpioDelay(100000); // Sleep for 0.1 seconds (100000 microseconds)
    }

    // Stop PWM output
    gpioPWM(PWM_GPIO, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("PWM output stopped and pigpio terminated.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

// Define GPIO pins
#define GPIO5 5
#define GPIO6 6
#define GPIO13 13

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio5_line = NULL;
struct gpiod_line *gpio6_line = NULL;
struct gpiod_line *gpio13_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int set_gpio_state(struct gpiod_line *line, int value);
int get_gpio_state(struct gpiod_line *line);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (gpio5_line) {
        gpiod_line_release(gpio5_line);
    }
    if (gpio6_line) {
        gpiod_line_release(gpio6_line);
    }
    if (gpio13_line) {
        gpiod_line_release(gpio13_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int value) {
    int ret;

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", line->number, value, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO line
int get_gpio_state(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %s\n", line->number, strerror(-value));
        return -1;
    }
    return value;
}

int main() {
    int ret;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get GPIO lines
    gpio5_line = gpiod_chip_get_line(chip, GPIO5);
    gpio6_line = gpiod_chip_get_line(chip, GPIO6);
    gpio13_line = gpiod_chip_get_line(chip, GPIO13);

    if (!gpio5_line || !gpio6_line || !gpio13_line) {
        fprintf(stderr, "Error getting GPIO line %d, %d, or %d\n", GPIO5, GPIO6, GPIO13);
        if (gpio5_line) gpiod_line_release(gpio5_line);
        if (gpio6_line) gpiod_line_release(gpio6_line);
        if (gpio13_line) gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(gpio5_line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO5, strerror(-ret));
        gpiod_line_release(gpio5_line);
        gpiod_line_release(gpio6_line);
        gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio6_line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO6, strerror(-ret));
        gpiod_line_release(gpio5_line);
        gpiod_line_release(gpio6_line);
        gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(gpio13_line, "my_app", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO13, strerror(-ret));
        gpiod_line_release(gpio5_line);
        gpiod_line_release(gpio6_line);
        gpiod_line_release(gpio13_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set initial state (LOW)
    if (set_gpio_state(gpio5_line, 0) < 0) return 1;
    if (set_gpio_state(gpio6_line, 0) < 0) return 1;
    if (set_gpio_state(gpio13_line, 0) < 0) return 1;

    // Print initial state
    printf("GPIO 5: %d, GPIO 6: %d, GPIO 13: %d\n", get_gpio_state(gpio5_line), get_gpio_state(gpio6_line), get_gpio_state(gpio13_line));

    // Set state to HIGH
    if (set_gpio_state(gpio5_line, 1) < 0) return 1;
    if (set_gpio_state(gpio6_line, 1) < 0) return 1;
    if (set_gpio_state(gpio13_line, 1) < 0) return 1;

    // Print updated state
    printf("GPIO 5: %d, GPIO 6: %d, GPIO 13: %d\n", get_gpio_state(gpio5_line), get_gpio_state(gpio6_line), get_gpio_state(gpio13_line));

    // Wait for a signal (Ctrl+C)
    pause();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>

#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/reading"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"

struct mosquitto *mosq = NULL;

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, cleaning up and exiting...\n");
        if (mosq) {
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
        }
        mosquitto_lib_cleanup();
        exit(0);
    }
}

int main() {
    int rc;
    char payload[100];
    time_t rawtime;
    struct tm *timeinfo;

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return 1;
    }

    // Configure MQTT broker address and port
    rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop: publish sensor readings
    while (1) {
        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);

        // Format the timestamp as a string
        strftime(payload, sizeof(payload), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Publish the reading to the MQTT topic
        rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
        if (rc != MOSQ_ERR_SUCCESS) {
            fprintf(stderr, "Error: Could not publish message: %s\n", mosquitto_strerror(rc));
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (this part will not be reached in the infinite loop)
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM duty cycle (percentage)
#define PWM_DUTY_CYCLE 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set PWM duty cycle on a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    int range = gpioGetPWMrealRange(gpio_pin);
    if (range < 0) {
        fprintf(stderr, "Error: Could not get PWM range for GPIO %d\n", gpio_pin);
        return -1;
    }

    int pwm_value = (int)(((float)duty_cycle / 100.0) * range);
    gpioPWM(gpio_pin, pwm_value);
    return 0;
}

// Function to report the current state of all GPIO pins
void report_state() {
    int state1 = gpioRead(PWM_PIN_1);
    int state2 = gpioRead(PWM_PIN_2);
    int state3 = gpioRead(PWM_PIN_3);
    int state4 = gpioRead(PWM_PIN_4);
    int state5 = gpioRead(PWM_PIN_5);

    printf("GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d, GPIO %d: %d\n",
           PWM_PIN_1, state1, PWM_PIN_2, state2, PWM_PIN_3, state3, PWM_PIN_4, state4, PWM_PIN_5, state5);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_4, PI_OUTPUT);
    gpioSetMode(PWM_PIN_5, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_5, PWM_FREQUENCY);

    // Set PWM duty cycle for all GPIO pins
    if (set_pwm_duty_cycle(PWM_PIN_1, PWM_DUTY_CYCLE) != 0 ||
        set_pwm_duty_cycle(PWM_PIN_2, PWM_DUTY_CYCLE) != 0 ||
        set_pwm_duty_cycle(PWM_PIN_3, PWM_DUTY_CYCLE) != 0 ||
        set_pwm_duty_cycle(PWM_PIN_4, PWM_DUTY_CYCLE) != 0 ||
        set_pwm_duty_cycle(PWM_PIN_5, PWM_DUTY_CYCLE) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle on one or more GPIO pins\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        report_state();
        gpioDelay(1000); // Delay for 1 second (1000 ms)
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(PWM_PIN_1, 0);
    gpioPWM(PWM_PIN_2, 0);
    gpioPWM(PWM_PIN_3, 0);
    gpioPWM(PWM_PIN_4, 0);
    gpioPWM(PWM_PIN_5, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to report the current PWM states
void report_pwm_states() {
    int pwm1_state = gpioGetPWMdutycycle(PWM_PIN_1);
    int pwm2_state = gpioGetPWMdutycycle(PWM_PIN_2);
    int pwm3_state = gpioGetPWMdutycycle(PWM_PIN_3);

    printf("PWM1: %d, PWM2: %d, PWM3: %d\n", pwm1_state, pwm2_state, pwm3_state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to PWM output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_1, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Set PWM duty cycles (0-255)
        set_pwm_duty_cycle(PWM_PIN_1, 128);
        set_pwm_duty_cycle(PWM_PIN_2, 64);
        set_pwm_duty_cycle(PWM_PIN_3, 192);

        // Report PWM states
        report_pwm_states();

        // Delay for 50 milliseconds
        gpioDelay(50000); // Delay in microseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int fd = -1;
static int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main()
{
    const char *dev_name = "/dev/video0";
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct buffer *buffers;
    unsigned int n_buffers;
    struct v4l2_buffer buf;
    char buffer_name[64];
    FILE *fp;
    int i;

    signal(SIGINT, signal_handler);

    if (-1 == (fd = open(dev_name, O_RDWR | O_NONBLOCK, 0))) {
        perror("Cannot open device");
        exit(1);
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        exit(1);
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        close(fd);
        exit(1);
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        close(fd);
        exit(1);
    }

    CLEAR(fmt);

    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(fd);
        exit(1);
    }

    CLEAR(req);

    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", dev_name);
            close(fd);
            exit(1);
        } else {
            perror("VIDIOC_REQBUFS");
            close(fd);
            exit(1);
        }
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", dev_name);
        close(fd);
        exit(1);
    }

    buffers = calloc(req.count, sizeof(*buffers));

    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        exit(1);
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            exit(1);
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd);
            exit(1);
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        snprintf(buffer_name, sizeof(buffer_name), "buffer_%d", i);
        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            close(fd);
            exit(1);
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        close(fd);
        exit(1);
    }

    while (running) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            perror("select");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            perror("VIDIOC_DQBUF");
            break;
        }

        fp = fopen("capture.jpg", "wb");
        if (fp == NULL) {
            perror("fopen");
            break;
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        snprintf(buffer_name, sizeof(buffer_name), "capture_%d.jpg", time(NULL));
        if (rename("capture.jpg", buffer_name) != 0) {
            perror("rename");
        }

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            break;
        }
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
        }
    }

    free(buffers);
    close(fd);

    return 0;
}

