#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line2;
struct gpiod_line *line3;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line2, line3);
    exit(0);
}

// Initializes the GPIO chip and lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line2, struct gpiod_line **line3) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    *line2 = gpiod_chip_get_line(*chip, GPIO_2);
    if (!*line2) {
        perror("Error getting GPIO line 2");
        gpiod_chip_close(*chip);
        return -1;
    }

    *line3 = gpiod_chip_get_line(*chip, GPIO_3);
    if (!*line3) {
        perror("Error getting GPIO line 3");
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line2, "my_program", 0) < 0) {
        perror("Error requesting GPIO line 2 for output");
        gpiod_line_release(*line3);
        gpiod_line_release(*line2);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line3, "my_program", 0) < 0) {
        perror("Error requesting GPIO line 3 for output");
        gpiod_line_release(*line2);
        gpiod_line_release(*line3);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line2, struct gpiod_line *line3) {
    if (line2) {
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_release(line3);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line2, &line3) < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 2 to 1
        if (set_gpio_value(line2, 1) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        printf("GPIO 2 set to 1\n");

        // Set GPIO 3 to 0
        if (set_gpio_value(line3, 0) < 0) {
            cleanup_gpio(chip, line2, line3);
            return 1;
        }
        printf("GPIO 3 set to 0\n");

        // Wait for 0.5 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000; // 0.5 seconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio27_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int set_gpio_state(int gpio_pin, int state);
int get_gpio_state(int gpio_pin);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_27) {
        line = gpio27_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", gpio_pin, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio_pin) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_27) {
        line = gpio27_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d value: %s\n", gpio_pin, strerror(-value));
        return -1;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    if (!gpio17_line) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return 1;
    }

    gpio27_line = gpiod_chip_get_line(chip, GPIO_27);
    if (!gpio27_line) {
        perror("Error getting GPIO 27 line");
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio17_line, "my_app", 0) < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(gpio27_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(gpio27_line, "my_app", 0) < 0) {
        perror("Error requesting GPIO 27 for output");
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio27_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 to 1
        if (set_gpio_state(GPIO_17, 1) == 0) {
            printf("GPIO 17 set to 1\n");
        } else {
            fprintf(stderr, "Failed to set GPIO 17 to 1\n");
        }

        // Set GPIO 27 to 0
        if (set_gpio_state(GPIO_27, 0) == 0) {
