#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_19 19

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio18_line = NULL;
struct gpiod_line *gpio19_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio18_line, struct gpiod_line **gpio19_line);
int set_gpio_value(struct gpiod_line *line, int value);
int get_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio18_line, struct gpiod_line *gpio19_line);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, gpio18_line, gpio19_line);
    exit(0);
}

// Initializes the GPIO chip and lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **gpio18_line, struct gpiod_line **gpio19_line) {
    int ret;

    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 18
    *gpio18_line = gpiod_chip_get_line(*chip, GPIO_18);
    if (!*gpio18_line) {
        perror("Error getting GPIO 18 line");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 19
    *gpio19_line = gpiod_chip_get_line(*chip, GPIO_19);
    if (!*gpio19_line) {
        perror("Error getting GPIO 19 line");
        gpiod_line_release(*gpio18_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(*gpio18_line, "gpio18", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(*gpio19_line);
        gpiod_line_release(*gpio18_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    ret = gpiod_line_request_output(*gpio19_line, "gpio19", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 19 for output");
        gpiod_line_release(*gpio18_line);
        gpiod_line_release(*gpio19_line);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }
    return value;
}

// Cleans up the GPIO lines and chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *gpio18_line, struct gpiod_line *gpio19_line) {
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (gpio19_line) {
        gpiod_line_release(gpio19_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int gpio18_value, gpio19_value;
    struct timespec sleep_time;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &gpio18_line, &gpio19_line) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 0.5 seconds

    while (1) {
        // Set GPIO 18 to 1
        if (set_gpio_value(gpio18_line, 1) != 0) {
            cleanup_gpio(chip, gpio18_line, gpio19_line);
            return 1;
        }

        // Get and print the value of GPIO 18
        gpio18_value = get_gpio_value(gpio18_line);
        if (gpio18_value < 0) {
            cleanup_gpio(chip, gpio18_line, gpio19_line);
            return 1;
        }
        printf("GPIO 18: %d\n", gpio18_value);

        // Set GPIO 19 to 0
        if (set_gpio_value(gpio19_line, 0) != 0) {
            cleanup_gpio(chip, gpio18_line, gpio19_line);
            return 1;
        }

        // Get and print the value of GPIO 19
        gpio19_value = get_gpio_value(gpio19_line);
        if (gpio19_value < 0) {
            cleanup_gpio(chip, gpio18_line, gpio19_line);
            return 1;
        }
        printf("GPIO 19: %d\n", gpio19_value);

        // Sleep for 0.5 seconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define MAX_BUFFER 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 5; // Wait for 0.5 seconds (5 * 0.1s)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[MAX_BUFFER];
    ssize_t bytes_read;

    printf("Reading from UART %s...\n", UART_DEVICE);

    while (program_running) {
        bytes_read = read(uart_fd, buffer, MAX_BUFFER - 1);
        if (bytes_read > 0) {
            buffer[bytes_read] = '\0'; // Null-terminate the string
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            perror("Error reading from UART");
            break;
        }
        usleep(100000); // Sleep for 100ms to avoid busy-waiting
    }

    close(uart_fd);
    printf("UART port closed.\n");

    return EXIT_SUCCESS;
}

