#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time = {2, 0}; // 2 seconds
    int state = 1; // Start with HIGH

    // Register signal handler for SIGINT (Ctrl+C)
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request(line, "output", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to output mode.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Set GPIO state
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        // Print current state
        printf("GPIO %d set to %s\n", GPIO_PIN, state ? "HIGH" : "LOW");

        // Toggle state
        state = !state;

        // Sleep for 2 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Release GPIO line
    gpiod_line_release(line);
    printf("GPIO %d released.\n", GPIO_PIN);

    // Close GPIO chip
    gpiod_chip_close(chip);
    printf("GPIO chip closed.\n");

    return 0;
}

