#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define DHT22_GPIO 4
#define MAX_TIMINGS 85
#define TIMEOUT_US 1000000 // 1 second timeout

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[MAX_TIMINGS];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed to 30us

    gpioSetMode(gpio, PI_INPUT);

    int timeout_counter = 0;
    while (gpioRead(gpio) == 1) {
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for start signal.\n");
            return -1; // Timeout
        }
        gpioDelay(1); // Check every microsecond
    }

    timeout_counter = 0;
    while (gpioRead(gpio) == 0) {
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for end of start signal.\n");
            return -1; // Timeout
        }
        gpioDelay(1);
    }

    timeout_counter = 0;
    while (gpioRead(gpio) == 1) {
        if (timeout_counter++ > TIMEOUT_US) {
            fprintf(stderr, "DHT22: Timeout waiting for end of data signal.\n");
            return -1; // Timeout
        }
        gpioDelay(1);
    }

    for (i = 0; i < MAX_TIMINGS; i++) {
        timeout_counter = 0;
        while (gpioRead(gpio) == 0) {
            if (timeout_counter++ > TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for rising edge.\n");
                return -1; // Timeout
            }
            gpioDelay(1);
        }

        long t = gpioTick();

        timeout_counter = 0;
        while (gpioRead(gpio) == 1) {
            if (timeout_counter++ > TIMEOUT_US) {
                fprintf(stderr, "DHT22: Timeout waiting for falling edge.\n");
                return -1; // Timeout
            }
            gpioDelay(1);
        }

        pulse_counts[i] = gpioTick() - t;
    }

    for (i = 2; i < 42; i++) {
        int index = i / 8;
        int bit = i % 8;

        if (pulse_counts[2 * i] > 40) {
            data[index] |= (1 << (7 - bit));
        }
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22: Checksum failure.\n");
        return -1; // Checksum failure
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    int result;

    result = read_dht22(DHT22_GPIO, &temperature, &humidity);

    if (result == 0) {
        printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
    } else {
        fprintf(stderr, "Failed to read DHT22 sensor.\n");
    }

    gpioTerminate();
    return 0;
}

