// Define GPIO pins
#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio23_line = NULL;
struct gpiod_line *gpio24_line = NULL;
struct gpiod_line *gpio25_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    struct gpiod_line_request_config config;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_pin);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", gpio_pin);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_23) {
        line = gpio23_line;
    } else if (gpio_pin == GPIO_24) {
        line = gpio24_line;
    } else if (gpio_pin == GPIO_25) {
        line = gpio25_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value to %d\n", gpio_pin, value);
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_23) {
        line = gpio23_line;
    } else if (gpio_pin == GPIO_24) {
        line = gpio24_line;
    } else if (gpio_pin == GPIO_25) {
        line = gpio25_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get GPIO line %d value\n", gpio_pin);
        return -1;
    }

    return value;
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(void) {
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio23_line) {
        gpiod_line_release(gpio23_line);
    }
    if (gpio24_line) {
        gpiod_line_release(gpio24_line);
    }
    if (gpio25_line) {
        gpiod_line_release(gpio25_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    time_t current_time;
    int gpio_values[4];
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", CHIP_NAME);
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_17) < 0 ||
        initialize_gpio(GPIO_23) < 0 ||
        initialize_gpio(GPIO_24) < 0 ||
        initialize_gpio(GPIO_25) < 0) {
        cleanup_gpio();
        return 1;
    }

    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio23_line = gpiod_chip_get_line(chip, GPIO_23);
    gpio24_line = gpiod_chip_get_line(chip, GPIO_24);
    gpio25_line = gpiod_chip_get_line(chip, GPIO_25);

    // Main loop
    while (1) {
        // Get current time
        current_time = time(NULL);

        // Set GPIO values
        if (set_gpio_value(GPIO_17, 1) < 0) goto cleanup;
        if (set_gpio_value(GPIO_23, 0) < 0) goto cleanup;
        if (set_gpio_value(GPIO_24, 1) < 0) goto cleanup;
        if (set_gpio_value(GPIO_25, 0) < 0) goto cleanup;

        // Get GPIO values
        gpio_values[0] = get_gpio_value(GPIO_17);
        gpio_values[1] = get_gpio_value(GPIO_23);
        gpio_values[2] = get_gpio_value(GPIO_24);
        gpio_values[3] = get_gpio_value(GPIO_25);

        // Print GPIO values and current time
        printf("GPIO 17: %d, GPIO 23: %d, GPIO 24: %d, GPIO 25: %d, Time: %ld\n",
               gpio_values[0], gpio_values[1], gpio_values[2], gpio_values[3], current_time);

        // Wait for 10 seconds
        sleep(10);
    }

cleanup:
    cleanup_gpio();
    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MQTT_HOST "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/sensor/mcp3008"
#define MCP3008_CHANNEL 0 // ADC channel to read

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;

// Function prototypes
int read_mcp3008(int channel);
int publish_mqtt(const char *topic, const char *payload);
void signal_handler(int signum);

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        if (spi_handle >= 0) {
            spiClose(spi_handle);
        }
        if (mosq) {
            mosquitto_destroy(mosq);
        }
        mosquitto_lib_cleanup();
        gpioTerminate();
        exit(0);
    }
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to publish data to MQTT broker
int publish_mqtt(const char *topic, const char *payload) {
    int ret;

    ret = mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT publish failed: %s\n", mosquitto_strerror(ret));
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Connect to MQTT broker
    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: MQTT connection failed: %s\n", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to string
        char payload[20];
        snprintf(payload, sizeof(payload), "%d", adc_value);

        // Publish to MQTT
        if (publish_mqtt(MQTT_TOPIC, payload) != 0) {
            fprintf(stderr, "Error: Failed to publish MQTT message\n");
        }

        // Wait for a short period
        sleep(1);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper cleanup.
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <string.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
        void   *start;
        size_t  length;
};

static int fd = -1;
static struct buffer *buffers = NULL;
static unsigned int n_buffers = 0;

static int xioctl(int fh, int request, void *arg)
{
        int r;

        do {
                r = ioctl(fh, request, arg);
        } while (-1 == r && EINTR == errno);

        return r;
}

int main()
{
        const char *dev_name = "/dev/video0";
        int i;
        unsigned int frames = 1;
        struct v4l2_capability cap;
        struct v4l2_format fmt;
        struct v4l2_requestbuffers req;
        struct v4l2_buffer buf;
        enum v4l2_buf_type type;

        fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
        if (fd < 0) {
                perror("Cannot open device");
                exit(1);
        }

        if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
                perror("VIDIOC_QUERYCAP");
                close(fd);
                exit(1);
        }

        if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
                fprintf(stderr, "%s is no video capture device\n",
                        dev_name);
                close(fd);
                exit(1);
        }

        if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
                fprintf(stderr, "%s does not support streaming i/o\n",
                        dev_name);
                close(fd);
                exit(1);
        }

        CLEAR(fmt);

        fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        fmt.fmt.pix.width = 640;
        fmt.fmt.pix.height = 480;
        fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
        fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

        if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
                perror("VIDIOC_S_FMT");
                close(fd);
                exit(1);
        }

        CLEAR(req);

        req.count = 4; // Request 4 buffers
        req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        req.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
                if (EINVAL == errno) {
                        fprintf(stderr, "%s does not support memory mapping\n",
                                dev_name);
                        close(fd);
                        exit(1);
                } else {
                        perror("VIDIOC_REQBUFS");
                        close(fd);
                        exit(1);
                }
        }

        if (req.count < 2) {
                fprintf(stderr, "Insufficient buffer memory on %s\n",
                        dev_name);
                close(fd);
                exit(1);
        }

        buffers = calloc(req.count, sizeof(*buffers));

        if (!buffers) {
                fprintf(stderr, "Out of memory\n");
                close(fd);
                exit(1);
        }

        for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
                CLEAR(buf);

                buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory = V4L2_MEMORY_MMAP;
                buf.index = n_buffers;

                if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
                        perror("VIDIOC_QUERYBUF");
                        close(fd);
                        exit(1);
                }

                buffers[n_buffers].length = buf.length;
                buffers[n_buffers].start =
                        mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                        MAP_SHARED, fd, buf.m.offset);

                if (MAP_FAILED == buffers[n_buffers].start) {
                        perror("mmap");
                        close(fd);
                        exit(1);
                }
        }

        for (i = 0; i < n_buffers; ++i) {
                CLEAR(buf);
                buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
                buf.memory = V4L2_MEMORY_MMAP;
                buf.index = i;

                if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
                        perror("VIDIOC_QBUF");
                        close(fd);
                        exit(1);
                }
        }

        type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

        if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
                perror("VIDIOC_STREAMON");
                close(fd);
                exit(1);
        }

        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r && EINTR != errno) {
                perror("select");
                close(fd);
                exit(1);
        }

        if (0 == r) {
                fprintf(stderr, "select timeout\n");
                close(fd);
                exit(1);
        }

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = 0;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
                perror("VIDIOC_DQBUF");
                close(fd);
                exit(1);
        }

        FILE *fp = fopen("capture.yuyv", "wb");
        if (!fp) {
                perror("fopen");
                close(fd);
                exit(1);
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
                perror("VIDIOC_STREAMOFF");
                close(fd);
                exit(1);
        }

        for (i = 0; i < n_buffers; ++i)
                if (-1 == munmap(buffers[i].start, buffers[i].length))
                        perror("munmap");

        free(buffers);
        close(fd);

        printf("Image captured and saved as capture.yuyv\n");
        return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for PWM outputs
#define GPIO_4 4
#define GPIO_5 5
#define GPIO_6 6
#define GPIO_7 7
#define GPIO_8 8
#define GPIO_9 9

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to set PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
    }
}

// Function to report the current PWM state
void report_pwm_state() {
    int duty_cycle_4 = gpioGetPWMdutycycle(GPIO_4);
    int duty_cycle_5 = gpioGetPWMdutycycle(GPIO_5);
    int duty_cycle_6 = gpioGetPWMdutycycle(GPIO_6);
    int duty_cycle_7 = gpioGetPWMdutycycle(GPIO_7);
    int duty_cycle_8 = gpioGetPWMdutycycle(GPIO_8);
    int duty_cycle_9 = gpioGetPWMdutycycle(GPIO_9);

    printf("GPIO 4: %d, GPIO 5: %d, GPIO 6: %d, GPIO 7: %d, GPIO 8: %d, GPIO 9: %d\n",
           duty_cycle_4, duty_cycle_5, duty_cycle_6, duty_cycle_7, duty_cycle_8, duty_cycle_9);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_4, PI_OUTPUT);
    gpioSetMode(GPIO_5, PI_OUTPUT);
    gpioSetMode(GPIO_6, PI_OUTPUT);
    gpioSetMode(GPIO_7, PI_OUTPUT);
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_4, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_5, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_6, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_7, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_8, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_9, PWM_FREQUENCY);

    // Set PWM range for all GPIO pins
    gpioSetPWMrange(GPIO_4, PWM_RANGE);
    gpioSetPWMrange(GPIO_5, PWM_RANGE);
    gpioSetPWMrange(GPIO_6, PWM_RANGE);
    gpioSetPWMrange(GPIO_7, PWM_RANGE);
    gpioSetPWMrange(GPIO_8, PWM_RANGE);
    gpioSetPWMrange(GPIO_9, PWM_RANGE);

    // Main loop
    while (!terminate) {
        // Set PWM duty cycles (example values)
        set_pwm_duty_cycle(GPIO_4, 128);
        set_pwm_duty_cycle(GPIO_5, 64);
        set_pwm_duty_cycle(GPIO_6, 192);
        set_pwm_duty_cycle(GPIO_7, 32);
        set_pwm_duty_cycle(GPIO_8, 224);
        set_pwm_duty_cycle(GPIO_9, 160);

        // Report PWM state
        report_pwm_state();

        // Wait for 1 second
        sleep(1);
    }

    // Stop PWM output on all GPIO pins
    gpioPWM(GPIO_4, 0);
    gpioPWM(GPIO_5, 0);
    gpioPWM(GPIO_6, 0);
    gpioPWM(GPIO_7, 0);
    gpioPWM(GPIO_8, 0);
    gpioPWM(GPIO_9, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18

// Define the number of cycles
#define NUM_CYCLES 3

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line17;
struct gpiod_line *line18;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line17, struct gpiod_line **line18);
int set_gpio_value(struct gpiod_line *line, int value);
int read_gpio_value(struct gpiod_line *line);
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line18);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(chip, line17, line18);
    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line17, struct gpiod_line **line18) {
    // Open the GPIO chip
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 17
    *line17 = gpiod_chip_get_line(*chip, GPIO_17);
    if (!*line17) {
        perror("Error getting GPIO line 17");
        gpiod_chip_close(*chip);
        return -1;
    }

    // Get the GPIO line for GPIO 18
    *line18 = gpiod_chip_get_line(*chip, GPIO_18);
    if (!*line18) {
        perror("Error getting GPIO line 18");
        gpiod_line_release(*line17);
        gpiod_chip_close(*chip);
        return -1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(*line17, "cycle_control_17", 0) < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(*line18);
        gpiod_line_release(*line17);
        gpiod_chip_close(*chip);
        return -1;
    }
    if (gpiod_line_request_output(*line18, "cycle_control_18", 0) < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(*line17);
        gpiod_line_release(*line18);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Reads the value of a GPIO line
int read_gpio_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error reading GPIO value");
        return -1;
    }
    return value;
}

// Releases the GPIO lines and closes the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line18) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line17, &line18) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop for 3 cycles
    for (int cycle = 0; cycle < NUM_CYCLES; cycle++) {
        printf("Cycle %d\n", cycle + 1);

        // Cycle 1: GPIO 17 = 1, GPIO 18 = 0
        if (set_gpio_value(line17, 1) < 0) {
            cleanup_gpio(chip, line17, line18);
            return 1;
        }
        if (set_gpio_value(line18, 0) < 0) {
            cleanup_gpio(chip, line17, line18);
            return 1;
        }
        printf("GPIO 17: 1, GPIO 18: 0\n");
        sleep(1);

        // Cycle 2: GPIO 17 = 0, GPIO 18 = 1
        if (set_gpio_value(line17, 0) < 0) {
            cleanup_gpio(chip, line17, line18);
            return 1;
        }
        if (set_gpio_value(line18, 1) < 0) {
            cleanup_gpio(chip, line17, line18);
            return 1;
