// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x20

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2C bus
int i2c_init(const char *bus) {
    int file_descriptor = open(bus, O_RDWR);
    if (file_descriptor < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return file_descriptor;
}

// Function to write data to the PCF8574
int pcf8574_write(int file_descriptor, uint8_t data) {
    if (write(file_descriptor, &data, 1) != 1) {
        perror("Error writing to PCF8574");
        return -1;
    }
    return 0;
}

// Function to display a pattern on the PCF8574
int display_pattern(int file_descriptor) {
    uint8_t pattern = 0x01; // Start with the first LED on
    for (int i = 0; i < 8 && program_running; ++i) {
        if (pcf8574_write(file_descriptor, pattern) != 0) {
            return -1;
        }
        usleep(500000); // 0.5 seconds
        pattern <<= 1; // Shift the pattern to the left
    }
    return 0;
}

// Function to close the I2C bus
void i2c_close(int file_descriptor) {
    close(file_descriptor);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    int file_descriptor = i2c_init(I2C_BUS);
    if (file_descriptor < 0) {
        return EXIT_FAILURE;
    }

    // Main loop to display the pattern
    while (program_running) {
        if (display_pattern(file_descriptor) != 0) {
            program_running = 0; // Stop the loop on error
            break;
        }
    }

    // Close the I2C bus before exiting
    i2c_close(file_descriptor);

    return EXIT_SUCCESS;
}

