        fprintf(stderr, "Error requesting GPIO 17 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(gpio18_line, "gpio18", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 18 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    ret = gpiod_line_request_output(gpio24_line, "gpio24", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO 24 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set initial state (LOW)
    if (set_gpio_state(GPIO_17, 0) < 0) return 1;
    if (set_gpio_state(GPIO_18, 0) < 0) return 1;
    if (set_gpio_state(GPIO_24, 0) < 0) return 1;

    // Print initial state
    printf("GPIO 17: %d\n", get_gpio_state(GPIO_17));
    printf("GPIO 18: %d\n", get_gpio_state(GPIO_18));
    printf("GPIO 24: %d\n", get_gpio_state(GPIO_24));

    // Set state to HIGH
    if (set_gpio_state(GPIO_17, 1) < 0) return 1;
    if (set_gpio_state(GPIO_18, 1) < 0) return 1;
    if (set_gpio_state(GPIO_24, 1) < 0) return 1;

    // Print updated state
    printf("GPIO 17: %d\n", get_gpio_state(GPIO_17));
    printf("GPIO 18: %d\n", get_gpio_state(GPIO_18));
    printf("GPIO 24: %d\n", get_gpio_state(GPIO_24));

    // Cleanup and exit
    cleanup();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Define timeout in microseconds
#define TIMEOUT_US 500000 // 0.5 seconds

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *trigger_line = NULL;
struct gpiod_line *echo_line = NULL;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to trigger the HC-SR04 sensor
int trigger_sensor() {
    int ret;
    struct timespec req, rem;

    // Set trigger pin high for 10 microseconds
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger pin high: %s\n", strerror(-ret));
        return -1;
    }

    req.tv_sec = 0;
    req.tv_nsec = 10000; // 10 microseconds
    nanosleep(&req, &rem);

    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger pin low: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for echo pin to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (pulse_width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    // Wait for echo pin to go low
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (gpiod_line_get_value(echo_line) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);
        if (pulse_width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    clock_gettime(CLOCK_MONOTONIC, &end);
    pulse_width = (end.tv_sec - start.tv_sec) * 1000000000LL + (end.tv_nsec - start.tv_nsec);

    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(long pulse_width) {
    return (pulse_width / 1000000.0) * 34300.0 / 2.0;
}

// Function to report the distance
void report_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    int ret;
    long pulse_width;
    float distance;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line for output: %s\n", strerror(-ret));
        gpiod_line_release(echo_line);
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request echo line for input
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line for input: %s\n", strerror(-ret));
        gpiod_line_release(trigger_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor() < 0) {
            fprintf(stderr, "Error triggering sensor\n");
            break;
        }

        // Measure the pulse width
        pulse_width = measure_pulse_width();
        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width or timeout\n");
            continue; // Retry
        }

        // Calculate the distance
        distance = calculate_distance(pulse_width);

        // Report the distance
        report_distance(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO lines and close chip
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for PWM outputs
#define GPIO_8 8
#define GPIO_9 9
#define GPIO_11 11
#define GPIO_18 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GPIO_8, PI_OUTPUT);
    gpioSetMode(GPIO_9, PI_OUTPUT);
    gpioSetMode(GPIO_11, PI_OUTPUT);
    gpioSetMode(GPIO_18, PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(GPIO_8, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_9, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_11, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_18, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_8, 255);
    gpioSetPWMrange(GPIO_9, 255);
    gpioSetPWMrange(GPIO_11, 255);
    gpioSetPWMrange(GPIO_18, 255);

    // Install signal handler for SIGINT
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate)
    {
        // Generate random PWM duty cycle values (0-255)
        int duty_cycle_8 = rand() % 256;
        int duty_cycle_9 = rand() % 256;
        int duty_cycle_11 = rand() % 256;
        int duty_cycle_18 = rand() % 256;

        // Set PWM duty cycles for each GPIO pin
        gpioPWM(GPIO_8, duty_cycle_8);
        gpioPWM(GPIO_9, duty_cycle_9);
        gpioPWM(GPIO_11, duty_cycle_11);
        gpioPWM(GPIO_18, duty_cycle_18);

        // Print the current PWM states to standard output
        printf("GPIO 8: %d, GPIO 9: %d, GPIO 11: %d, GPIO 18: %d\n", duty_cycle_8, duty_cycle_9, duty_cycle_11, duty_cycle_18);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and exit
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define CLEAR(x) memset(&(x), 0, sizeof(x))

struct buffer {
    void   *start;
    size_t  length;
};

static int fd = -1;
static int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int xioctl(int fh, int request, void *arg)
{
    int r;

    do {
        r = ioctl(fh, request, arg);
    } while (-1 == r && EINTR == errno);

    return r;
}

int main()
{
    const char *dev_name = "/dev/video0";
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct buffer *buffers;
    unsigned int n_buffers;
    struct v4l2_buffer buf;
    char filename[64];
    int i;

    signal(SIGINT, signal_handler);

    fd = open(dev_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Cannot open device");
        return 1;
    }

    if (-1 == xioctl(fd, VIDIOC_QUERYCAP, &cap)) {
        perror("VIDIOC_QUERYCAP");
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is no video capture device\n", dev_name);
        close(fd);
        return 1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming i/o\n", dev_name);
        close(fd);
        return 1;
    }

    CLEAR(fmt);
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (-1 == xioctl(fd, VIDIOC_S_FMT, &fmt)) {
        perror("VIDIOC_S_FMT");
        close(fd);
        return 1;
    }

    CLEAR(req);
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (-1 == xioctl(fd, VIDIOC_REQBUFS, &req)) {
        if (EINVAL == errno) {
            fprintf(stderr, "%s does not support memory mapping\n", dev_name);
            close(fd);
            return 1;
        } else {
            perror("VIDIOC_REQBUFS");
            close(fd);
            return 1;
        }
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return 1;
    }

    for (n_buffers = 0; n_buffers < req.count; ++n_buffers) {
        CLEAR(buf);

        buf.type        = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory      = V4L2_MEMORY_MMAP;
        buf.index       = n_buffers;

        if (-1 == xioctl(fd, VIDIOC_QUERYBUF, &buf)) {
            perror("VIDIOC_QUERYBUF");
            close(fd);
            free(buffers);
            return 1;
        }

        buffers[n_buffers].length = buf.length;
        buffers[n_buffers].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (MAP_FAILED == buffers[n_buffers].start) {
            perror("mmap");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    for (i = 0; i < n_buffers; ++i) {
        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            close(fd);
            free(buffers);
            return 1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (-1 == xioctl(fd, VIDIOC_STREAMON, &type)) {
        perror("VIDIOC_STREAMON");
        close(fd);
        free(buffers);
        return 1;
    }

    while (running) {
        fd_set fds;
        struct timeval tv;
        int r;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 2; // Timeout of 2 seconds
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (-1 == r) {
            perror("select");
            break;
        }

        if (0 == r) {
            fprintf(stderr, "select timeout\n");
            break;
        }

        CLEAR(buf);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (-1 == xioctl(fd, VIDIOC_DQBUF, &buf)) {
            perror("VIDIOC_DQBUF");
            break;
        }

        snprintf(filename, sizeof(filename), "image_%04d.yuv", time(NULL));
        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            perror("fopen");
            break;
        }

        fwrite(buffers[buf.index].start, buf.bytesused, 1, fp);
        fclose(fp);

        if (-1 == xioctl(fd, VIDIOC_QBUF, &buf)) {
            perror("VIDIOC_QBUF");
            break;
        }

        usleep(100000); // 0.1 seconds
    }

    if (-1 == xioctl(fd, VIDIOC_STREAMOFF, &type)) {
        perror("VIDIOC_STREAMOFF");
    }

    for (i = 0; i < n_buffers; ++i) {
        if (-1 == munmap(buffers[i].start, buffers[i].length)) {
            perror("munmap");
        }
    }

    close(fd);
    free(buffers);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pwm_value;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", PWM_GPIO);

    while (program_running) {
        // Generate PWM values between 0 and 1000
        pwm_value = rand() % (PWM_RANGE + 1);

        // Set the PWM duty cycle
        gpioPWM(PWM_GPIO, pwm_value);

        // Print the current PWM value
        printf("PWM Value: %d\n", pwm_value);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Clean up and terminate pigpio
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();

    printf("PWM control stopped.\n");

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8574_ADDR 0x20

int main() {
    int file;
    int i;
    unsigned char data[8] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80};

    // Open I2C bus
    if ((file = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Specify slave address
    if (ioctl(file, I2C_SLAVE, PCF8574_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file);
        return 1;
    }

    // Write data to PCF8574
    for (i = 0; i < 8; i++) {
        if (write(file, &data[i], 1) != 1) {
            perror("Failed to write to I2C device");
            close(file);
            return 1;
        }
        printf("Wrote 0x%02X to PCF8574\n", data[i]);
        usleep(500000); // 500ms delay
    }

    // Close I2C bus
    close(file);
    printf("Program finished.\n");
    return 0;
}

