        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to report the current PWM state
void report_pwm_state(int duty_cycle1, int duty_cycle2, int duty_cycle3) {
    printf("PWM State: GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
           PWM_PIN_1, duty_cycle1, PWM_PIN_2, duty_cycle2, PWM_PIN_3, duty_cycle3);
