    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate PWM duty cycles (example values)
        int duty_cycle1 = 128;
        int duty_cycle2 = 64;
        int duty_cycle3 = 192;

        // Set PWM duty cycles
        if (set_pwm_duty_cycle(PWM_PIN_1, duty_cycle1) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", PWM_PIN_1);
            break; // Exit loop on error
        }
        if (set_pwm_duty_cycle(PWM_PIN_2, duty_cycle2) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", PWM_PIN_2);
            break; // Exit loop on error
        }
        if (set_pwm_duty_cycle(PWM_PIN_3, duty_cycle3) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", PWM_PIN_3);
            break; // Exit loop on error
        }

        // Report PWM state
        report_pwm_state(duty_cycle1, duty_cycle2, duty_cycle3);

        // Wait for 0.1 seconds
        gpioDelay(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int echo_timeout = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int start_tick, int end_tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1;
        echo_timeout = 0; // Reset timeout
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance in centimeters
float calculate_distance(int start_tick, int end_tick) {
    if (start_tick == 0 || end_tick == 0) {
        return -1.0; // Indicate error
    }

    int diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_counter = 0;
        while (!echo_received && !echo_timeout) {
            gpioDelay(1000); // Check every 1ms
            timeout_counter++;
            if (timeout_counter * 1000 > TIMEOUT_US) {
                echo_timeout = 1;
                break;
            }
        }

        // Calculate distance
        float distance = calculate_distance(echo_start_tick, echo_end_tick);

        // Print distance or error message
        if (distance > 0) {
            printf("Distance: %.2f cm\n", distance);
        } else if (echo_timeout) {
            printf("Error: No echo received within timeout\n");
        } else {
            printf("Error: Invalid start or end tick\n");
        }

        // Reset flags for next measurement
        echo_received = 0;
        echo_timeout = 0;
        echo_start_tick = 0;
        echo_end_tick = 0;

        gpioDelay(100000); // Delay between measurements (100ms)
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 23

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 5;
    sleep_time.tv_nsec = 0;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    fprintf(stderr, "GPIO %d requested for output.\n", GPIO_PIN);

    /* Main loop */
    while (!terminate) {
        /* Set GPIO high */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("Error setting GPIO high");
            break;
        }
        printf("GPIO %d set to HIGH\n", GPIO_PIN);

        /* Sleep for 5 seconds */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }

        /* Set GPIO low */
        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("Error setting GPIO low");
            break;
        }
        printf("GPIO %d set to LOW\n", GPIO_PIN);

        /* Sleep for 5 seconds */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    /* Release GPIO line */
    gpiod_line_release(line);
    fprintf(stderr, "GPIO %d released.\n", GPIO_PIN);

    /* Close GPIO chip */
    gpiod_chip_close(chip);
    fprintf(stderr, "GPIO chip closed.\n");

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a single byte from an I2C register
int read_i2c_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read register data");
        return -1;
    }

    return data;
}

// Function to write a single byte to an I2C register
int write_i2c_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = read_i2c_reg(fd, ACCEL_XOUT_H);
    x_l = read_i2c_reg(fd, ACCEL_XOUT_L);
    y_h = read_i2c_reg(fd, ACCEL_YOUT_H);
    y_l = read_i2c_reg(fd, ACCEL_YOUT_L);
    z_h = read_i2c_reg(fd, ACCEL_ZOUT_H);
    z_l = read_i2c_reg(fd, ACCEL_ZOUT_L);

    if (x_h == -1 || x_l == -1 || y_h == -1 || y_l == -1 || z_h == -1 || z_l == -1) {
        return -1; // Indicate error
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0; // Indicate success
}

int main() {
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    int16_t accel_x, accel_y, accel_z;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU6050 (clear sleep bit)
    if (write_i2c_reg(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read accelerometer data
        if (read_accelerometer_data(i2c_fd, &accel_x, &accel_y, &accel_z) == 0) {
            // Print accelerometer data
            printf("Accel X: %d, Accel Y: %d, Accel Z: %d\n", accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Delay for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Close I2C device (this will never be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17

// Define the number of cycles
#define NUM_CYCLES 3

// Define the duration of each cycle in seconds
#define CYCLE_DURATION 5

// Global variable to track the cycle count
volatile int cycle_count = 0;

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line2;
    struct gpiod_line *line3;
    struct gpiod_line *line17;
} gpio_state_t;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, terminating program...\n");
    terminate = 1;
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_state_t *state) {
    state->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    state->line2 = gpiod_chip_get_line(state->chip, GPIO_2);
    if (!state->line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_2, strerror(errno));
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->line3 = gpiod_chip_get_line(state->chip, GPIO_3);
    if (!state->line3) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(state->line2);
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->line17 = gpiod_chip_get_line(state->chip, GPIO_17);
    if (!state->line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(state->line2);
        gpiod_line_release(state->line3);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line2, "cycle_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_2, strerror(errno));
        gpiod_line_release(state->line2);
        gpiod_line_release(state->line3);
        gpiod_line_release(state->line17);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line3, "cycle_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_3, strerror(errno));
        gpiod_line_release(state->line2);
        gpiod_line_release(state->line3);
        gpiod_line_release(state->line17);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line17, "cycle_control", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(state->line2);
        gpiod_line_release(state->line3);
        gpiod_line_release(state->line17);
        gpiod_chip_close(state->chip);
        return -1;
    }

    return 0;
}

// Function to set the state of the GPIO lines
void set_gpio_state(gpio_state_t *state, int state2, int state3, int state17) {
    if (gpiod_line_set_value(state->line2, state2) < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_2, strerror(errno));
    }
    if (gpiod_line_set_value(state->line3, state3) < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_3, strerror(errno));
    }
    if (gpiod_line_set_value(state->line17, state17) < 0) {
        fprintf(stderr, "Error setting GPIO line %d value: %s\n", GPIO_17, strerror(errno));
    }
}

// Function to release GPIO lines
void release_gpio(gpio_state_t *state) {
    gpiod_line_release(state->line2);
    gpiod_line_release(state->line3);
    gpiod_line_release(state->line17);
    gpiod_chip_close(state->chip);
}

int main() {
    gpio_state_t gpio_state;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio(&gpio_state) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to control the GPIO lines
    while (cycle_count < NUM_CYCLES && !terminate) {
        // Cycle 1: GPIO 2 = 1, GPIO 3 = 0, GPIO 17 = 1
        set_gpio_state(&gpio_state, 1, 0, 1);
        printf("Cycle %d: GPIO 2 = 1, GPIO 3 = 0, GPIO 17 = 1\n", cycle_count + 1);
        sleep(CYCLE_DURATION);

        // Cycle 2: GPIO 2 = 0, GPIO 3 = 1, GPIO 17 = 0
        set_gpio_state(&gpio_state, 0, 1, 0);
        printf("Cycle %d: GPIO 2 = 0, GPIO 3 = 1, GPIO 17 = 0\n", cycle_count + 1);
        sleep(CYCLE_DURATION);

        // Cycle 3: GPIO 2 = 1, GPIO 3 = 1, GPIO 17 = 1
        set_gpio_state(&gpio_state, 1, 1, 1);
        printf("Cycle %d: GPIO 2 = 1, GPIO 3 = 1, GPIO 17 = 1\n", cycle_count + 1);
        sleep(CYCLE_DURATION);

        cycle_count++;
    }

    // Release GPIO lines before exiting
    release_gpio(&gpio_state);

    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio22_line = NULL;
struct gpiod_line *gpio27_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int set_gpio_state(int gpio_pin, int state);
int get_gpio_state(int gpio_pin);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_22) {
        line = gpio22_line;
    } else if (gpio_pin == GPIO_27) {
        line = gpio27_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", gpio_pin, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio_pin) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) {
        line = gpio17_line;
    } else if (gpio_pin == GPIO_22) {
        line = gpio22_line;
    } else if (gpio_pin == GPIO_27) {
        line = gpio27_line;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %s\n", gpio_pin, strerror(-value));
        return -1;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio22_line = gpiod_chip_get_line(chip, GPIO_22);
    gpio27_line = gpiod_chip_get_line(chip, GPIO_27);

    if (!gpio17_line || !gpio22_line || !gpio27_line) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    // Request GPIO lines for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret;
    ret = gpiod_line_request(gpio17_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_17, strerror(-ret));
        cleanup(0);
        return 1;
    }

    ret = gpiod_line_request(gpio22_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_22, strerror(-ret));
        cleanup(0);
        return 1;
    }

    ret = gpiod_line_request(gpio27_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output: %s\n", GPIO_27, strerror(-ret));
        cleanup(0);
        return 1;
    }

    // Set initial state (LOW)
    if (set_gpio_state(GPIO_17, 0) != 0 ||
        set_gpio_state(GPIO_22, 0) != 0 ||
        set_gpio_state(GPIO_27, 0) != 0) {
        cleanup(0);
        return 1;
    }

    printf("GPIO %d, %d, %d set to LOW\n", GPIO_17, GPIO_22, GPIO_27);

    // Set state to HIGH
    if (set_gpio_state(GPIO_17, 1) != 0 ||
        set_gpio_state(GPIO_22, 1) != 0 ||
        set_gpio_state(GPIO_27, 1) != 0) {
        cleanup(0);
        return 1;
    }

    printf("GPIO %d, %d, %d set to HIGH\n", GPIO_17, GPIO_22, GPIO_27);

    // Set state to LOW again
    if (set_gpio_state(GPIO_17, 0) != 0 ||
        set_gpio_state(GPIO_22, 0) != 0 ||
        set_gpio_state(GPIO_27, 0) != 0) {
        cleanup(0);
        return 1;
    }

    printf("GPIO %d, %d, %d set to LOW\n", GPIO_17, GPIO_22, GPIO_27);

    // Cleanup and exit
    cleanup(0);

    return 0;
}

