#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>

// Define GPIO pins
#define GPIO_10 10
#define GPIO_11 11
#define GPIO_12 12
#define GPIO_17 17

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *line_10 = NULL;
struct gpiod_line *line_11 = NULL;
struct gpiod_line *line_12 = NULL;
struct gpiod_line *line_17 = NULL;

// Function prototypes
int set_gpio_state(int gpio, int state);
int get_gpio_state(int gpio);
void cleanup();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        cleanup();
        exit(0);
    }
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    struct gpiod_line *line;

    switch (gpio) {
        case GPIO_10:
            line = line_10;
            break;
        case GPIO_11:
            line = line_11;
            break;
        case GPIO_12:
            line = line_12;
            break;
        case GPIO_17:
            line = line_17;
            break;
        default:
            fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
            return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", gpio, state, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio) {
    struct gpiod_line *line;

    switch (gpio) {
        case GPIO_10:
            line = line_10;
            break;
        case GPIO_11:
            line = line_11;
            break;
        case GPIO_12:
            line = line_12;
            break;
        case GPIO_17:
            line = line_17;
            break;
        default:
            fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
            return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %s\n", gpio, strerror(errno));
        return -1;
    }

    return value;
}

// Function to cleanup GPIO resources
void cleanup() {
    if (line_10) {
        gpiod_line_release(line_10);
    }
    if (line_11) {
        gpiod_line_release(line_11);
    }
    if (line_12) {
        gpiod_line_release(line_12);
    }
    if (line_17) {
        gpiod_line_release(line_17);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    line_10 = gpiod_chip_get_line(chip, GPIO_10);
    line_11 = gpiod_chip_get_line(chip, GPIO_11);
    line_12 = gpiod_chip_get_line(chip, GPIO_12);
    line_17 = gpiod_chip_get_line(chip, GPIO_17);

    if (!line_10 || !line_11 || !line_12 || !line_17) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line_10, "gpio10", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 10 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(line_11, "gpio11", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 11 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(line_12, "gpio12", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 12 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (gpiod_line_request_output(line_17, "gpio17", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO 17 for output: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set initial states
    if (set_gpio_state(GPIO_10, 1) < 0) return 1;
    if (set_gpio_state(GPIO_11, 0) < 0) return 1;
    if (set_gpio_state(GPIO_12, 1) < 0) return 1;
    if (set_gpio_state(GPIO_17, 0) < 0) return 1;

    // Print initial states
    printf("GPIO 10: %d\n", get_gpio_state(GPIO_10));
    printf("GPIO 11: %d\n", get_gpio_state(GPIO_11));
    printf("GPIO 12: %d\n", get_gpio_state(GPIO_12));
    printf("GPIO 17: %d\n", get_gpio_state(GPIO_17));

