// Define GPIO pins
#define GPIO_18 18
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio18_line = NULL;
struct gpiod_line *gpio27_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line, "example", 0); // Initial value 0
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return -1;
    }

    if (gpio_pin == GPIO_18) {
        gpio18_line = line;
    } else if (gpio_pin == GPIO_27) {
        gpio27_line = line;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;
    int ret;

    if (gpio_pin == GPIO_18) {
        line = gpio18_line;
    } else if (gpio_pin == GPIO_27) {
        line = gpio27_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == GPIO_18) {
        line = gpio18_line;
    } else if (gpio_pin == GPIO_27) {
        line = gpio27_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO value");
        return -1;
    }

    return value;
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(void) {
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (gpio27_line) {
        gpiod_line_release(gpio27_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int gpio18_value, gpio27_value;
    struct timespec sleep_time;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_18) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_18);
        return 1;
    }
    if (initialize_gpio(GPIO_27) < 0) {
        fprintf(stderr, "Failed to initialize GPIO %d\n", GPIO_27);
        cleanup_gpio();
        return 1;
    }

    // Main loop
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 milliseconds

    while (1) {
        // Set GPIO 18 to 1
        if (set_gpio_value(GPIO_18, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to 1\n", GPIO_18);
            cleanup_gpio();
            return 1;
        }
        gpio18_value = get_gpio_value(GPIO_18);
        if (gpio18_value < 0) {
            fprintf(stderr, "Failed to get GPIO %d value\n", GPIO_18);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d set to %d\n", GPIO_18, gpio18_value);

        // Set GPIO 27 to 0
        if (set_gpio_value(GPIO_27, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d to 0\n", GPIO_27);
            cleanup_gpio();
            return 1;
        }
        gpio27_value = get_gpio_value(GPIO_27);
        if (gpio27_value < 0) {
            fprintf(stderr, "Failed to get GPIO %d value\n", GPIO_27);
            cleanup_gpio();
            return 1;
        }
        printf("GPIO %d set to %d\n", GPIO_27, gpio27_value);

        // Sleep for 10 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

