#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB color channels
#define RED_PIN   18
#define GREEN_PIN 23
#define BLUE_PIN  24

// Define the number of cycles
#define NUM_CYCLES 3

// Define the delay between cycles (in microseconds)
#define DELAY_US 5000

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set the RGB color values on the GPIO pins
void set_color(int red, int green, int blue) {
    gpioWrite(RED_PIN, red);
    gpioWrite(GREEN_PIN, green);
    gpioWrite(BLUE_PIN, blue);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Main loop to cycle through RGB colors
    for (int cycle = 0; cycle < NUM_CYCLES && !terminate; cycle++) {
        // Red
        set_color(1, 0, 0);
        gpioDelay(DELAY_US);

        // Green
        set_color(0, 1, 0);
        gpioDelay(DELAY_US);

        // Blue
        set_color(0, 0, 1);
        gpioDelay(DELAY_US);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

#include <stdio.h>
