#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 27

struct gpiod_chip *chip;
struct gpiod_line *line;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    exit(0);
}

int main() {
    int ret;
    int state = 1; // Start with HIGH
    time_t last_report_time = 0;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request_output(line, "example", 0); // Initial value LOW
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(line);
        return 1;
    }

    printf("GPIO %d (BCM) set to output mode.\n", GPIO_PIN);

    // Main loop
    while (1) {
        // Set GPIO state
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break; // Exit loop on error
        }

        // Get current time
        time_t current_time = time(NULL);

        // Report state every 2 seconds
        if (current_time - last_report_time >= 2) {
            printf("GPIO %d set to %s\n", GPIO_PIN, state ? "HIGH" : "LOW");
            last_report_time = current_time;
        }

        // Toggle state
        state = !state;

        // Wait for 2 seconds
        sleep(2);
    }

    // Cleanup (should not reach here unless an error occurred)
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 1;
}

