#define W1_DEVICES_PATH "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define GPIO_PIN 4

static volatile int keep_running = 1;

void signal_handler(int sig) {
    keep_running = 0;
    printf("\nExiting gracefully...\n");
}

int read_ds18b20(float *temperature) {
    char w1_devices_path[256];
    char w1_device_path[512];
    char w1_slave_path[512];
    int fd;
    char buf[256];
    ssize_t num_read;
    char *temp_ptr;

    snprintf(w1_devices_path, sizeof(w1_devices_path), "%s", W1_DEVICES_PATH);

    fd = open(w1_devices_path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening /sys/bus/w1/devices/");
        return -1;
    }

    while (read(fd, buf, sizeof(buf)) > 0) {
        char *device_name = strstr(buf, "\n");
        if (device_name != NULL) {
            device_name++; // Move past the \n
            snprintf(w1_device_path, sizeof(w1_device_path), "%s%s", W1_DEVICES_PATH, device_name);
            break;
        }
    }
    close(fd);

    if (strlen(w1_device_path) == 0) {
        fprintf(stderr, "Error: DS18B20 device not found.\n");
        return -1;
    }

    snprintf(w1_slave_path, sizeof(w1_slave_path), "%s/%s", w1_device_path, W1_SLAVE_FILE);

    fd = open(w1_slave_path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening w1_slave file");
        return -1;
    }

    num_read = read(fd, buf, sizeof(buf));
    if (num_read < 0) {
        perror("Error reading w1_slave file");
        close(fd);
        return -1;
    }

    close(fd);

    if (strstr(buf, "YES") == NULL) {
        fprintf(stderr, "Error: CRC check failed.\n");
        return -1;
    }

    temp_ptr = strstr(buf, "t=");
    if (temp_ptr == NULL) {
        fprintf(stderr, "Error: Temperature data not found.\n");
        return -1;
    }

    long temp_reading = strtol(temp_ptr + 2, NULL, 10);
    *temperature = (float)temp_reading / 1000.0;

    return 0;
}

int main() {
    float temperature;
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    signal(SIGINT, signal_handler);

    for (int i = 0; i < 3 && keep_running; ++i) {
        if (read_ds18b20(&temperature) == 0) {
            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
        } else {
            fprintf(stderr, "Error reading temperature.\n");
            return 1;
        }
        sleep(5);
    }

    return 0;
}

