#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 18
#define ECHO_PIN 23

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
static volatile int running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
    gpioTerminate();
    exit(0);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the ECHO pin
long pulseIn(int pin, int level, int timeout) {
    long width = 0;
    long startTime = 0;
    long currentTime = 0;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        currentTime = gpioTick();
        if (startTime == 0) {
            startTime = currentTime;
        }
        if (currentTime - startTime > timeout) {
            return -1; // Timeout
        }
    }

    // Measure the pulse width
    startTime = gpioTick();
    while (gpioRead(pin) == level) {
        currentTime = gpioTick();
        if (currentTime - startTime > timeout) {
            return -1; // Timeout
        }
    }
    width = currentTime - startTime;

    return width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        triggerSensor();
        long pulseWidth = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulseWidth > 0) {
            float distance = calculateDistance(pulseWidth);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Timeout or error reading echo pulse\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

