#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for PWM outputs
#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to set PWM duty cycle
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

// Function to report the current PWM states
void report_pwm_states(int duty_cycle_1, int duty_cycle_2, int duty_cycle_3) {
    printf("PWM States: GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
           PWM_PIN_1, duty_cycle_1, PWM_PIN_2, duty_cycle_2, PWM_PIN_3, duty_cycle_3);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to PWM output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(PWM_PIN_1, 255);
    gpioSetPWMrange(PWM_PIN_2, 255);
    gpioSetPWMrange(PWM_PIN_3, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(PWM_PIN_1, 1000);
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Generate random duty cycles (0-255)
        int duty_cycle_1 = rand() % 256;
        int duty_cycle_2 = rand() % 256;
        int duty_cycle_3 = rand() % 256;

        // Set PWM duty cycles
        if (set_pwm_duty_cycle(PWM_PIN_1, duty_cycle_1) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_2, duty_cycle_2) != 0 ||
            set_pwm_duty_cycle(PWM_PIN_3, duty_cycle_3) != 0) {
            fprintf(stderr, "Error setting PWM duty cycles. Exiting.\n");
            break;
        }

        // Report PWM states
        report_pwm_states(duty_cycle_1, duty_cycle_2, duty_cycle_3);

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

