#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define DHT22_GPIO 4
#define MAX_TIMINGS 85
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[MAX_TIMINGS];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed to 30 microseconds

    gpioSetMode(gpio, PI_INPUT);

    // Read pulse lengths
    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpioRead(gpio) == (i % 2 == 0 ? 0 : 1)) {
            count++;
            gpioDelay(1); // Delay 1 microsecond
            if (count > 200) {
                fprintf(stderr, "Timeout waiting for DHT22 response.\n");
                return -1; // Timeout
            }
        }
        pulse_counts[i] = count;
    }

    // Decode data
    for (i = 2; i < 42; i++) {
        int index = i * 2;
        if (pulse_counts[index] > 25) {
            data[bit_count / 8] |= (1 << (7 - (bit_count % 8)));
        }
        bit_count++;
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "DHT22 checksum error.\n");
        return -2; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) + data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) + data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

int main() {
    int i, result;
    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    printf("DHT22 Sensor Reader\n");

    for (i = 0; i < MAX_RETRIES; i++) {
        result = read_dht22(DHT22_GPIO, &temperature, &humidity);

        if (result == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s - Temperature: %.1f°C, Humidity: %.1f%%\n", timestamp, temperature, humidity);
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "DHT22 read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1 second before retrying
        }
    }

    if (result != 0) {
        fprintf(stderr, "DHT22 read failed after %d retries.\n", MAX_RETRIES);
    }

    gpioTerminate();
    return 0;
}

