// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio22_line = NULL;
struct gpiod_line *gpio23_line = NULL;
struct gpiod_line *gpio24_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    struct gpiod_line_request_config config;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get GPIO line %d\n", gpio_pin);
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        fprintf(stderr, "Error: Could not request GPIO line %d for output\n", gpio_pin);
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) line = gpio17_line;
    else if (gpio_pin == GPIO_22) line = gpio22_line;
    else if (gpio_pin == GPIO_23) line = gpio23_line;
    else if (gpio_pin == GPIO_24) line = gpio24_line;
    else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line %d value to %d\n", gpio_pin, value);
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_17) line = gpio17_line;
    else if (gpio_pin == GPIO_22) line = gpio22_line;
    else if (gpio_pin == GPIO_23) line = gpio23_line;
    else if (gpio_pin == GPIO_24) line = gpio24_line;
    else {
        fprintf(stderr, "Error: Invalid GPIO pin %d\n", gpio_pin);
        return -1;
    }

    return gpiod_line_get_value(line);
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(void) {
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio23_line) {
        gpiod_line_release(gpio23_line);
    }
    if (gpio24_line) {
        gpiod_line_release(gpio24_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    time_t current_time;
    int gpio_values[4];
    int i;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip %s\n", CHIP_NAME);
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_17) < 0 ||
        initialize_gpio(GPIO_22) < 0 ||
        initialize_gpio(GPIO_23) < 0 ||
        initialize_gpio(GPIO_24) < 0) {
        cleanup_gpio();
        return 1;
    }

    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio22_line = gpiod_chip_get_line(chip, GPIO_22);
    gpio23_line = gpiod_chip_get_line(chip, GPIO_23);
    gpio24_line = gpiod_chip_get_line(chip, GPIO_24);

    // Main loop
    while (1) {
        // Get current time
        current_time = time(NULL);

        // Set GPIO values
        if (set_gpio_value(GPIO_17, 1) < 0) goto cleanup;
        if (set_gpio_value(GPIO_22, 0) < 0) goto cleanup;
        if (set_gpio_value(GPIO_23, 1) < 0) goto cleanup;
        if (set_gpio_value(GPIO_24, 0) < 0) goto cleanup;

        // Get GPIO values
        gpio_values[0] = get_gpio_value(GPIO_17);
        gpio_values[1] = get_gpio_value(GPIO_22);
        gpio_values[2] = get_gpio_value(GPIO_23);
        gpio_values[3] = get_gpio_value(GPIO_24);

        // Print GPIO values and timestamp
        printf("GPIO 17: %d, GPIO 22: %d, GPIO 23: %d, GPIO 24: %d, Timestamp: %ld\n",
               gpio_values[0], gpio_values[1], gpio_values[2], gpio_values[3], current_time);

        // Wait for 10 seconds
        sleep(10);
    }

cleanup:
    cleanup_gpio();
    return 1;
}

#include <stdio.h>
