// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18

// Define the number of cycles
#define NUM_CYCLES 5

// Define the delay between cycles (in seconds)
#define DELAY_SECONDS 0.05

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line4;
    struct gpiod_line *line17;
    struct gpiod_line *line18;
} gpio_state_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_state_t *state) {
    state->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    state->line4 = gpiod_chip_get_line(state->chip, GPIO_4);
    if (!state->line4) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_4, strerror(errno));
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->line17 = gpiod_chip_get_line(state->chip, GPIO_17);
    if (!state->line17) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(state->line4);
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->line18 = gpiod_chip_get_line(state->chip, GPIO_18);
    if (!state->line18) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(state->line4);
        gpiod_line_release(state->line17);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line4, "cycle_control_4", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_4, strerror(errno));
        gpiod_line_release(state->line4);
        gpiod_line_release(state->line17);
        gpiod_line_release(state->line18);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line17, "cycle_control_17", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_17, strerror(errno));
        gpiod_line_release(state->line4);
        gpiod_line_release(state->line17);
        gpiod_line_release(state->line18);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line18, "cycle_control_18", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_18, strerror(errno));
        gpiod_line_release(state->line4);
        gpiod_line_release(state->line17);
        gpiod_line_release(state->line18);
        gpiod_chip_close(state->chip);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to perform one cycle
int perform_cycle(gpio_state_t *state) {
    // Cycle 1: GPIO 4 = 1, GPIO 17 = 0, GPIO 18 = 0
    if (set_gpio_state(state->line4, 1) < 0) return -1;
    if (set_gpio_state(state->line17, 0) < 0) return -1;
    if (set_gpio_state(state->line18, 0) < 0) return -1;
    printf("Cycle 1: GPIO 4=1, GPIO 17=0, GPIO 18=0\n");
    usleep(DELAY_SECONDS * 1000000); // Delay for 0.05 seconds

    // Cycle 2: GPIO 4 = 0, GPIO 17 = 1, GPIO 18 = 0
    if (set_gpio_state(state->line4, 0) < 0) return -1;
    if (set_gpio_state(state->line17, 1) < 0) return -1;
    if (set_gpio_state(state->line18, 0) < 0) return -1;
    printf("Cycle 2: GPIO 4=0, GPIO 17=1, GPIO 18=0\n");
    usleep(DELAY_SECONDS * 1000000); // Delay for 0.05 seconds

    // Cycle 3: GPIO 4 = 0, GPIO 17 = 0, GPIO 18 = 1
    if (set_gpio_state(state->line4, 0) < 0) return -1;
    if (set_gpio_state(state->line17, 0) < 0) return -1;
    if (set_gpio_state(state->line18, 1) < 0) return -1;
    printf("Cycle 3: GPIO 4=0, GPIO 17=0, GPIO 18=1\n");
    usleep(DELAY_SECONDS * 1000000); // Delay for 0.05 seconds

    // Cycle 4: GPIO 4 = 1, GPIO 17 = 1, GPIO 18 = 1
    if (set_gpio_state(state->line4, 1) < 0) return -1;
    if (set_gpio_state(state->line17, 1) < 0) return -1;
    if (set_gpio_state(state->line18, 1) < 0) return -1;
    printf("Cycle 4: GPIO 4=1, GPIO 17=1, GPIO 18=1\n");
    usleep(DELAY_SECONDS * 1000000); // Delay for 0.05 seconds

    return 0;
}

// Function to cleanup GPIO lines
int cleanup_gpio(gpio_state_t *state) {
    if (state->line4) {
        gpiod_line_release(state->line4);
    }
    if (state->line17) {
        gpiod_line_release(state->line17);
    }
    if (state->line18) {
        gpiod_line_release(state->line18);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
    return 0;
}

int main() {
    gpio_state_t gpio_state = {0};

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO lines
    if (initialize_gpio(&gpio_state) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Perform cycles
    for (int i = 0; i < NUM_CYCLES && program_running; ++i) {
        if (perform_cycle(&gpio_state) < 0) {
            fprintf(stderr, "Cycle failed. Exiting.\n");
            break;
        }
    }

    // Cleanup GPIO lines
    if (cleanup_gpio(&gpio_state) < 0) {
        fprintf(stderr, "GPIO cleanup failed.\n");
    }

    printf("Program finished.\n");
    return 0;
}

