#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define GPIO_27 27

// Define the number of cycles
#define NUM_CYCLES 100

// Define the delay between cycles (in milliseconds)
#define DELAY_MS 500

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[7];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio(int gpio);
int set_gpio_value(int gpio, int value);
int get_gpio_value(int gpio);
void cleanup_gpio(int gpio);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize a GPIO pin
int initialize_gpio(int gpio) {
    struct gpiod_line_request_config config;
    int ret;

    memset(&config, 0, sizeof(config));
    config.consumer = "gpio_control";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    lines[gpio - 4] = gpiod_line_request(chip, gpio, &config, 0);
    if (!lines[gpio - 4]) {
        fprintf(stderr, "Error requesting line %d: %s\n", gpio, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to set the value of a GPIO pin
int set_gpio_value(int gpio, int value) {
    int ret = gpiod_line_set_value(lines[gpio - 4], value);
    if (ret < 0) {
        fprintf(stderr, "Error setting value for line %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to get the value of a GPIO pin
int get_gpio_value(int gpio) {
    int value = gpiod_line_get_value(lines[gpio - 4]);
    if (value < 0) {
        fprintf(stderr, "Error getting value for line %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return value;
}

// Function to cleanup a GPIO pin
void cleanup_gpio(int gpio) {
    gpiod_line_release(lines[gpio - 4]);
}

int main() {
    int i, j, state;
    time_t start_time, current_time;
    double elapsed_time;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO pins
    int gpios[] = {GPIO_4, GPIO_17, GPIO_22, GPIO_23, GPIO_24, GPIO_25, GPIO_27};
    for (i = 0; i < 7; i++) {
        if (initialize_gpio(gpios[i]) != 0) {
            fprintf(stderr, "Failed to initialize GPIO %d\n", gpios[i]);
            // Cleanup already initialized pins before exiting
            for (j = 0; j < i; j++) {
                cleanup_gpio(gpios[j]);
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    for (i = 0; i < NUM_CYCLES && !terminate; i++) {
        // Set all GPIOs to 1
        for (j = 0; j < 7; j++) {
            if (set_gpio_value(gpios[j], 1) != 0) {
                fprintf(stderr, "Failed to set GPIO %d to 1\n", gpios[j]);
                terminate = 1; // Stop the loop on error
                break;
            }
        }
        if (terminate) break;

        time(&start_time);
        usleep(DELAY_MS * 1000); // Delay for 0.5 seconds
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        // Set all GPIOs to 0
        for (j = 0; j < 7; j++) {
            if (set_gpio_value(gpios[j], 0) != 0) {
                fprintf(stderr, "Failed to set GPIO %d to 0\n", gpios[j]);
                terminate = 1; // Stop the loop on error
                break;
            }
        }
        if (terminate) break;

        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        printf("Cycle %d: GPIOs set to 1 for %.2f seconds, then set to 0 for %.2f seconds\n", i + 1, 0.5, 0.5);
    }

    // Cleanup GPIO pins
    for (i = 0; i < 7; i++) {
        cleanup_gpio(gpios[i]);
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return 0;
}

