    while (1) {
        // Set GPIO values
        if (set_gpio_value(GPIO_17, gpio_values[0]) < 0 ||
            set_gpio_value(GPIO_18, gpio_values[1]) < 0 ||
            set_gpio_value(GPIO_23, gpio_values[2]) < 0) {
            cleanup_gpio();
            return 1;
        }

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp and GPIO values
        printf("%s - GPIO 17: %d, GPIO 18: %d, GPIO 23: %d\n",
               timestamp,
               get_gpio_value(GPIO_17),
               get_gpio_value(GPIO_18),
               get_gpio_value(GPIO_23));

        // Increment GPIO values (cycle through 0, 1, 0)
        for (i = 0; i < 3; i++) {
            gpio_values[i] = (gpio_values[i] + 1) % 2;
        }

        // Wait for 0.1 seconds
        usleep(100000); // 100000 microseconds = 0.1 seconds
    }

    return 0;
}

