#define DHT22_GPIO 4
#define MAX_TIMINGS 85
#define TIMEOUT_US 100000 // 100ms timeout

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to read DHT22 data
int read_dht22(int gpio, float *temperature, float *humidity) {
    int data[5] = {0, 0, 0, 0, 0};
    int bit_count = 0;
    int pulse_counts[MAX_TIMINGS];
    int i, j;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1);
    gpioWrite(gpio, 1);
    gpioDelay(30); // Changed to 30us

    gpioSetMode(gpio, PI_INPUT);

    int timeout_counter = 0;
    for (i = 0; i < MAX_TIMINGS; i++) {
        int count = 0;
        while (gpioRead(gpio) == (1 - (i % 2))) {
            count++;
            gpioDelay(1); // Delay 1us
            if (count > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for pin to change state.\n");
                return -1; // Timeout
            }
        }
        pulse_counts[i] = count;
    }

    for (i = 0; i < 40; i++) {
        int index = 2 * i + 1;
        if (pulse_counts[index] > 25) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Validate checksum
    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) {
        fprintf(stderr, "Checksum failure.\n");
        return -1; // Checksum failure
    }

    *humidity = (float)(((data[0] << 8) + data[1])) / 10.0;
    *temperature = (float)(((data[2] << 8) + data[3])) / 10.0;
    if (*temperature > 125) {
        *temperature = *temperature - 256;
    }

    return 0; // Success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    float temperature, humidity;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    for (int i = 0; i < 3 && !terminate; i++) {
        int result = read_dht22(DHT22_GPIO, &temperature, &humidity);
        if (result == 0) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s - Temperature: %.1f°C, Humidity: %.1f%%\n", timestamp, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor.\n");
        }
        sleep(60);
    }

    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define GPIO8 8
#define GPIO9 9
#define GPIO10 10
#define GPIO11 11
#define GPIO23 23

// Define the number of cycles
#define NUM_CYCLES 3

// Define the duration of each cycle in seconds
#define CYCLE_DURATION 1

// Structure to hold GPIO chip and line information
typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line8;
    struct gpiod_line *line9;
    struct gpiod_line *line10;
    struct gpiod_line *line11;
    struct gpiod_line *line23;
} gpio_state_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", sig);
}

// Function to initialize GPIO lines
int initialize_gpio(gpio_state_t *state) {
    state->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Error opening GPIO chip.\n");
        return -1;
    }

    state->line8 = gpiod_chip_get_line(state->chip, GPIO8);
    state->line9 = gpiod_chip_get_line(state->chip, GPIO9);
    state->line10 = gpiod_chip_get_line(state->chip, GPIO10);
    state->line11 = gpiod_chip_get_line(state->chip, GPIO11);
    state->line23 = gpiod_chip_get_line(state->chip, GPIO23);

    if (!state->line8 || !state->line9 || !state->line10 || !state->line11 || !state->line23) {
        fprintf(stderr, "Error getting GPIO line.\n");
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->line8, "cycle", 0) < 0 ||
        gpiod_line_request_output(state->line9, "cycle", 0) < 0 ||
        gpiod_line_request_output(state->line10, "cycle", 0) < 0 ||
        gpiod_line_request_output(state->line11, "cycle", 0) < 0 ||
        gpiod_line_request_output(state->line23, "cycle", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line for output.\n");
        gpiod_chip_close(state->chip);
        gpiod_line_release(state->line8);
        gpiod_line_release(state->line9);
        gpiod_line_release(state->line10);
        gpiod_line_release(state->line11);
        gpiod_line_release(state->line23);
        return -1;
    }

    return 0;
}

// Function to perform one cycle
void perform_cycle(gpio_state_t *state) {
    // Cycle 1: GPIO8 = 1, GPIO9 = 0, GPIO10 = 1, GPIO11 = 0, GPIO23 = 1
    if (gpiod_line_set_value(state->line8, 1) < 0 ||
        gpiod_line_set_value(state->line9, 0) < 0 ||
        gpiod_line_set_value(state->line10, 1) < 0 ||
        gpiod_line_set_value(state->line11, 0) < 0 ||
        gpiod_line_set_value(state->line23, 1) < 0) {
        fprintf(stderr, "Error setting GPIO value.\n");
        return;
    }
    printf("Cycle 1: GPIO8=1, GPIO9=0, GPIO10=1, GPIO11=0, GPIO23=1\n");
    sleep(CYCLE_DURATION);

    // Cycle 2: GPIO8 = 0, GPIO9 = 1, GPIO10 = 0, GPIO11 = 1, GPIO23 = 0
    if (gpiod_line_set_value(state->line8, 0) < 0 ||
        gpiod_line_set_value(state->line9, 1) < 0 ||
        gpiod_line_set_value(state->line10, 0) < 0 ||
        gpiod_line_set_value(state->line11, 1) < 0 ||
        gpiod_line_set_value(state->line23, 0) < 0) {
        fprintf(stderr, "Error setting GPIO value.\n");
        return;
    }
    printf("Cycle 2: GPIO8=0, GPIO9=1, GPIO10=0, GPIO11=1, GPIO23=0\n");
    sleep(CYCLE_DURATION);

    // Cycle 3: GPIO8 = 1, GPIO9 = 1, GPIO10 = 0, GPIO11 = 0, GPIO23 = 1
    if (gpiod_line_set_value(state->line8, 1) < 0 ||
        gpiod_line_set_value(state->line9, 1) < 0 ||
        gpiod_line_set_value(state->line10, 0) < 0 ||
        gpiod_line_set_value(state->line11, 0) < 0 ||
        gpiod_line_set_value(state->line23, 1) < 0) {
        fprintf(stderr, "Error setting GPIO value.\n");
        return;
    }
    printf("Cycle 3: GPIO8=1, GPIO9=1, GPIO10=0, GPIO11=0, GPIO23=1\n");
    sleep(CYCLE_DURATION);
}

// Function to release GPIO lines
void cleanup_gpio(gpio_state_t *state) {
    gpiod_line_release(state->line8);
    gpiod_line_release(state->line9);
    gpiod_line_release(state->line10);
    gpiod_line_release(state->line11);
    gpiod_line_release(state->line23);
    gpiod_chip_close(state->chip);
}

int main() {
    gpio_state_t gpio_state;
    int cycle_count = 0;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_state) < 0) {
        return 1;
    }

    // Perform cycles
    while (program_running && cycle_count < NUM_CYCLES) {
        perform_cycle(&gpio_state);
        cycle_count++;
    }

    // Cleanup GPIO
    cleanup_gpio(&gpio_state);

    printf("Program finished.\n");
    return 0;
}

