}

// Function to report the current PWM states
void report_pwm_states() {
    int pwm1_value = gpioGetPWMdutycycle(PWM_PIN_1);
    int pwm2_value = gpioGetPWMdutycycle(PWM_PIN_2);
    int pwm3_value = gpioGetPWMdutycycle(PWM_PIN_3);

    printf("PWM1: %d, PWM2: %d, PWM3: %d\n", pwm1_value, pwm2_value, pwm3_value);
}

