    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to PWM output mode
    gpioSetMode(PWM_PIN_1, PI_OUTPUT);
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(PWM_PIN_1, 1000); // 1 kHz
    gpioSetPWMfrequency(PWM_PIN_2, 1000);
    gpioSetPWMfrequency(PWM_PIN_3, 1000);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(PWM_PIN_1, 1000);
    gpioSetPWMrange(PWM_PIN_2, 1000);
    gpioSetPWMrange(PWM_PIN_3, 1000);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Set PWM duty cycles (adjust as needed)
        set_pwm_duty_cycle(PWM_PIN_1, 500); // 50% duty cycle
        set_pwm_duty_cycle(PWM_PIN_2, 250); // 25% duty cycle
        set_pwm_duty_cycle(PWM_PIN_3, 750); // 75% duty cycle

        // Report PWM states
        report_pwm_states();

        // Wait for 1 second
        sleep(1);
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

