#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MAX31855 register addresses
#define MAX31855_CONFIG_REG 0x00
#define MAX31855_FAULT_REG 0x01
#define MAX31855_TEMP_MSB_REG 0x02
#define MAX31855_TEMP_LSB_REG 0x03
#define MAX31855_VOLTAGE_MSB_REG 0x04
#define MAX31855_VOLTAGE_LSB_REG 0x05

// Global variables for cleanup
static int spi_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the SPI device
int spi_init(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read data from the MAX31855
int read_max31855(int spi_fd, uint16_t *data) {
    uint8_t tx_buf[4] = {0}; // Dummy data for reading
    uint8_t rx_buf[4] = {0};

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to parse the MAX31855 data
void parse_max31855_data(uint16_t raw_data, float *temperature, float *voltage) {
    // Check for fault bits
    if (raw_data & 0x0001) {
        fprintf(stderr, "MAX31855 Fault: %04X\n", raw_data);
        *temperature = -999.0; // Indicate error
        *voltage = -999.0;
        return;
    }

    // Extract temperature data
    int16_t temp_raw = (raw_data >> 18) & 0x3FFF; // Mask out fault bits and shift
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000; // Sign extend if negative
    }
    *temperature = temp_raw * 0.25;

    // Extract voltage data
    int16_t voltage_raw = (raw_data >> 4) & 0x07FF; // Mask out fault bits and shift
    *voltage = voltage_raw * 0.005;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return 1;
    }

    uint16_t raw_data;
    float temperature, voltage;

    // Main loop
    while (!terminate) {
        if (read_max31855(spi_fd, &raw_data) == 0) {
            parse_max31855_data(raw_data, &temperature, &voltage);
            printf("Temperature: %.2f C, Voltage: %.2f V\n", temperature, voltage);
        } else {
            fprintf(stderr, "Failed to read MAX31855 data.\n");
        }

        sleep(1); // Read every 1 second
    }

    // Cleanup
    close(spi_fd);
    fprintf(stderr, "SPI device closed.\n");

    return 0;
}

