    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    struct gpiod_line *line;

    if (gpio == GPIO_17) {
        line = line17;
    } else if (gpio == GPIO_18) {
        line = line18;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
        return -1;
    }

    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state: %d\n", gpio, ret);
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio) {
    struct gpiod_line *line;

    if (gpio == GPIO_17) {
        line = line17;
    } else if (gpio == GPIO_18) {
        line = line18;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio);
        return -1;
    }

    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %d\n", gpio, value);
        return -1;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get GPIO lines
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Error getting GPIO %d line\n", GPIO_17);
        gpiod_chip_close(chip);
        return 1;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO %d line\n", GPIO_18);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(line17, "my_app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_17);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    if (gpiod_line_request_output(line18, "my_app", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d for output\n", GPIO_18);
        gpiod_line_release(line17);
        gpiod_line_release(line18);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 to 1
        if (set_gpio_state(GPIO_17, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 17 state\n");
            break;
        }
        printf("GPIO 17 set to 1\n");

        // Set GPIO 18 to 0
        if (set_gpio_state(GPIO_18, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 18 state\n");
            break;
        }
        printf("GPIO 18 set to 0\n");

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);

        // Set GPIO 17 to 0
        if (set_gpio_state(GPIO_17, 0) < 0) {
            fprintf(stderr, "Error setting GPIO 17 state\n");
            break;
        }
        printf("GPIO 17 set to 0\n");

        // Set GPIO 18 to 1
        if (set_gpio_state(GPIO_18, 1) < 0) {
            fprintf(stderr, "Error setting GPIO 18 state\n");
            break;
        }
        printf("GPIO 18 set to 1\n");

        // Wait for 0.1 seconds
        nanosleep(&ts, NULL);
    }

    // Cleanup (should not reach here unless an error occurred)
    gpiod_line_release(line17);
    gpiod_line_release(line18);
    gpiod_chip_close(chip);

    return 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // Timeout in microseconds (0.5 seconds)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(int start_tick, int end_tick);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that the echo has started
        timeout_flag = 0;   // Reset timeout flag
    } else if (level == 0) {
        if (echo_received) {
            echo_end_tick = tick;
            echo_received = 0; // Reset echo received flag
        }
    }
}

// Function to calculate distance in centimeters
float calculate_distance(int start_tick, int end_tick) {
    if (start_tick == 0 || end_tick == 0) {
        return -1.0; // Indicate error
    }

    int diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (1) {
        trigger_pulse();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (!echo_received && !timeout_flag) {
            gpioDelay(100); // Check every 100 us
            timeout_count++;
            if (timeout_count * 100 > TIMEOUT_US) {
                timeout_flag = 1;
                echo_end_tick = 0; // Reset end tick on timeout
            }
        }

        if (timeout_flag) {
            printf("Timeout occurred\n");
        } else {
            float distance = calculate_distance(echo_start_tick, echo_end_tick);
            if (distance > 0) {
                printf("Distance: %.2f cm\n", distance);
            } else {
                printf("Error calculating distance\n");
            }
        }

        timeout_flag = 0; // Reset timeout flag for next measurement
        echo_received = 0; // Reset echo received flag
        echo_start_tick = 0; // Reset start tick
        echo_end_tick = 0;   // Reset end tick

        gpioDelay(500); // Delay between measurements
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    gpioTerminate();
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", GPIO_CHIP);
        return 1;
    }

    // Get the line for the GPIO pin
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for output
    ret = gpiod_line_request(line, "output", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the GPIO pin to high
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO pin high: %s\n", strerror(-ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to HIGH\n", GPIO_PIN);

    // Release the line and close the chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x03

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Global variables
int i2c_fd = -1; // I2C file descriptor
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function to handle Ctrl+C signal
void signal_handler(int sig) {
    program_running = 0;
    printf("\nExiting program...\n");
}

// Function to initialize the BMP280 sensor
int bmp280_init(int fd) {
    // Set the sensor to forced mode
    uint8_t ctrl_meas = 0b00100011; // Oversampling x1, forced mode
    if (write(fd, &ctrl_meas, 1) != 1) {
        perror("Error writing to CTRL_MEAS register");
        return -1;
    }

    // Set the configuration register (t_sb = 0.5ms, filter = off)
    uint8_t config = 0b00000000;
    if (write(fd, &config, 1) != 1) {
        perror("Error writing to CONFIG register");
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP280
int bmp280_read_calibration_data(int fd, struct bmp280_calib_data *calib) {
    uint8_t data[24];
    if (read(fd, data, 24) != 24) {
        perror("Error reading calibration data");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Function to read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (read(fd, data, 6) != 6) {
        perror("Error reading raw data");
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Function to compensate temperature
int32_t bmp280_compensate_temperature(int32_t raw_temperature, struct bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return (int32_t)(T * 100); // Return temperature in 0.01 degree Celsius
}

// Function to compensate pressure
uint32_t bmp280_compensate_pressure(int32_t raw_pressure, int32_t t_fine, struct bmp280_calib_data calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0; // avoid exception caused by division by zero
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return (uint32_t)(p * 100); // Return pressure in Pa
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BMP280 sensor
    if (bmp280_init(i2c_fd) < 0) {
        fprintf(stderr, "BMP280 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data(i2c_fd, &calib) < 0) {
        fprintf(stderr, "Failed to read calibration data.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop to read and print temperature and pressure
    for (int i = 0; i < 3 && program_running; ++i) {
        int32_t raw_temperature, raw_pressure;
        int32_t t_fine;

        // Read raw data
        if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) < 0) {
            fprintf(stderr, "Failed to read raw data.\n");
            break; // Exit loop on error
        }

        // Compensate temperature and pressure
        t_fine = bmp280_compensate_temperature(raw_temperature, calib);
        uint32_t pressure = bmp280_compensate_pressure(raw_pressure, t_fine, calib);

        // Print the compensated values
        printf("Temperature: %d.%02d C, Pressure: %u Pa\n", t_fine / 100, abs(t_fine % 100), pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_line *gpio17_line = NULL;
struct gpiod_line *gpio22_line = NULL;
struct gpiod_line *gpio23_line = NULL;
struct gpiod_line *gpio24_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int set_gpio_state(int gpio_pin, int state);
int get_gpio_state(int gpio_pin);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Release GPIO lines
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio22_line) {
        gpiod_line_release(gpio22_line);
    }
    if (gpio23_line) {
        gpiod_line_release(gpio23_line);
    }
    if (gpio24_line) {
        gpiod_line_release(gpio24_line);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    int ret;
    struct gpiod_line *line;

    switch (gpio_pin) {
        case GPIO_17:
            line = gpio17_line;
            break;
        case GPIO_22:
            line = gpio22_line;
            break;
        case GPIO_23:
            line = gpio23_line;
            break;
        case GPIO_24:
            line = gpio24_line;
            break;
        default:
            fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
            return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", gpio_pin, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(int gpio_pin) {
    int ret;
    struct gpiod_line *line;

    switch (gpio_pin) {
        case GPIO_17:
            line = gpio17_line;
            break;
        case GPIO_22:
            line = gpio22_line;
            break;
        case GPIO_23:
            line = gpio23_line;
            break;
        case GPIO_24:
            line = gpio24_line;
            break;
        default:
            fprintf(stderr, "Error: Invalid GPIO pin number: %d\n", gpio_pin);
            return -1;
    }

    ret = gpiod_line_get_value(line);
    if (ret < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %s\n", gpio_pin, strerror(-ret));
        return -1;
    }

    return ret;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    gpio22_line = gpiod_chip_get_line(chip, GPIO_22);
    gpio23_line = gpiod_chip_get_line(chip, GPIO_23);
    gpio24_line = gpiod_chip_get_line(chip, GPIO_24);

    if (!gpio17_line || !gpio22_line || !gpio23_line || !gpio24_line) {
        perror("Error getting GPIO line");
        cleanup(0);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(gpio17_line, "my_app", 0) < 0) {
        perror("Error requesting GPIO 17 for output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(gpio22_line, "my_app", 0) < 0) {
        perror("Error requesting GPIO 22 for output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(gpio23_line, "my_app", 0) < 0) {
        perror("Error requesting GPIO 23 for output");
        cleanup(0);
        return 1;
    }
    if (gpiod_line_request_output(gpio24_line, "my_app", 0) < 0) {
        perror("Error requesting GPIO 24 for output");
        cleanup(0);
        return 1;
    }

    // Set initial state (LOW)
    if (set_gpio_state(GPIO_17, 0) < 0) return 1;
    if (set_gpio_state(GPIO_22, 0) < 0) return 1;
    if (set_gpio_state(GPIO_23, 0) < 0) return 1;
    if (set_gpio_state(GPIO_24, 0) < 0) return 1;

    // Print initial state
    printf("GPIO 17: %d\n", get_gpio_state(GPIO_17));
    printf("GPIO 22: %d\n", get_gpio_state(GPIO_22));
    printf("GPIO 23: %d\n", get_gpio_state(GPIO_23));
    printf("GPIO 24: %d\n", get_gpio_state(GPIO_24));

    // Set state to HIGH
    if (set_gpio_state(GPIO_17, 1) < 0) return 1;
    if (set_gpio_state(GPIO_22, 1) < 0) return 1;
    if (set_gpio_state(GPIO_23, 1) < 0) return 1;
    if (set_gpio_state(GPIO_24, 1) < 0) return 1;

    // Print updated state
    printf("GPIO 17: %d\n", get_gpio_state(GPIO_17));
    printf("GPIO 22: %d\n", get_gpio_state(GPIO_22));
    printf("GPIO 23: %d\n", get_gpio_state(GPIO_23));
    printf("GPIO 24: %d\n", get_gpio_state(GPIO_24));

    // Wait for a while (e.g., 5 seconds)
    sleep(5);

    // Set state to LOW again
    if (set_gpio_state(GPIO_17, 0) < 0) return 1;
    if (set_gpio_state(GPIO_22, 0) < 0) return 1;
    if (set_gpio_state(GPIO_23, 0) < 0) return 1;
    if (set_gpio_state(GPIO_24, 0) < 0) return 1;

    // Print final state
    printf("GPIO 17: %d\n", get_gpio_state(GPIO_17));
    printf("GPIO 22: %d\n", get_gpio_state(GPIO_22));
    printf("GPIO 23: %d\n", get_gpio_state(GPIO_23));
    printf("GPIO 24: %d\n", get_gpio_state(GPIO_24));

    // Cleanup and exit
    cleanup(0);

    return 0;
}

