#include <string.h>
#include <signal.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18

struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Function to set the GPIO pin state
int set_gpio_state(int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO state: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main() {
    int ret;
    int state = 1; // Initial state: HIGH

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for output
    ret = gpiod_line_request_output(line, "example", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        return 1;
    }

    // Set the initial state
    if (set_gpio_state(state) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d set to %d\n", GPIO_PIN, state);

    // Cleanup (should not reach here in normal execution due to signal handler)
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        keep_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state;
    int ret;
    int i;

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request the line for output */
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop: toggle the GPIO state */
    while (keep_running) {
        /* Read the current state */
        state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
            break; /* Exit loop on error */
        }

        /* Toggle the state */
        state = !state;

        /* Set the new state */
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d to %d: %s\n", GPIO_PIN, state, strerror(errno));
            break; /* Exit loop on error */
        }

        /* Report the state */
        printf("GPIO %d set to %d\n", GPIO_PIN, state);

        /* Wait for a short period */
        usleep(500000); /* 0.5 seconds */
    }

    /* Release the GPIO line */
    gpiod_line_release(line);

    /* Close the GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <time.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_ID 0xD0

// Calibration data registers
#define BME280_REG_CALIB_00 0x88

// Global variables for calibration data
int32_t t_fine;
uint16_t dig_T1;
int16_t dig_T2;
int16_t dig_T3;
uint16_t dig_P1;
int16_t dig_P2;
int16_t dig_P3;
int16_t dig_P4;
int16_t dig_P5;
int16_t dig_P6;
int16_t dig_P7;
int16_t dig_P8;
int16_t dig_P9;
uint8_t dig_H1;
int16_t dig_H2;
uint8_t dig_H3;
int16_t dig_H4;
int16_t dig_H5;
int8_t dig_H6;

// Function to read a single byte from the I2C device
int i2c_read_byte(int file_descriptor, uint8_t reg_address)
{
    if (write(file_descriptor, &reg_address, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t buffer[1];
    if (read(file_descriptor, buffer, 1) != 1) {
        perror("Failed to read byte");
        return -1;
    }

    return buffer[0];
}

// Function to write a single byte to the I2C device
int i2c_write_byte(int file_descriptor, uint8_t reg_address, uint8_t value)
{
    uint8_t buffer[2];
    buffer[0] = reg_address;
    buffer[1] = value;

    if (write(file_descriptor, buffer, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }

    return 0;
}

// Function to read multiple bytes from the I2C device
int i2c_read_bytes(int file_descriptor, uint8_t reg_address, uint8_t *buffer, int length)
{
    if (write(file_descriptor, &reg_address, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(file_descriptor, buffer, length) != length) {
        perror("Failed to read bytes");
        return -1;
    }

    return 0;
}

// Function to initialize the BME280 sensor
int bme280_init(int file_descriptor)
{
    // Check the device ID
    int device_id = i2c_read_byte(file_descriptor, BME280_REG_ID);
    if (device_id != 0x60) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", device_id);
        return -1;
    }

    // Read calibration data
    uint8_t calib_data[26];
    if (i2c_read_bytes(file_descriptor, BME280_REG_CALIB_00, calib_data, 26) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    dig_T1 = (calib_data[1] << 8) | calib_data[0];
    dig_T2 = (int16_t)((calib_data[3] << 8) | calib_data[2]);
    dig_T3 = (int16_t)((calib_data[5] << 8) | calib_data[4]);
    dig_P1 = (calib_data[7] << 8) | calib_data[6];
    dig_P2 = (int16_t)((calib_data[9] << 8) | calib_data[8]);
    dig_P3 = (int16_t)((calib_data[11] << 8) | calib_data[10]);
    dig_P4 = (int16_t)((calib_data[13] << 8) | calib_data[12]);
    dig_P5 = (int16_t)((calib_data[15] << 8) | calib_data[14]);
    dig_P6 = (int16_t)((calib_data[17] << 8) | calib_data[16]);
    dig_P7 = (int16_t)((calib_data[19] << 8) | calib_data[18]);
    dig_P8 = (int16_t)((calib_data[21] << 8) | calib_data[20]);
    dig_P9 = (int16_t)((calib_data[23] << 8) | calib_data[22]);
    dig_H1 = calib_data[25];

    uint8_t calib_data_h[7];
    if (i2c_read_bytes(file_descriptor, 0xE1, calib_data_h, 7) != 0) {
        fprintf(stderr, "Error reading humidity calibration data\n");
        return -1;
    }

    dig_H2 = (int16_t)((calib_data_h[1] << 8) | calib_data_h[0]);
    dig_H3 = calib_data_h[2];
    dig_H4 = (calib_data_h[3] << 4) | (calib_data_h[4] & 0x0F);
    dig_H5 = (calib_data_h[5] << 4) | (calib_data_h[4] >> 4);
    dig_H6 = (int8_t)calib_data_h[6];

    // Set humidity oversampling to 1x
    if (i2c_write_byte(file_descriptor, BME280_REG_CTRL_HUM, 0x01) != 0) {
        fprintf(stderr, "Error writing humidity control register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2c_write_byte(file_descriptor, BME280_REG_CTRL_MEAS, 0x27) != 0) {
        fprintf(stderr, "Error writing control register\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature, pressure, and humidity data
int bme280_read_data(int file_descriptor, int32_t *temperature, int32_t *pressure, int32_t *humidity)
{
    uint8_t data[8];

    if (i2c_read_bytes(file_descriptor, BME280_REG_PRESSURE_MSB, data, 8) != 0) {
        fprintf(stderr, "Error reading data\n");
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// Function to compensate temperature
float compensate_temperature(int32_t raw_temperature)
{
    float var1 = (raw_temperature / 16384.0 - dig_T1 / 1024.0) * dig_T2;
    float var2 = ((raw_temperature / 131072.0 - dig_T1 / 8192.0) * (raw_temperature / 131072.0 - dig_T1 / 8192.0)) * dig_T3;
    t_fine = (int32_t)(var1 + var2);
    float T = (var1 + var2) / 5120.0;
    return T;
}

// Function to compensate pressure
float compensate_pressure(int32_t raw_pressure)
{
    float var1 = t_fine / 2.0 - 64000.0;
    float var2 = var1 * var1 * dig_P6 / 32768.0;
    var2 = var2 + var1 * dig_P5 * 2.0;
    var2 = var2 / 4.0 + dig_P4 * 65536.0;
    var1 = (dig_P3 * var1 * var1 / 524288.0 + dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * dig_P1;

    if (var1 == 0)
    {
        return 0;
    }

    float p = 1048576.0 - raw_pressure;
    p = (p - var2 / 4096.0) * 6250.0 / var1;
    var1 = dig_P9 * p * p / 2147483648.0;
    var2 = p * dig_P8 / 32768.0;
    p = p + (var1 + var2 + dig_P7) / 16.0;

    return p;
}

// Function to compensate humidity
float compensate_humidity(int32_t raw_humidity)
{
    float var_H;
    var_H = (t_fine - 76800.0);
    var_H = (raw_humidity - (dig_H4 * 64.0 + dig_H5 / 16384.0 * var_H)) * (dig_H2 / 65536.0 * (1.0 + dig_H6 / 67108864.0 * var_H * (1.0 + dig_H3 / 67108864.0 * var_H)));
    var_H = var_H * (1.0 - dig_H1 * var_H / 524288.0);

    if (var_H > 100.0)
    {
        var_H = 100.0;
    } else if (var_H < 0.0)
    {
        var_H = 0.0;
    }

    return var_H;
}

int main()
{
    int file_descriptor;
    const char *i2c_device = "/dev/i2c-1";

    // Open the I2C device
    file_descriptor = open(i2c_device, O_RDWR);
    if (file_descriptor < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(file_descriptor, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(file_descriptor);
        return 1;
    }

    // Initialize the BME280 sensor
    if (bme280_init(file_descriptor) != 0) {
        fprintf(stderr, "BME280 initialization failed\n");
        close(file_descriptor);
        return 1;
    }

    // Read and print sensor data three times
    for (int i = 0; i < 3; i++) {
        int32_t raw_temperature, raw_pressure, raw_humidity;

        if (bme280_read_data(file_descriptor, &raw_temperature, &raw_pressure, &raw_humidity) == 0) {
            float temperature = compensate_temperature(raw_temperature);
            float pressure = compensate_pressure(raw_pressure);
            float humidity = compensate_humidity(raw_humidity);

            printf("Temperature: %.2f °C, Pressure: %.2f Pa, Humidity: %.2f %%\n", temperature, pressure, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Close the I2C device
    close(file_descriptor);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    int state = 0;
    struct timespec sleep_time;
    sleep_time.tv_sec = 1;
    sleep_time.tv_nsec = 0;

    /* Register signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Open GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    /* Get GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request GPIO line for output */
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d (BCM) set to output mode.\n", GPIO_PIN);

    /* Main loop */
    while (!terminate) {
        /* Set GPIO state */
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("Error setting GPIO state");
            break;
        }

        /* Get current time */
        time_t now = time(NULL);
        struct tm *tstruct = localtime(&now);
        char buf[80];
        strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

        /* Print state and timestamp */
        printf("%s GPIO %d set to %d\n", buf, GPIO_PIN, state);

        /* Toggle state */
        state = !state;

        /* Sleep for 1 second */
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    /* Release GPIO line */
    gpiod_line_release(line);

    /* Close GPIO chip */
    gpiod_chip_close(chip);

    printf("GPIO %d released.\n", GPIO_PIN);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <signal.h>
#include <errno.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x10

// VEML7700 register addresses
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS_DATA 0x04

// I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from an I2C register
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Configure VEML7700 (example configuration)
    if (i2c_write_reg(i2c_fd, VEML7700_ALS_CONF, 0x00) < 0) { // Integration time = 100ms, Gain = 1/8
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t als_data;

        // Read ALS data
        if (i2c_read_word(i2c_fd, VEML7700_ALS_DATA, &als_data) < 0) {
            fprintf(stderr, "Error reading ALS data. Retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Print the reading
        printf("ALS Data: %u\n", als_data);

        // Wait 500ms
        usleep(500000);
    }

    // The program should never reach here due to the infinite loop.
    close(i2c_fd);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define UART_DEVICE "/dev/ttyS0" // Or /dev/ttyAMA0
#define BAUD_RATE B115200
#define TIMEOUT_MS 100

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int setup_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = BAUD_RATE | CS8 | CLOCAL | CREAD; // 8N1, no parity
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = 1; // Wait for 0.1 seconds (100ms)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int read_data(int fd, char *buffer, size_t buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            return 0; // Timeout
        }
        perror("Error reading from UART");
        return -1;
    } else {
        buffer[bytes_read] = '\0';
        return bytes_read;
    }
}

int main() {
    signal(SIGINT, signal_handler);

    uart_fd = setup_uart(UART_DEVICE);
    if (uart_fd == -1) {
        return EXIT_FAILURE;
    }

    char buffer[256];
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    printf("Starting data exchange...\n");

    while (program_running) {
        ssize_t bytes_read = read_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read > 0) {
            printf("Received: %s", buffer);
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading, exiting.\n");
            break;
        }

        nanosleep(&sleep_time, NULL);
    }

    close(uart_fd);
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define timeout in microseconds
#define TIMEOUT_US 50000

// Define valid distance range in centimeters
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *trigger_line;
struct gpiod_line *echo_line;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to trigger the HC-SR04 sensor
int trigger_sensor(struct gpiod_line *trigger_line) {
    int ret;
    ret = gpiod_line_set_value(trigger_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger high: %s\n", strerror(-ret));
        return -1;
    }
    usleep(10); // 10us trigger pulse
    ret = gpiod_line_set_value(trigger_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting trigger low: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to measure the echo pulse width
long measure_pulse_width(struct gpiod_line *echo_line) {
    struct timespec start, end;
    long pulse_width = 0;
    int ret;

    // Wait for the echo pin to go high
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading echo pin: %s\n", strerror(-ret));
            return -1;
        }
        if (ret == 1) {
            clock_gettime(CLOCK_MONOTONIC, &start);
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (pulse_width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }

    // Wait for the echo pin to go low
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        ret = gpiod_line_get_value(echo_line);
        if (ret < 0) {
            fprintf(stderr, "Error reading echo pin: %s\n", strerror(-ret));
            return -1;
        }
        if (ret == 0) {
            clock_gettime(CLOCK_MONOTONIC, &end);
            pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
            return pulse_width;
        }
        clock_gettime(CLOCK_MONOTONIC, &end);
        pulse_width = (end.tv_sec - start.tv_sec) * 1000000 + (end.tv_nsec - start.tv_nsec) / 1000;
        if (pulse_width > TIMEOUT_US) {
            return -1; // Timeout
        }
    }
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    return (pulse_width * 0.0343) / 2.0;
}

// Function to validate the distance
int validate_distance(float distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Function to report the distance
void report_distance(float distance) {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    int ret;
    long pulse_width;
    float distance;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get trigger line
    trigger_line = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trigger_line) {
        fprintf(stderr, "Error getting trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get echo line
    echo_line = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo_line) {
        fprintf(stderr, "Error getting echo line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        return 1;
    }

    // Request trigger line for output
    ret = gpiod_line_request_output(trigger_line, "trigger", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting trigger line for output: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return 1;
    }

    // Request echo line for input
    ret = gpiod_line_request_input(echo_line, "echo");
    if (ret < 0) {
        fprintf(stderr, "Error requesting echo line for input: %s\n", strerror(-ret));
        gpiod_chip_close(chip);
        gpiod_line_release(trigger_line);
        gpiod_line_release(echo_line);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        if (trigger_sensor(trigger_line) < 0) {
            fprintf(stderr, "Error triggering sensor, retrying...\n");
            usleep(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Measure the pulse width
        pulse_width = measure_pulse_width(echo_line);
        if (pulse_width < 0) {
            fprintf(stderr, "Error measuring pulse width, retrying...\n");
            usleep(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Calculate the distance
        distance = calculate_distance(pulse_width);

        // Validate the distance
        if (validate_distance(distance)) {
            // Report the distance
            report_distance(distance);
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        // Wait 0.5 seconds
        usleep(500000);
    }

    // Release GPIO lines
    gpiod_line_release(trigger_line);
    gpiod_line_release(echo_line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

