#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDRESS 0x53
#define POWER_CTL 0x2D
#define DATAX0 0x32

int main() {
    int file;
    int fd;
    uint8_t buffer[6];
    int16_t x, y, z;

    // Open I2C bus
    if ((fd = open(I2C_BUS, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set ADXL345 address
    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    // Enable measurement mode
    uint8_t power_ctl_value = 0x08; // Set measure bit
    if (write(fd, &power_ctl_value, 1) != 1) {
        perror("Failed to write to POWER_CTL register");
        close(fd);
        return 1;
    }

    // Read acceleration data
    if (read(fd, buffer, 6) != 6) {
        perror("Failed to read acceleration data");
        close(fd);
        return 1;
    }

    // Combine high and low bytes for each axis
    x = (int16_t)((buffer[1] << 8) | buffer[0]);
    y = (int16_t)((buffer[3] << 8) | buffer[2]);
    z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Print the acceleration values
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);

    // Close I2C bus
    close(fd);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <signal.h>
