// Define GPIO pins
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define GPIO_27 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME_MS 50

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[8];
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_button(int gpio);
void set_led(int gpio, int state);
void report_state(int gpio, int state);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to read the state of a button with debouncing
int read_button(int gpio) {
    struct timespec start, now;
    int button_state = 0;

    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        button_state = gpiod_line_get_value(lines[gpio]);
        clock_gettime(CLOCK_MONOTONIC, &now);
        double elapsed_ms = (now.tv_sec - start.tv_sec) * 1000.0 + (now.tv_nsec - start.tv_nsec) / 1000000.0;

        if (button_state == 0) {
            return 1; // Button pressed
        }

        if (elapsed_ms >= DEBOUNCE_TIME_MS) {
            return 0; // Button not pressed
        }
    }
}

// Function to set the state of an LED
void set_led(int gpio, int state) {
    int ret = gpiod_line_set_value(lines[gpio], state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %s\n", gpio, state, strerror(errno));
    }
}

// Function to report the state of an LED to standard output
void report_state(int gpio, int state) {
    printf("GPIO %d: %s\n", gpio, state ? "ON" : "OFF");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get lines for each GPIO pin
    int gpios[] = {GPIO_4, GPIO_17, GPIO_18, GPIO_22, GPIO_23, GPIO_24, GPIO_25, GPIO_27};
    for (int i = 0; i < 8; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpios[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO %d line: %s\n", gpios[i], strerror(errno));
            goto cleanup;
        }

        // Request line for output (LEDs)
        if (gpiod_line_request_output(lines[i], "led", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", gpios[i], strerror(errno));
            goto cleanup;
        }

        // Set initial state to OFF
        set_led(gpios[i], 0);
        report_state(gpios[i], 0);
    }

    // Main loop
    while (!terminate) {
        // Read button states and set LEDs accordingly
        for (int i = 0; i < 8; i++) {
            if (read_button(gpios[i])) {
                set_led(gpios[i], 1);
                report_state(gpios[i], 1);
            } else {
                set_led(gpios[i], 0);
                report_state(gpios[i], 0);
            }
        }

        // Wait for 50 milliseconds
        usleep(50000); // 50000 microseconds = 50 milliseconds
    }

cleanup:
    // Release GPIO lines and close chip
    for (int i = 0; i < 8; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

