#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 18 // BCM numbering

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int duty_cycle;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    printf("PWM control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_PIN);

    while (program_running) {
        // Generate a sequence of duty cycles (0-255)
        for (duty_cycle = 0; duty_cycle <= 255; duty_cycle++) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            fflush(stdout); // Ensure output is immediately visible
            gpioDelay(100000); // 0.1 seconds (100000 microseconds)
        }

        // Generate a sequence of duty cycles (255-0)
        for (duty_cycle = 255; duty_cycle >= 0; duty_cycle--) {
            gpioPWM(GPIO_PIN, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            fflush(stdout); // Ensure output is immediately visible
            gpioDelay(100000); // 0.1 seconds (100000 microseconds)
        }
    }

    // Clean up and terminate pigpio
    gpioPWM(GPIO_PIN, 0); // Set duty cycle to 0 before exiting
    gpioTerminate();

    printf("PWM control stopped.\n");
    return 0;
}

#include <stdio.h>
