#define GPIO_CHIP "gpiochip0"
#define GPIO_4 4
#define GPIO_17 17

struct gpiod_chip *chip;
struct gpiod_line *line4, *line17;

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", sig);
}

int main() {
    int i, ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line for GPIO 4
    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("Error getting GPIO line 4");
        gpiod_chip_close(chip);
        return 1;
    }

    // Get GPIO line for GPIO 17
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Error getting GPIO line 17");
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    ret = gpiod_line_request_output(line4, "cycle", 0); // Initial state LOW
    if (ret < 0) {
        perror("Error requesting GPIO 4 for output");
        gpiod_line_release(line17);
        gpiod_line_release(line4);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(line17, "cycle", 0); // Initial state LOW
    if (ret < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(line4);
        gpiod_line_release(line17);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO 4 and GPIO 17 are now output lines.\n");

    // Main loop for 5 cycles
    for (i = 0; i < 5 && program_running; i++) {
        // Cycle 1: GPIO 4 HIGH, GPIO 17 LOW
        printf("Cycle %d: GPIO 4 HIGH, GPIO 17 LOW\n", i + 1);
        ret = gpiod_line_set_value(line4, 1);
        if (ret < 0) {
            perror("Error setting GPIO 4 HIGH");
            program_running = 0; // Stop the program on error
        }
        ret = gpiod_line_set_value(line17, 0);
        if (ret < 0) {
            perror("Error setting GPIO 17 LOW");
            program_running = 0; // Stop the program on error
        }
        nanosleep(&sleep_time, NULL);

        // Cycle 2: GPIO 4 LOW, GPIO 17 HIGH
        printf("Cycle %d: GPIO 4 LOW, GPIO 17 HIGH\n", i + 1);
        ret = gpiod_line_set_value(line4, 0);
        if (ret < 0) {
            perror("Error setting GPIO 4 LOW");
            program_running = 0; // Stop the program on error
        }
        ret = gpiod_line_set_value(line17, 1);
        if (ret < 0) {
            perror("Error setting GPIO 17 HIGH");
            program_running = 0; // Stop the program on error
        }
        nanosleep(&sleep_time, NULL);
    }

    // Release GPIO lines and close chip
    printf("Releasing GPIO lines and closing chip.\n");
    gpiod_line_release(line4);
    gpiod_line_release(line17);
    gpiod_chip_close(chip);

    printf("Program finished.\n");
    return 0;
}

