        return -1;
    }

    *line21 = gpiod_chip_get_line(*chip, GPIO_21);
    if (!*line21) {
        perror("Error getting GPIO line 21");
        gpiod_line_release(*line17);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line17, "my_program", 0) < 0) {
        perror("Error requesting GPIO line 17 for output");
        gpiod_line_release(*line21);
        gpiod_line_release(*line17);
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_output(*line21, "my_program", 0) < 0) {
        perror("Error requesting GPIO line 21 for output");
        gpiod_line_release(*line17);
        gpiod_line_release(*line21);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Sets the state of a GPIO line
int set_gpio_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Gets the state of a GPIO line
int get_gpio_state(struct gpiod_line *line) {
    int state = gpiod_line_get_value(line);
    if (state < 0) {
        perror("Error getting GPIO line value");
        return -1;
    }
    return state;
}

// Releases GPIO lines and closes the chip
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line17, struct gpiod_line *line21) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line21) {
        gpiod_line_release(line21);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line17, &line21) != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO 17 to HIGH
        if (set_gpio_state(line17, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO 17 HIGH. Exiting.\n");
            cleanup_gpio(chip, line17, line21);
            return 1;
        }
        printf("GPIO 17 set to HIGH\n");

        // Set GPIO 21 to LOW
        if (set_gpio_state(line21, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO 21 LOW. Exiting.\n");
            cleanup_gpio(chip, line17, line21);
            return 1;
        }
        printf("GPIO 21 set to LOW\n");

        // Wait for 0.1 seconds
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 100000000; // 0.1 seconds
        nanosleep(&ts, NULL);

        // Set GPIO 17 to LOW
        if (set_gpio_state(line17, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO 17 LOW. Exiting.\n");
            cleanup_gpio(chip, line17, line21);
            return 1;
        }
        printf("GPIO 17 set to LOW\n");

        // Set GPIO 21 to HIGH
        if (set_gpio_state(line21, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO 21 HIGH. Exiting.\n");
            cleanup_gpio(chip, line17, line21);
            return 1;
        }
        printf("GPIO 21 set to HIGH\n");

        // Wait for 0.1 seconds
        nanosleep(&ts, NULL);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define PWM_GPIO 4 // BCM GPIO 4
#define PWM_FREQUENCY 1000 // 1 kHz

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    int duty_cycle;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 4 as output
    gpioSetMode(PWM_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);

    printf("PWM control started on GPIO %d (BCM). Press Ctrl+C to exit.\n", PWM_GPIO);

    while (!terminate) {
        // Generate PWM signal with varying duty cycle
        for (duty_cycle = 0; duty_cycle <= 255; duty_cycle++) {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            fflush(stdout); // Ensure output is immediately displayed
            gpioDelay(10000); // 10 ms delay (10000 microseconds)
        }

        // Reverse the duty cycle
        for (duty_cycle = 255; duty_cycle >= 0; duty_cycle--) {
            gpioPWM(PWM_GPIO, duty_cycle);
            printf("Duty Cycle: %d\n", duty_cycle);
            fflush(stdout);
            gpioDelay(10000);
        }
    }

    // Clean up and terminate pigpio
    gpioPWM(PWM_GPIO, 0); // Set duty cycle to 0 before exiting
    gpioTerminate();

    printf("PWM control stopped.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
