#include <unistd.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_18 18
#define GPIO_22 22
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", line->number, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to get the state of a GPIO pin
int get_gpio_state(struct gpiod_line *line) {
    int state = gpiod_line_get_value(line);
    if (state < 0) {
        fprintf(stderr, "Error getting GPIO %d state: %s\n", line->number, strerror(-state));
        return -1;
    }
    return state;
}

// Function to print the current state of all GPIO pins
void print_gpio_states(struct gpiod_chip *chip) {
    struct gpiod_line *line;
    int i;

    printf("GPIO States:\n");
    for (i = 0; i < chip->lines; i++) {
        line = gpiod_chip_get_line(chip, i);
        if (line == NULL) {
            fprintf(stderr, "Error getting GPIO line %d\n", i);
            continue;
        }
        int state = get_gpio_state(line);
        if (state >= 0) {
            printf("GPIO %d: %d\n", line->number, state);
        }
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int i, ret;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", CHIP_NAME, strerror(errno));
        return 1;
    }

    // Get the number of lines (GPIOs) on the chip
    int num_lines = chip->lines;

    // Iterate through the GPIO lines
    for (i = 0; i < num_lines; i++) {
        line = gpiod_chip_get_line(chip, i);
        if (!line) {
            fprintf(stderr, "Error getting GPIO line %d\n", i);
            continue;
        }

        // Check if the line number matches one of the desired GPIOs
        if (line->number == GPIO_17 || line->number == GPIO_18 || line->number == GPIO_22 || line->number == GPIO_27) {
            // Request the line for output
            ret = gpiod_line_request_output(line, "gpio_control", 0);
            if (ret < 0) {
                fprintf(stderr, "Error requesting GPIO %d for output: %s\n", line->number, strerror(-ret));
                gpiod_chip_close(chip);
                return 1;
            }

            // Set the initial state to 0
            if (set_gpio_state(line, 0) < 0) {
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                return 1;
            }
        }
    }

    // Main loop
    while (!terminate) {
        // Get current time
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Print timestamp
        printf("%s: ", timestamp);

        // Print GPIO states
        print_gpio_states(chip);

        // Toggle GPIO 17
        if (set_gpio_state(gpiod_chip_get_line(chip, (GPIO_17 - 1)), 1) < 0) {
            terminate = 1;
        }

        // Toggle GPIO 18
        if (set_gpio_state(gpiod_chip_get_line(chip, (GPIO_18 - 1)), 0) < 0) {
            terminate = 1;
        }

        // Toggle GPIO 22
        if (set_gpio_state(gpiod_chip_get_line(chip, (GPIO_22 - 1)), 1) < 0) {
            terminate = 1;
        }

        // Toggle GPIO 27
        if (set_gpio_state(gpiod_chip_get_line(chip, (GPIO_27 - 1)), 0) < 0) {
            terminate = 1;
        }

        // Wait for 0.5 seconds
        usleep(500000); // 0.5 seconds = 500000 microseconds
    }

    // Release GPIO lines
    for (i = 0; i < num_lines; i++) {
        line = gpiod_chip_get_line(chip, i);
        if (line && line->number == GPIO_17 || line->number == GPIO_18 || line->number == GPIO_22 || line->number == GPIO_27) {
            gpiod_line_release(line);
        }
    }

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated.\n");
    return 0;
}

