#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 24
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        keep_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int state;
    int ret;
    int i;

    /* Register signal handler for graceful shutdown */
    signal(SIGINT, signal_handler);

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Request the line for output */
    ret = gpiod_line_request_output(line, "output", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d for output: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    /* Main loop: toggle the GPIO state */
    while (keep_running) {
        /* Read the current state */
        state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
            break; /* Exit loop on error */
        }

        /* Toggle the state */
        state = !state;

        /* Set the new state */
        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %d to %d: %s\n", GPIO_PIN, state, strerror(errno));
            break; /* Exit loop on error */
        }

        /* Report the state */
        printf("GPIO %d set to %d\n", GPIO_PIN, state);

        /* Wait for a short period */
        usleep(500000); /* 0.5 seconds */
    }

    /* Release the GPIO line */
    gpiod_line_release(line);

    /* Close the GPIO chip */
    gpiod_chip_close(chip);

    return 0;
}

#include <stdio.h>
