// Define GPIO pins
#define GPIO_0 0
#define GPIO_1 1
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_5 5
#define GPIO_12 12
#define GPIO_17 17

// Define the number of pins
#define NUM_PINS 8

// Define the pin numbers in an array
int pins[] = {GPIO_0, GPIO_1, GPIO_2, GPIO_3, GPIO_4, GPIO_5, GPIO_12, GPIO_17};

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize a GPIO pin
int initialize_gpio(struct gpiod_chip *chip, int pin, const char *direction) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting line %d: %s\n", pin, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request_output(line, direction, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to report the state of all GPIO pins
void report_gpio_states(struct gpiod_line **lines, int num_pins) {
    printf("GPIO States: ");
    for (int i = 0; i < num_pins; i++) {
        int value = gpiod_line_get_value(lines[i]);
        if (value < 0) {
            fprintf(stderr, "Error getting line value: %s\n", strerror(errno));
            continue; // Continue to the next pin
        }
        printf("%d ", value);
    }
    printf("\n");
}

// Function to release a GPIO pin
void release_gpio(struct gpiod_line *line) {
    gpiod_line_release(line);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line **lines = NULL;
    int i;

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Allocate memory for the array of lines
    lines = (struct gpiod_line **)malloc(NUM_PINS * sizeof(struct gpiod_line *));
    if (!lines) {
        fprintf(stderr, "Error allocating memory for lines\n");
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize each GPIO pin
    for (i = 0; i < NUM_PINS; i++) {
        if (initialize_gpio(chip, pins[i], "out") < 0) {
            fprintf(stderr, "Error initializing GPIO %d\n", pins[i]);
            // Release any previously initialized lines
            for (int j = 0; j < i; j++) {
                release_gpio(lines[j]);
            }
            free(lines);
            gpiod_chip_close(chip);
            return 1;
        }
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
    }

    // Main loop
    while (!terminate) {
        // Toggle the state of each GPIO pin
        for (i = 0; i < NUM_PINS; i++) {
            int state = gpiod_line_get_value(lines[i]);
            if (state < 0) {
                fprintf(stderr, "Error getting line value for GPIO %d: %s\n", pins[i], strerror(errno));
                continue; // Skip to the next pin
            }
            state = !state; // Toggle the state
            if (set_gpio_state(lines[i], state) < 0) {
                fprintf(stderr, "Error setting GPIO %d\n", pins[i]);
            }
        }

        // Report the current state of all GPIO pins
        report_gpio_states(lines, NUM_PINS);

        // Wait for 1 second
        sleep(1);
    }

    // Release all GPIO pins
    for (i = 0; i < NUM_PINS; i++) {
        release_gpio(lines[i]);
    }

    // Free the memory allocated for the lines array
    free(lines);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated successfully.\n");
    return 0;
}

