void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        timeout_flag = 0; // Reset timeout flag on rising edge
    } else if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;
        timeout_flag = 0; // Reset timeout flag on falling edge
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for echo pulse or timeout
        timeout_flag = 0; // Reset timeout flag before each measurement
        while (pulse_width == 0 && !timeout_flag) {
            gpioDelay(1000); // Check every 1ms
            if (timeout_flag) break; // Exit if timeout occurs
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Print the distance
        printf("Distance: %.2f cm\n", distance);

        // Wait before next measurement
        gpioDelay(500000); // 0.5 seconds
    }

    // Cleanup (this part will not be reached in the infinite loop)
    gpioTerminate();
    return 0;
}

