#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25
#define GPIO_27 27

// Function to set GPIO pin state
int set_gpio_state(int pin, int state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO line direction to output
    ret = gpiod_line_request_output(line, "control", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Set GPIO pin state
    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO pin %d state to %d: %s\n", pin, state, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Release GPIO line
    gpiod_line_release(line);

    // Close GPIO chip
    gpiod_chip_close(chip);

    return 0;
}

