#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulse_duration);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to trigger the HC-SR04 sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse duration on the ECHO pin
long pulseIn(int pin, int level, int timeout) {
    long startTime = 0, endTime = 0;
    long pulseDuration = 0;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        startTime = gpioTick();
        if (startTime == 0) return 0; // Handle potential overflow
        if (startTime > timeout) return 0; // Timeout
    }

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        endTime = gpioTick();
        if (endTime == 0) return 0; // Handle potential overflow
        if (endTime > timeout) return 0; // Timeout
    }

    pulseDuration = endTime - startTime;
    return pulseDuration;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_duration) {
    return (float)pulse_duration * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_duration = pulseIn(ECHO_PIN, 1, TIMEOUT_US);

        if (pulse_duration > 0) {
            float distance = calculateDistance(pulse_duration);
            printf("Distance: %.2f cm\n", distance);
        } else {
            printf("Timeout or error: No echo received\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

