#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// Enable Register Values
#define TCS34725_ENABLE_AIEN 0x10  // ALS Interrupt Enable
#define TCS34725_ENABLE_WEN 0x08   // Wait enable - Writing 1 activates the wait timer
#define TCS34725_ENABLE_AEN 0x02   // ALS Enable
#define TCS34725_ENABLE_PON 0x01   // Power on

// Integration Time
#define TCS34725_INTEGRATIONTIME_2_4MS  0xFF   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   0xF6   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_50MS   0xEB   // 50ms  - 20 cycles   - Max Count: 20480
#define TCS34725_INTEGRATIONTIME_101MS  0xD5   // 101ms - 42 cycles   - Max Count: 43008
#define TCS34725_INTEGRATIONTIME_154MS  0xC0   // 154ms - 64 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_238MS  0x80   // 238ms - 98 cycles   - Max Count: 65535
#define TCS34725_INTEGRATIONTIME_512MS  0x00   // 512ms - 208 cycles  - Max Count: 65535

// Gain
#define TCS34725_GAIN_1X  0x00   // No gain
#define TCS34725_GAIN_4X  0x01   // 4x gain
#define TCS34725_GAIN_16X 0x02   // 16x gain
#define TCS34725_GAIN_60X 0x03   // 60x gain

// Global variables for cleanup
static int i2c_fd = -1;
static volatile sig_atomic_t keep_running = 1;

// Signal handler for Ctrl+C
void int_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    keep_running = 0;
}

// Function to write a byte to a TCS34725 register
int tcs34725_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2];
    buf[0] = TCS34725_COMMAND_BIT | reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from a TCS34725 register
int tcs34725_read_byte(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address to I2C device");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to initialize the TCS34725 sensor
int tcs34725_init(int fd)
{
    // Enable power and ALS
    if (tcs34725_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0) return -1;
    usleep(3000); // Wait for power-on (datasheet recommends at least 2.2ms)
    if (tcs34725_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) return -1;

    // Set integration time and gain (example: 2.4ms, 1x gain)
    if (tcs34725_write_byte(fd, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_2_4MS) < 0) return -1;
    if (tcs34725_write_byte(fd, TCS34725_CONTROL, TCS34725_GAIN_1X) < 0) return -1;

    return 0;
}

// Function to read RGBA values from the TCS34725 sensor
int tcs34725_read_rgba(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c)
{
    uint8_t buf[8];

    // Read all RGBA registers in one go
    if (write(fd, (uint8_t[]){TCS34725_COMMAND_BIT | TCS34725_CDATA, 0}, 2) != 2) {
        perror("Failed to write register address to I2C device");
        return -1;
    }

    if (read(fd, buf, 8) != 8) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *c = (buf[1] << 8) | buf[0];
    *r = (buf[3] << 8) | buf[2];
    *g = (buf[5] << 8) | buf[4];
    *b = (buf[7] << 8) | buf[6];

    return 0;
}

int main()
{
    const char *i2c_device = "/dev/i2c-1"; // I2C device file
    struct timespec sleep_time = {0, 500000000}; // 0.5 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, int_handler);

    // Open I2C device
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize the TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        uint16_t r, g, b, c;

        // Read RGBA values
        if (tcs34725_read_rgba(i2c_fd, &r, &g, &b, &c) == 0) {
            // Print RGBA values
            printf("R: %5u, G: %5u, B: %5u, C: %5u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read RGBA values.\n");
        }

        // Sleep for 0.5 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
        }
    }

    // Cleanup: Close I2C device
    close(i2c_fd);
    printf("Program terminated.\n");
    return 0;
}

#include <stdio.h>
