struct gpiod_line *line23;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(int gpio_pin);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio(GPIO_18);
    cleanup_gpio(GPIO_23);
    gpiod_chip_close(chip);
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    int ret;

    if (gpio_pin == GPIO_18) {
        line = line18;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, NULL, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %d\n", gpio_pin, ret);
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;
    int ret;

    if (gpio_pin == GPIO_18) {
        line = line18;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d to %d: %d\n", gpio_pin, value, ret);
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == GPIO_18) {
        line = line18;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error getting GPIO %d value: %d\n", gpio_pin, value);
        return -1;
    }

    return value;
}

// Releases a GPIO line
void cleanup_gpio(int gpio_pin) {
    struct gpiod_line *line;

    if (gpio_pin == GPIO_18) {
        line = line18;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return;
    }

    gpiod_line_release(line);
}

int main() {
    int ret;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000; // 0.01 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %d\n", -1);
        return 1;
    }

    // Get GPIO lines
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
