        fprintf(stderr, "Error getting GPIO line: %d\n", -1);
        gpiod_chip_close(chip);
        return 1;
    }

    // Initialize GPIO lines
    if (initialize_gpio(GPIO_18) < 0 || initialize_gpio(GPIO_23) < 0) {
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Toggle GPIO 18
        ret = set_gpio_value(GPIO_18, 1);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO 18, exiting.\n");
            break;
        }
        printf("GPIO 18 set to 1\n");
        nanosleep(&sleep_time, NULL);

        // Toggle GPIO 23
        ret = set_gpio_value(GPIO_23, 0);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO 23, exiting.\n");
            break;
        }
        printf("GPIO 23 set to 0\n");
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup (should not reach here if signal handler works)
    cleanup_gpio(GPIO_18);
    cleanup_gpio(GPIO_23);
    gpiod_chip_close(chip);

    return 1;
}

