#define GPIO_24 24
#define GPIO_27 27

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to set the state of a GPIO pin
int set_gpio_state(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO %d state to %d: %s\n", line->number, state, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to report the state of all GPIO pins
void report_gpio_states(struct gpiod_chip *chip) {
    int i;
    struct gpiod_line *line;
    int line_count = gpiod_chip_get_line_count(chip);

    printf("GPIO States:\n");
    for (i = 0; i < line_count; i++) {
        line = gpiod_chip_get_line(chip, i);
        if (line == NULL) {
            fprintf(stderr, "Error getting GPIO line %d\n", i);
            continue;
        }

        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error getting GPIO %d value: %s\n", line->number, strerror(-value));
            continue;
        }

        printf("GPIO %d: %d\n", line->number, value);
    }
}

