    lines[5] = gpiod_chip_get_line(chip, GPIO_24);
    lines[6] = gpiod_chip_get_line(chip, GPIO_27);

    // Check for errors getting lines
    for (i = 0; i < 7; i++) {
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO %d line\n", i + 4); // Print the actual GPIO number
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Request GPIO lines for output
    for (i = 0; i < 7; i++) {
        ret = gpiod_line_request_output(lines[i], "control", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO %d for output: %s\n", lines[i]->number, strerror(-ret));
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop
    while (!terminate) {
        // Set GPIO states
        for (i = 0; i < 7; i++) {
            ret = set_gpio_state(lines[i], i % 2); // Toggle between 0 and 1
            if (ret < 0) {
                fprintf(stderr, "Error setting GPIO %d state\n", lines[i]->number);
                break; // Exit loop if there's an error
            }
        }

        // Report GPIO states
        report_gpio_states(chip);

        // Wait for 1 second
        sleep(1);
    }

    // Release GPIO lines
    for (i = 0; i < 7; i++) {
        gpiod_line_release(lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    printf("Program terminated successfully.\n");

    return 0;
}

