int initialize_gpio(void);
int set_gpio_state(int gpio, int state);
int report_state(int gpio17_state, int gpio18_state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes the GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO line for GPIO 17
    gpio17_line = gpiod_chip_get_line(chip, GPIO_17);
    if (!gpio17_line) {
        perror("Error getting GPIO 17 line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get the GPIO line for GPIO 18
    gpio18_line = gpiod_chip_get_line(chip, GPIO_18);
    if (!gpio18_line) {
        perror("Error getting GPIO 18 line");
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(gpio17_line, "gpio17", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 17 for output");
        gpiod_line_release(gpio18_line);
        gpiod_line_release(gpio17_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio18_line, "gpio18", 0);
    if (ret < 0) {
        perror("Error requesting GPIO 18 for output");
        gpiod_line_release(gpio17_line);
        gpiod_line_release(gpio18_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Sets the state of a GPIO pin
int set_gpio_state(int gpio, int state) {
    int ret;
    struct gpiod_line *line;

    if (gpio == GPIO_17) {
        line = gpio17_line;
    } else if (gpio == GPIO_18) {
        line = gpio18_line;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio);
        return -1;
    }

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        perror("Error setting GPIO state");
        return -1;
    }

    return 0;
}

