void cleanup_gpio(void) {
    if (gpio17_line) {
        gpiod_line_release(gpio17_line);
    }
    if (gpio18_line) {
        gpiod_line_release(gpio18_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
