    int gpio17_state = 0;
    int gpio18_state = 1;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 milliseconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Set GPIO states
        if (set_gpio_state(GPIO_17, gpio17_state) < 0) {
            fprintf(stderr, "Failed to set GPIO 17 state. Exiting.\n");
            cleanup_gpio();
            return 1;
        }
        if (set_gpio_state(GPIO_18, gpio18_state) < 0) {
