#include <pigpio.h>

// Define GPIO pins for PWM output
#define PWM_PIN_2 2
#define PWM_PIN_3 3
#define PWM_PIN_18 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM duty cycle (percentage)
#define PWM_DUTY_CYCLE 50

// Global variable to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PWM_PIN_2, PI_OUTPUT);
    gpioSetMode(PWM_PIN_3, PI_OUTPUT);
    gpioSetMode(PWM_PIN_18, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(PWM_PIN_2, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_3, PWM_FREQUENCY);
    gpioSetPWMfrequency(PWM_PIN_18, PWM_FREQUENCY);

    // Set PWM duty cycle for all pins
    gpioPWM(PWM_PIN_2, PWM_DUTY_CYCLE * 255 / 100); // pigpio uses 0-255 range
    gpioPWM(PWM_PIN_3, PWM_DUTY_CYCLE * 255 / 100);
    gpioPWM(PWM_PIN_18, PWM_DUTY_CYCLE * 255 / 100);

    // Main loop
    while (!terminate) {
        // Print the current PWM state
        printf("PWM_PIN_2: %d, PWM_PIN_3: %d, PWM_PIN_18: %d\n",
               gpioGetPWMdutycycle(PWM_PIN_2),
               gpioGetPWMdutycycle(PWM_PIN_3),
               gpioGetPWMdutycycle(PWM_PIN_18));

        // Wait for 5 seconds
        sleep(5);
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();

    return 0;
}

