#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *line18, *line23, *line24;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_gpio_value(int gpio_pin, int value);
int get_gpio_value(int gpio_pin);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Initializes a GPIO line for output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error: Could not get line for GPIO %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "gpio_control", 0); // Initial value 0
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request GPIO %d as output: %s\n", gpio_pin, gpiod_line_name(line));
        return -1;
    }

    return 0;
}

// Sets the value of a GPIO line
int set_gpio_value(int gpio_pin, int value) {
    struct gpiod_line *line;
    int ret;

    if (gpio_pin == GPIO_18) {
        line = line18;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else if (gpio_pin == GPIO_24) {
        line = line24;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set value for GPIO %d: %s\n", gpio_pin, gpiod_line_name(line));
        return -1;
    }

    return 0;
}

// Gets the value of a GPIO line
int get_gpio_value(int gpio_pin) {
    struct gpiod_line *line;
    int value;

    if (gpio_pin == GPIO_18) {
        line = line18;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else if (gpio_pin == GPIO_24) {
        line = line24;
    } else {
        fprintf(stderr, "Error: Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error: Could not get value for GPIO %d: %s\n", gpio_pin, gpiod_line_name(line));
        return -1;
    }

    return value;
}

// Releases GPIO lines and unexports the chip
void cleanup_gpio(void) {
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line23) {
        gpiod_line_release(line23);
    }
    if (line24) {
        gpiod_line_release(line24);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int i;
    int gpio_pins[] = {GPIO_18, GPIO_23, GPIO_24};
    int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);
    struct timespec sleep_time = {0, 100000000}; // 0.1 seconds

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    // Initialize GPIO lines
    for (i = 0; i < num_pins; i++) {
        if (initialize_gpio(gpio_pins[i]) != 0) {
            cleanup_gpio();
            return 1;
        }
    }

    // Main loop
    while (1) {
        for (i = 0; i < num_pins; i++) {
            if (set_gpio_value(gpio_pins[i], 1) != 0) {
                cleanup_gpio();
                return 1;
            }
            printf("GPIO %d set to 1\n", gpio_pins[i]);
            nanosleep(&sleep_time, NULL);

            if (set_gpio_value(gpio_pins[i], 0) != 0) {
                cleanup_gpio();
                return 1;
            }
            printf("GPIO %d set to 0\n", gpio_pins[i]);
            nanosleep(&sleep_time, NULL);
        }
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <signal.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00; // Disable sleep mode

    if (write(i2c_fd, data, 2) != 2) {
        perror("Failed to write to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[7];
    data[0] = ACCEL_XOUT_H;

    if (write(i2c_fd, data, 1) != 1) {
        perror("Failed to write to ACCEL_XOUT_H register");
        return -1;
    }

    if (read(i2c_fd, data, 6) != 6) {
        perror("Failed to read accelerometer data");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    printf("MPU6050 initialized successfully.\n");

    // Main loop
    while (1) {
        int16_t x, y, z;

        if (read_accelerometer_data(&x, &y, &z) == 0) {
            printf("X: %d, Y: %d, Z: %d\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read accelerometer data.\n");
        }

        sleep(1);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

int main() {
    int ret;
    struct timespec sleep_time = {0, 600000000L}; // 0.6 seconds
    int current_state = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for output
    ret = gpiod_line_request(line, "output", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    printf("GPIO %d (BCM) set to output mode.\n", GPIO_PIN);

    // Main loop
    while (!terminate) {
        // Toggle GPIO state
        current_state = !current_state;
        ret = gpiod_line_set_value(line, current_state);
        if (ret < 0) {
            perror("Error setting GPIO value");
            break;
        }

        // Print current state
        printf("GPIO %d set to %d\n", GPIO_PIN, current_state);

        // Sleep for 0.6 seconds
        if (nanosleep(&sleep_time, NULL) != 0) {
            perror("nanosleep");
            break;
        }
    }

    // Release GPIO line
    gpiod_line_release(line);
    printf("GPIO %d released.\n", GPIO_PIN);

    // Close GPIO chip
    gpiod_chip_close(chip);
    printf("GPIO chip closed.\n");

    return 0;
}
